{"file_path":"<WS1>/_dev/sim.js","content":"'use strict';

/* VITARIUM — headless ecosystem core.
   Pure simulation logic: no DOM, no time, no rendering.  All stochasticity is
   drawn from one seeded stream, so one seed + one control history = one run. */

(function (root) {
  const TICKS_PER_GEN = 6;
  const CAPS = { plant: 5200, prey: 1500, pred: 340 };

  const CATS = {
    drought: { label: 'Drought', duration: 18, titre: 'Canopy arrested', detail: 'The plate dries; growth withholds.' },
    plague:  { label: 'Plague',  duration: 14, titre: 'Fever in the herd', detail: 'Crowding turns to contagion among grazers.' },
    eclipse: { label: 'Eclipse', duration: 12, titre: 'Light withdrawn', detail: 'Vision contracts; the field turns inward.' }
  };

  const DEFAULTS = {
    seed: 1931,
    width: 120,
    height: 80,
    mutationRate: 0.04,
    regrowth: 0.055,
    droughtEvery: 120,
    plagueEvery: 168,
    eclipseEvery: 216,
    enableDrought: true,
    enablePlague: true,
    enableEclipse: true,
    migration: true,
    initPlants: 2400,
    initPrey: 195,
    initPred: 26
  };

  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
  function wrap(v, n) { v %= n; return v < 0 ? v + n : v; }

  function mulberry32(a) {
    a = a >>> 0;
    return function () {
      a = (a + 0x6D2B79F5) >>> 0;
      let t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  class RNG {
    constructor(seed) {
      this._rand = mulberry32(seed || 1);
    }
    next() { return this._rand(); }
    range(a, b) { return a + (b - a) * this._rand(); }
    int(a, b) { return a + Math.floor(this._rand() * (b - a + 1)); }
    chance(p) { return this._rand() < p; }
    pick(arr) { return arr[Math.floor(this._rand() * arr.length)]; }
    gauss() {
      let u = 0, v = 0;
      while (u === 0) u = this._rand();
      while (v === 0) v = this._rand();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    }
  }

  /* Bucket hash reused every tick; kills are left in place and skipped so we
     never allocate during a tick. */
  class BucketHash {
    constructor(w, h, cell) {
      this.cell = cell;
      this.cols = Math.ceil(w / cell);
      this.rows = Math.ceil(h / cell);
      this.buckets = new Array(this.cols * this.rows);
      for (let i = 0; i < this.buckets.length; i++) this.buckets[i] = [];
    }
    clear() {
      for (let i = 0; i < this.buckets.length; i++) this.buckets[i].length = 0;
    }
    add(agent, index) {
      const cx = clamp(Math.floor(agent.x / this.cell), 0, this.cols - 1);
      const cy = clamp(Math.floor(agent.y / this.cell), 0, this.rows - 1);
      this.buckets[cy * this.cols + cx].push(index);
    }
    nearest(x, y, radius, agents, filter) {
      const minX = clamp(Math.floor((x - radius) / this.cell), 0, this.cols - 1);
      const maxX = clamp(Math.floor((x + radius) / this.cell), 0, this.cols - 1);
      const minY = clamp(Math.floor((y - radius) / this.cell), 0, this.rows - 1);
      const maxY = clamp(Math.floor((y + radius) / this.cell), 0, this.rows - 1);
      let best = null, bestD = radius * radius;
      for (let cy = minY; cy <= maxY; cy++) {
        const row = cy * this.cols;
        for (let cx = minX; cx <= maxX; cx++) {
          const bucket = this.buckets[row + cx];
          for (let k = 0; k < bucket.length; k++) {
            const a = agents[bucket[k]];
            if (!a || !a.alive || (filter && !filter(a))) continue;
            let dx = a.x - x, dy = a.y - y;
            if (dx > this.cell) dx -= this._w; else if (dx < -this.cell) dx += this._w;
            if (dy > this.cell) dy -= this._h; else if (dy < -this.cell) dy += this._h;
            const d = dx * dx + dy * dy;
            if (d < bestD) { bestD = d; best = a; }
          }
        }
      }
      if (best) {
        let dx = best.x - x, dy = best.y - y;
        if (dx > this._w / 2) dx -= this._w; else if (dx < -this._w / 2) dx += this._w;
        if (dy > this._h / 2) dy -= this._h; else if (dy < -this._h / 2) dy += this._h;
        best._dx = dx; best._dy = dy;
        return { agent: best, dist: Math.sqrt(bestD) };
      }
      return null;
    }
    bindWorld(w, h) { this._w = w; this._h = h; }
  }

  function founder(rng, base, spread) {
    return base.map(v => clamp(v + rng.gauss() * spread, 0.03, 0.97));
  }

  function mutateGenes(rng, genes, rate) {
    const out = genes.slice();
    const sd = rate * 0.45;
    for (let i = 0; i < out.length; i++) {
      out[i] = clamp(out[i] + rng.gauss() * sd, 0.015, 0.985);
    }
    return out;
  }

  function preyPheno(g) {
    return {
      speed: 0.10 + g[0] * 0.42,
      vision: 1.5 + g[1] * 10.5,
      cost: 0.62 + g[2] * 0.85,
      gain: 0.52 + g[2] * 0.58,
      threshold: 0.54 + g[3] * 0.37
    };
  }
  function predPheno(g) {
    return {
      speed: 0.13 + g[0] * 0.44,
      vision: 1.8 + g[1] * 11.0,
      cost: 0.70 + g[2] * 0.80,
      gain: 0.60 + g[2] * 0.55,
      threshold: 0.60 + g[3] * 0.32
    };
  }
  function plantPheno(g) {
    return {
      growth: 0.45 + g[0] * 1.25,
      hardy: g[1],
      range: 1 + Math.round(g[2] * 4),
      seedAt: 0.69 + g[3] * 0.22
    };
  }

  function meanSd(agents, geneCount) {
    const n = agents.length;
    const mean = new Array(geneCount).fill(null);
    const sd = new Array(geneCount).fill(null);
    if (!n) return { mean, sd };
    for (let g = 0; g < geneCount; g++) {
      let sum = 0;
      for (let i = 0; i < n; i++) sum += agents[i].genes[g];
      const m = sum / n;
      let sq = 0;
      for (let i = 0; i < n; i++) {
        const d = agents[i].genes[g] - m;
        sq += d * d;
      }
      mean[g] = m;
      sd[g] = Math.sqrt(sq / n);
    }
    return { mean, sd };
  }

  class Ecosystem {
    constructor(options) {
      this.opts = Object.assign({}, DEFAULTS, options || {});
      this.w = this.opts.width;
      this.h = this.opts.height;
      this.preyHash = new BucketHash(this.w, this.h, 6);
      this.predHash = new BucketHash(this.w, this.h, 6);
      this.preyHash.bindWorld(this.w, this.h);
      this.predHash.bindWorld(this.w, this.h);
      this.reset(this.opts.seed);
    }

    reset(seed) {
      this.seed = (seed === undefined ? this.opts.seed : seed) >>> 0;
      this.opts.seed = this.seed;
      this.gen = 0;
      this.tick = 0;
      this.rng = new RNG((this.seed ^ 0x9E3779B9) >>> 0);
      this.plants = [];
      this.prey = [];
      this.preds = [];
      this.plantGrid = new Array(this.w * this.h).fill(null);
      this.history = [];
      this.logs = [];
      this.spans = [];
      this.active = new Map();
      this.nextAt = {};
      this.zeroGens = { plant: 0, prey: 0, pred: 0 };
      this.lastRescue = { plant: -9999, prey: -9999, pred: -9999 };
      this.kills = [];
      this.extinctAnnounced = { plant: false, prey: false, pred: false };
      this._setSchedule();
      this._seedInitial();
      this._sample();
    }

    _setSchedule() {
      const o = this.opts;
      this.nextAt.drought = o.enableDrought && o.droughtEvery > 0 ? o.droughtEvery : Infinity;
      this.nextAt.plague = o.enablePlague && o.plagueEvery > 0 ? o.plagueEvery : Infinity;
      this.nextAt.eclipse = o.enableEclipse && o.eclipseEvery > 0 ? o.eclipseEvery : Infinity;
    }

    setMutationRate(v) {
      this.opts.mutationRate = clamp(Number(v) || 0, 0, 0.2);
    }

    setRegrowth(v) {
      this.opts.regrowth = clamp(Number(v) || 0.001, 0.005, 0.2);
    }

    setEnabled(type, enabled) {
      const key = type === 'drought' ? 'enableDrought' : type === 'plague' ? 'enablePlague' : 'enableEclipse';
      this.opts[key] = !!enabled;
      const every = type === 'drought' ? 'droughtEvery' : type === 'plague' ? 'plagueEvery' : 'eclipseEvery';
      this.nextAt[type] = enabled && this.opts[every] > 0 ? this.gen + this.opts[every] : Infinity;
    }

    setInterval(type, value) {
      const every = type === 'drought' ? 'droughtEvery' : type === 'plague' ? 'plagueEvery' : 'eclipseEvery';
      this.opts[every] = Math.max(0, Math.round(value));
      const enabled = type === 'drought' ? this.opts.enableDrought : type === 'plague' ? this.opts.enablePlague : this.opts.enableEclipse;
      this.nextAt[type] = enabled && this.opts[every] > 0 ? this.gen + this.opts[every] : Infinity;
    }

    setMigration(enabled) {
      this.opts.migration = !!enabled;
    }

    getActive(type) {
      return this.active.get(type) || null;
    }

    visionFactor() {
      return this.active.has('eclipse') ? 0.34 : 1;
    }

    /* ---------- seeding ---------- */

    _seedInitial() {
      const o = this.opts;
      const rng = this.rng;
      const plantBase = [0.55, 0.52, 0.5, 0.58];
      const plantCount = Math.min(o.initPlants, this.w * this.h);
      for (let i = 0; i < plantCount; i++) {
        let x, y, tries = 0;
        do {
          x = rng.int(0, this.w - 1);
          y = rng.int(0, this.h - 1);
          tries++;
        } while (this.plantGrid[y * this.w + x] && tries < 24);
        if (!this.plantGrid[y * this.w + x]) {
          this._addPlant(x, y, rng.range(0.28, 0.72), founder(rng, plantBase, 0.11));
        }
      }
      const preyBase = [0.48, 0.5, 0.48, 0.55];
      for (let i = 0; i < o.initPrey; i++) {
        this._addPrey(rng.range(0, this.w), rng.range(0, this.h), rng.range(0.38, 0.62),
          founder(rng, preyBase, 0.13), rng.range(0, Math.PI * 2));
      }
      const predBase = [0.62, 0.62, 0.5, 0.6];
      for (let i = 0; i < o.initPred; i++) {
        this._addPred(rng.range(0, this.w), rng.range(0, this.h), rng.range(0.55, 0.8),
          founder(rng, predBase, 0.11), rng.range(0, Math.PI * 2));
      }
      this._log(0, 'seal', 'Plate sealed',
        `${this.plants.length.toLocaleString()} rosettes · ${this.prey.length} grazers · ${this.preds.length} hunters`);
    }

    _addPlant(x, y, e, genes) {
      if (this.plants.length >= CAPS.plant) return null;
      const idx = wrap(y, this.h) * this.w + wrap(x, this.w);
      if (this.plantGrid[idx]) return null;
      const plant = { x: wrap(x, this.w), y: wrap(y, this.h), e, age: 0, genes, alive: true };
      this.plants.push(plant);
      this.plantGrid[idx] = plant;
      return plant;
    }

    _addPrey(x, y, e, genes, heading) {
      if (this.prey.length >= CAPS.prey) return null;
      const a = {
        x: wrap(x, this.w), y: wrap(y, this.h), px: wrap(x, this.w), py: wrap(y, this.h),
        heading: heading || 0, e, age: 0, cool: 0, genes, ph: preyPheno(genes), alive: true
      };
      this.prey.push(a);
      return a;
    }

    _addPred(x, y, e, genes, heading) {
      if (this.preds.length >= CAPS.pred) return null;
      const a = {
        x: wrap(x, this.w), y: wrap(y, this.h), px: wrap(x, this.w), py: wrap(y, this.h),
        heading: heading || 0, e, age: 0, cool: 0, digest: 0, genes, ph: predPheno(genes), alive: true
      };
      this.preds.push(a);
      return a;
    }

    /* ---------- world helpers ---------- */

    plantAt(x, y) {
      return this.plantGrid[wrap(Math.floor(y), this.h) * this.w + wrap(Math.floor(x), this.w)] || null;
    }

    _removePlant(plant) {
      if (!plant.alive) return;
      plant.alive = false;
      const idx = plant.y * this.w + plant.x;
      if (this.plantGrid[idx] === plant) this.plantGrid[idx] = null;
    }

    _plantsAround(x, y) {
      let n = 0;
      for (let oy = -1; oy <= 1; oy++) {
        for (let ox = -1; ox <= 1; ox++) {
          if (!ox && !oy) continue;
          if (this.plantGrid[wrap(y + oy, this.h) * this.w + wrap(x + ox, this.w)]) n++;
        }
      }
      return n;
    }

    _findForage(x, y, radius) {
      let best = null, bestD = Infinity;
      const rings = Math.min(6, Math.max(1, Math.ceil(radius * 0.72)));
      for (let r = 1; r <= rings; r++) {
        for (let k = 0; k < 8; k++) {
          const angle = k * Math.PI / 4 + (r % 2) * 0.18;
          const px = x + Math.cos(angle) * r;
          const py = y + Math.sin(angle) * r;
          const plant = this.plantAt(px, py);
          if (plant && plant.e > 0.06) {
            let dx = px - x, dy = py - y;
            if (dx > this.w / 2) dx -= this.w; else if (dx < -this.w / 2) dx += this.w;
            if (dy > this.h / 2) dy -= this.h; else if (dy < -this.h / 2) dy += this.h;
            const d = dx * dx + dy * dy;
            if (d < bestD) { bestD = d; best = { x: x + dx, y: y + dy, dx, dy, d }; }
          }
        }
        if (best && r >= 2) break;
      }
      return best;
    }

    _turnToward(agent, desired, rate) {
      let d = desired - agent.heading;
      while (d > Math.PI) d -= Math.PI * 2;
      while (d < -Math.PI) d += Math.PI * 2;
      agent.heading += clamp(d, -rate, rate);
    }

    /* ---------- catastrophes ---------- */

    _beginGeneration() {
      for (const [type, span] of Array.from(this.active.entries())) {
        if (this.gen >= span.end) {
          this.active.delete(type);
          this._log(this.gen, 'end', `${CATS[type].label} lifted`, `The plate returns to its ordinary weather.`);
        }
      }
      for (const type of ['drought', 'plague', 'eclipse']) {
        if (this.active.has(type)) continue;
        if (this.nextAt[type] !== Infinity && this.gen >= this.nextAt[type]) {
          const span = { type, start: this.gen, end: this.gen + CATS[type].duration };
          this.active.set(type, span);
          this.spans.push(span);
          if (type === 'eclipse') this.nextAt[type] = this.gen + this.opts.eclipseEvery;
          else if (type === 'plague') this.nextAt[type] = this.gen + this.opts.plagueEvery;
          else this.nextAt[type] = this.gen + this.opts.droughtEvery;
          this._log(this.gen, 'start', CATS[type].label, CATS[type].detail, type);
        }
      }
    }

    _endGeneration() {
      this._updatePlants();
      if (this.opts.migration) this._refugium();
      this._compact();
      this._sample();
      if (this.gen === 1 || this.gen % 25 === 0) this._refreshHashesForInspection();
    }

    _refreshHashesForInspection() { /* hashes are rebuilt per tick; no-op placeholder */ }

    _updatePlants() {
      const o = this.opts;
      const drought = this.active.has('drought');
      const eclipse = this.active.has('eclipse');
      const growMult = (drought ? 0.2 : 1) * (eclipse ? 0.58 : 1);
      for (let i = 0; i < this.plants.length; i++) {
        const p = this.plants[i];
        if (!p.alive) continue;
        p.age++;
        const ph = plantPheno(p.genes);
        const crowd = this._plantsAround(p.x, p.y);
        let growth = o.regrowth * ph.growth * (0.35 + 0.65 * (1 - p.e)) * (1 - Math.min(0.72, crowd * 0.085)) * growMult;
        p.e = Math.min(1, p.e + growth);
        let death = 0.0018 + Math.max(0, p.age - 150) * 0.00008 + crowd * 0.00035;
        if (drought) death += 0.003 + (1 - ph.hardy) * 0.02;
        if (this.rng.chance(death)) { this._removePlant(p); continue; }
        if (p.e >= ph.seedAt) this._seedPlant(p, ph, crowd);
      }
      // remove eaten / dead plants
      let write = 0;
      for (let i = 0; i < this.plants.length; i++) {
        const p = this.plants[i];
        if (p.alive && p.e > 0.01) this.plants[write++] = p;
        else if (p.alive) this._removePlant(p);
      }
      this.plants.length = write;
    }

    _seedPlant(parent, ph, crowd) {
      if (this.plants.length >= CAPS.plant) return;
      const attempts = 8 + ph.range * 2;
      for (let i = 0; i < attempts; i++) {
        const angle = this.rng.range(0, Math.PI * 2);
        const radius = this.rng.int(1, ph.range);
        const x = wrap(parent.x + Math.round(Math.cos(angle) * radius), this.w);
        const y = wrap(parent.y + Math.round(Math.sin(angle) * radius), this.h);
        if (!this.plantGrid[y * this.w + x]) {
          const genes = mutateGenes(this.rng, parent.genes, this.opts.mutationRate);
          const child = this._addPlant(x, y, 0.24 + 0.08 * (1 - ph.range / 5), genes);
          if (child) {
            parent.e -= 0.34;
            return;
          }
        }
      }
    }

    /* ---------- fauna ---------- */

    _rebuildHashes() {
      this.preyHash.clear();
      this.predHash.clear();
      for (let i = 0; i < this.prey.length; i++) if (this.prey[i].alive) this.preyHash.add(this.prey[i], i);
      for (let i = 0; i < this.preds.length; i++) if (this.preds[i].alive) this.predHash.add(this.preds[i], i);
    }

    _tickPrey(a) {
      const ph = a.ph;
      const vf = this.visionFactor();
      const vision = ph.vision * vf;
      a.age++;
      if (a.cool > 0) a.cool--;
      const cost = (0.0017 + ph.speed * 0.00155 + ph.vision * 0.00044) * ph.cost * (this.active.has('plague') ? 1.06 : 1);
      a.e -= cost;
      if (a.e <= 0) { a.alive = false; return; }

      const threat = this.predHash.nearest(a.x, a.y, Math.min(vision, 8), this.preds);
      let desired = a.heading;
      let urgency = 0;
      if (threat) {
        const dx = threat.agent._dx;
        const dy = threat.agent._dy;
        desired = Math.atan2(-dy, -dx);
        urgency = 1;
        // a frightened grazer turns hard and sprints
      } else if (a.e < ph.threshold + 0.12) {
        const forage = this._findForage(a.x, a.y, vision);
        if (forage) {
          desired = Math.atan2(forage.dy, forage.dx);
          urgency = 0.35;
        } else {
          desired = a.heading + this.rng.gauss() * 0.55;
        }
      } else {
        desired = a.heading + this.rng.gauss() * 0.42;
      }
      const turnRate = 0.18 + ph.speed * 0.8 + urgency * 0.22;
      this._turnToward(a, desired, turnRate);
      a.px = a.x; a.py = a.y;
      const sprint = urgency ? 1.16 : 1;
      a.x = wrap(a.x + Math.cos(a.heading) * ph.speed * sprint, this.w);
      a.y = wrap(a.y + Math.sin(a.heading) * ph.speed * sprint, this.h);

      // graze from the cell underfoot
      const plant = this.plantAt(a.x, a.y);
      if (plant && plant.e > 0.04) {
        const bite = Math.min(plant.e, 0.034);
        plant.e -= bite;
        a.e = Math.min(1, a.e + bite * ph.gain);
        if (plant.e <= 0.02) this._removePlant(plant);
      }

      if (a.e >= ph.threshold && a.age > 20 && a.cool <= 0 && this.prey.length < CAPS.prey) {
        const invest = 0.17 + 0.19 * ph.threshold;
        if (a.e - invest > 0.12) {
          a.e -= invest;
          a.cool = 18;
          const genes = mutateGenes(this.rng, a.genes, this.opts.mutationRate);
          const child = this._addPrey(
            wrap(a.x + this.rng.gauss() * 0.7, this.w),
            wrap(a.y + this.rng.gauss() * 0.7, this.h),
            invest * 0.92,
            genes,
            this.rng.range(0, Math.PI * 2)
          );
          if (child) child.cool = 18;
        }
      }
    }

    _tickPred(a) {
      const ph = a.ph;
      const vf = this.visionFactor();
      a.age++;
      if (a.cool > 0) a.cool--;
      if (a.digest > 0) a.digest--;
      a.e -= (0.0022 + ph.speed * 0.00165 + ph.vision * 0.0005) * ph.cost;
      if (a.e <= 0) { a.alive = false; return; }

      let desired = a.heading;
      let spotted = null;
      if (a.digest <= 0) {
        spotted = this.preyHash.nearest(a.x, a.y, ph.vision * vf, this.prey, p => p.alive);
      }
      let sprint = 1;
      if (spotted) {
        const dx = spotted.agent._dx;
        const dy = spotted.agent._dy;
        desired = Math.atan2(dy, dx);
        if (spotted.dist < 2.5) sprint = 1.22;
        if (spotted.dist < 0.62) {
          const victim = spotted.agent;
          victim.alive = false;
          a.e = Math.min(1, a.e + 0.22 + 0.24 * victim.e);
          a.digest = 11;
          this.kills.push({ x: victim.x, y: victim.y, gen: this.gen, seed: this.rng.next() });
          if (this.kills.length > 48) this.kills.shift();
        }
      } else {
        desired = a.heading + this.rng.gauss() * (a.digest > 0 ? 0.25 : 0.6);
      }
      this._turnToward(a, desired, 0.2 + ph.speed * 0.7);
      a.px = a.x; a.py = a.y;
      a.x = wrap(a.x + Math.cos(a.heading) * ph.speed * sprint, this.w);
      a.y = wrap(a.y + Math.sin(a.heading) * ph.speed * sprint, this.h);

      if (a.e >= ph.threshold && a.age > 32 && a.cool <= 0 && this.prey.length < CAPS.prey && this.preds.length < CAPS.pred) {
        const invest = 0.19 + 0.16 * ph.threshold;
        if (a.e - invest > 0.15) {
          a.e -= invest;
          a.cool = 26;
          const genes = mutateGenes(this.rng, a.genes, this.opts.mutationRate);
          const child = this._addPred(
            wrap(a.x + this.rng.gauss() * 0.9, this.w),
            wrap(a.y + this.rng.gauss() * 0.9, this.h),
            invest * 0.9,
