      if (!plant.alive) return;
      plant.alive = false;
      const idx = plant.y * this.w + plant.x;
      if (this.plantGrid[idx] === plant) this.plantGrid[idx] = null;
    }

    _plantsAround(x, y) {
      let n = 0;
      for (let oy = -1; oy <= 1; oy++) {
        for (let ox = -1; ox <= 1; ox++) {
          if (!ox && !oy) continue;
          if (this.plantGrid[wrap(y + oy, this.h) * this.w + wrap(x + ox, this.w)]) n++;
        }
      }
      return n;
    }

    _findForage(x, y, radius) {
      let best = null, bestD = Infinity;
      const rings = Math.min(6, Math.max(1, Math.ceil(radius * 0.72)));
      for (let r = 1; r <= rings; r++) {
        for (let k = 0; k < 8; k++) {
          const angle = k * Math.PI / 4 + (r % 2) * 0.18;
          const px = x + Math.cos(angle) * r;
          const py = y + Math.sin(angle) * r;
          const plant = this.plantAt(px, py);
          if (plant && plant.e > 0.06) {
            let dx = px - x, dy = py - y;
            if (dx > this.w / 2) dx -= this.w; else if (dx < -this.w / 2) dx += this.w;
            if (dy > this.h / 2) dy -= this.h; else if (dy < -this.h / 2) dy += this.h;
            const d = dx * dx + dy * dy;
            if (d < bestD) { bestD = d; best = { x: x + dx, y: y + dy, dx, dy, d }; }
          }
        }
        if (best && r >= 2) break;
      }
      return best;
    }

    _turnToward(agent, desired, rate) {
      let d = desired - agent.heading;
      while (d > Math.PI) d -= Math.PI * 2;
      while (d < -Math.PI) d += Math.PI * 2;
      agent.heading += clamp(d, -rate, rate);
    }

    /* ---------- catastrophes ---------- */

    _beginGeneration() {
      for (const [type, span] of Array.from(this.active.entries())) {
        if (this.gen >= span.end) {
          this.active.delete(type);
          this._log(this.gen, 'end', `${CATS[type].label} lifted`, `The plate returns to its ordinary weather.`);
        }
      }
      for (const type of ['drought', 'plague', 'eclipse']) {
        if (this.active.has(type)) continue;
        if (this.nextAt[type] !== Infinity && this.gen >= this.nextAt[type]) {
          const span = { type, start: this.gen, end: this.gen + CATS[type].duration };
          this.active.set(type, span);
          this.spans.push(span);
          if (type === 'eclipse') this.nextAt[type] = this.gen + this.opts.eclipseEvery;
          else if (type === 'plague') this.nextAt[type] = this.gen + this.opts.plagueEvery;
          else this.nextAt[type] = this.gen + this.opts.droughtEvery;
          this._log(this.gen, 'start', CATS[type].label, CATS[type].detail, type);
        }
      }
    }

    _endGeneration() {
      this._updatePlants();
      if (this.opts.migration) this._refugium();
      this._compact();
      this._sample();
      if (this.gen === 1 || this.gen % 25 === 0) this._refreshHashesForInspection();
    }

    _refreshHashesForInspection() { /* hashes are rebuilt per tick; no-op placeholder */ }

    _updatePlants() {
      const o = this.opts;
      const drought = this.active.has('drought');
      const eclipse = this.active.has('eclipse');
      const growMult = (drought ? 0.2 : 1) * (eclipse ? 0.58 : 1);
      for (let i = 0; i < this.plants.length; i++) {
        const p = this.plants[i];
        if (!p.alive) continue;
        p.age++;
        const ph = plantPheno(p.genes);
        const crowd = this._plantsAround(p.x, p.y);
        let growth = o.regrowth * ph.growth * (0.35 + 0.65 * (1 - p.e)) * (1 - Math.min(0.72, crowd * 0.085)) * growMult;
        p.e = Math.min(1, p.e + growth);
        let death = 0.0018 + Math.max(0, p.age - 150) * 0.00008 + crowd * 0.00035;
        if (drought) death += 0.003 + (1 - ph.hardy) * 0.02;
        if (this.rng.chance(death)) { this._removePlant(p); continue; }
        if (p.e >= ph.seedAt) this._seedPlant(p, ph, crowd);
      }
      // remove eaten / dead plants
      let write = 0;
      for (let i = 0; i < this.plants.length; i++) {
        const p = this.plants[i];
        if (p.alive && p.e > 0.01) this.plants[write++] = p;
        else if (p.alive) this._removePlant(p);
      }
      this.plants.length = write;
    }

    _seedPlant(parent, ph, crowd) {
      if (this.plants.length >= CAPS.plant) return;
      const attempts = 8 + ph.range * 2;
      for (let i = 0; i < attempts; i++) {
        const angle = this.rng.range(0, Math.PI * 2);
        const radius = this.rng.int(1, ph.range);
        const x = wrap(parent.x + Math.round(Math.cos(angle) * radius), this.w);
        const y = wrap(parent.y + Math.round(Math.sin(angle) * radius), this.h);
        if (!this.plantGrid[y * this.w + x]) {
          const genes = mutateGenes(this.rng, parent.genes, this.opts.mutationRate);
          const child = this._addPlant(x, y, 0.24 + 0.08 * (1 - ph.range / 5), genes);
          if (child) {
            parent.e -= 0.34;
            return;
          }
        }
      }
    }

    /* ---------- fauna ---------- */

    _rebuildHashes() {
      this.preyHash.clear();
      this.predHash.clear();
      for (let i = 0; i < this.prey.length; i++) if (this.prey[i].alive) this.preyHash.add(this.prey[i], i);
      for (let i = 0; i < this.preds.length; i++) if (this.preds[i].alive) this.predHash.add(this.preds[i], i);
    }

    _tickPrey(a) {
      const ph = a.ph;
      const vf = this.visionFactor();
      const vision = ph.vision * vf;
      a.age++;
      if (a.cool > 0) a.cool--;
      const cost = (0.0017 + ph.speed * 0.00155 + ph.vision * 0.00044) * ph.cost * (this.active.has('plague') ? 1.06 : 1);
      a.e -= cost;
      if (a.e <= 0) { a.alive = false; return; }

      const threat = this.predHash.nearest(a.x, a.y, Math.min(vision, 8), this.preds);
      let desired = a.heading;
      let urgency = 0;
      if (threat) {
        const dx = threat.agent._dx;
        const dy = threat.agent._dy;
        desired = Math.atan2(-dy, -dx);
        urgency = 1;
        // a frightened grazer turns hard and sprints
      } else if (a.e < ph.threshold + 0.12) {
        const forage = this._findForage(a.x, a.y, vision);
        if (forage) {
          desired = Math.atan2(forage.dy, forage.dx);
          urgency = 0.35;
        } else {
          desired = a.heading + this.rng.gauss() * 0.55;
        }
      } else {
        desired = a.heading + this.rng.gauss() * 0.42;
      }
      const turnRate = 0.18 + ph.speed * 0.8 + urgency * 0.22;
      this._turnToward(a, desired, turnRate);
      a.px = a.x; a.py = a.y;
      const sprint = urgency ? 1.16 : 1;
      a.x = wrap(a.x + Math.cos(a.heading) * ph.speed * sprint, this.w);
      a.y = wrap(a.y + Math.sin(a.heading) * ph.speed * sprint, this.h);

      // graze from the cell underfoot
      const plant = this.plantAt(a.x, a.y);
      if (plant && plant.e > 0.04) {
        const bite = Math.min(plant.e, 0.034);
        plant.e -= bite;
        a.e = Math.min(1, a.e + bite * ph.gain);
        if (plant.e <= 0.02) this._removePlant(plant);
      }

      if (a.e >= ph.threshold && a.age > 20 && a.cool <= 0 && this.prey.length < CAPS.prey) {
        const invest = 0.17 + 0.19 * ph.threshold;
        if (a.e - invest > 0.12) {
          a.e -= invest;
          a.cool = 18;
          const genes = mutateGenes(this.rng, a.genes, this.opts.mutationRate);
          const child = this._addPrey(
            wrap(a.x + this.rng.gauss() * 0.7, this.w),
            wrap(a.y + this.rng.gauss() * 0.7, this.h),
            invest * 0.92,
            genes,
            this.rng.range(0, Math.PI * 2)
          );
          if (child) child.cool = 18;
        }
      }
    }

    _tickPred(a) {
      const ph = a.ph;
      const vf = this.visionFactor();
      a.age++;
      if (a.cool > 0) a.cool--;
      if (a.digest > 0) a.digest--;
      a.e -= (0.0022 + ph.speed * 0.00165 + ph.vision * 0.0005) * ph.cost;
      if (a.e <= 0) { a.alive = false; return; }

      let desired = a.heading;
      let spotted = null;
      if (a.digest <= 0) {
        spotted = this.preyHash.nearest(a.x, a.y, ph.vision * vf, this.prey, p => p.alive);
      }
      let sprint = 1;
      if (spotted) {
        const dx = spotted.agent._dx;
        const dy = spotted.agent._dy;
        desired = Math.atan2(dy, dx);
        if (spotted.dist < 2.5) sprint = 1.22;
        if (spotted.dist < 0.62) {
          const victim = spotted.agent;
          victim.alive = false;
          a.e = Math.min(1, a.e + 0.22 + 0.24 * victim.e);
          a.digest = 11;
          this.kills.push({ x: victim.x, y: victim.y, gen: this.gen, seed: this.rng.next() });
          if (this.kills.length > 48) this.kills.shift();
        }
      } else {
        desired = a.heading + this.rng.gauss() * (a.digest > 0 ? 0.25 : 0.6);
      }
      this._turnToward(a, desired, 0.2 + ph.speed * 0.7);
      a.px = a.x; a.py = a.y;
      a.x = wrap(a.x + Math.cos(a.heading) * ph.speed * sprint, this.w);
      a.y = wrap(a.y + Math.sin(a.heading) * ph.speed * sprint, this.h);

      if (a.e >= ph.threshold && a.age > 32 && a.cool <= 0 && this.prey.length < CAPS.prey && this.preds.length < CAPS.pred) {
        const invest = 0.19 + 0.16 * ph.threshold;
        if (a.e - invest > 0.15) {
          a.e -= invest;
          a.cool = 26;
          const genes = mutateGenes(this.rng, a.genes, this.opts.mutationRate);
          const child = this._addPred(
            wrap(a.x + this.rng.gauss() * 0.9, this.w),
            wrap(a.y + this.rng.gauss() * 0.9, this.h),
            invest * 0.9,
            genes,
            this.rng.range(0, Math.PI * 2)
          );
          if (child) child.cool = 26;
        }
      }
    }

    _compact() {
      let wp = 0;
      for (let i = 0; i < this.prey.length; i++) if (this.prey[i].alive) this.prey[wp++] = this.prey[i];
      this.prey.length = wp;
      let wq = 0;
      for (let i = 0; i < this.preds.length; i++) if (this.preds[i].alive) this.preds[wq++] = this.preds[i];
      this.preds.length = wq;
    }

    _refugium() {
      const g = this.gen;
      const counts = { plant: this.plants.length, prey: this.prey.length, pred: this.preds.length };
      for (const s of ['plant', 'prey', 'pred']) {
        if (counts[s] === 0) this.zeroGens[s]++; else this.zeroGens[s] = 0;
      }
      if (g < 18) return;
      const plantBase = [0.55, 0.52, 0.5, 0.58];
      const preyBase = [0.48, 0.5, 0.48, 0.55];
      const predBase = [0.62, 0.62, 0.5, 0.6];
      if (this.zeroGens.plant >= 2 && g - this.lastRescue.plant > 60) {
        let added = 0;
        for (let i = 0; i < 120; i++) {
          const x = this.rng.int(0, this.w - 1), y = this.rng.int(0, this.h - 1);
          if (!this.plantGrid[y * this.w + x]) {
            if (this._addPlant(x, y, 0.3, founder(this.rng, plantBase, 0.12))) added++;
          }
        }
        if (added) {
          this.lastRescue.plant = g;
          this._log(g, 'migration', 'Spore drift', `${added} rosettes enter on the westerly.`);
        }
      }
      if (this.zeroGens.prey >= 2 && this.plants.length > 90 && g - this.lastRescue.prey > 60) {
        let added = 0;
        for (let i = 0; i < 10; i++) {
          const edge = this.rng.int(0, 3);
          const x = edge < 2 ? 1 : this.rng.int(0, this.w - 1);
          const y = edge >= 2 ? 1 : this.rng.int(0, this.h - 1);
          if (this._addPrey(x, y, 0.55, founder(this.rng, preyBase, 0.13), this.rng.range(0, Math.PI * 2))) added++;
        }
        if (added) {
          this.lastRescue.prey = g;
          this._log(g, 'migration', 'Grazers return', `${added} grazers cross the margin.`);
        }
      }
      if (this.zeroGens.pred >= 2 && this.prey.length > 36 && g - this.lastRescue.pred > 60) {
        let added = 0;
        for (let i = 0; i < 4; i++) {
          const edge = this.rng.int(0, 3);
          const x = edge < 2 ? this.w - 2 : this.rng.int(0, this.w - 1);
          const y = edge >= 2 ? this.h - 2 : this.rng.int(0, this.h - 1);
          if (this._addPred(x, y, 0.7, founder(this.rng, predBase, 0.11), this.rng.range(0, Math.PI * 2))) added++;
        }
        if (added) {
          this.lastRescue.pred = g;
          this._log(g, 'migration', 'Hunters return', `${added} hunters slip in from the north.`);
        }
      }
    }

    _sample() {
      const plant = meanSd(this.plants, 4);
      const prey = meanSd(this.prey, 4);
      const pred = meanSd(this.preds, 4);
      this.history.push({
        gen: this.gen,
        counts: { plant: this.plants.length, prey: this.prey.length, pred: this.preds.length },
        traits: { plant, prey, pred },
        active: Array.from(this.active.keys())
      });
    }

    _log(gen, kind, title, detail, catastrophe) {
      this.logs.push({ gen, kind, title, detail, catastrophe: catastrophe || null });
      if (this.logs.length > 400) this.logs.splice(0, this.logs.length - 400);
    }

    /* Advance one generation: six action ticks, then the botanical cycle. */
    stepGeneration() {
      this.gen++;
      this._beginGeneration();
      for (let t = 0; t < TICKS_PER_GEN; t++) {
        this.tick++;
        this._rebuildHashes();
        const nPrey = this.prey.length;
        for (let i = 0; i < nPrey; i++) if (this.prey[i].alive) this._tickPrey(this.prey[i]);
        const nPred = this.preds.length;
        for (let i = 0; i < nPred; i++) if (this.preds[i].alive) this._tickPred(this.preds[i]);
      }
      this._endGeneration();
      return this.gen;
    }

    runHeadless(n) {
      for (let i = 0; i < n; i++) this.stepGeneration();
      return this.gen;
    }

    snapshot() {
      return {
        gen: this.gen,
        counts: { plant: this.plants.length, prey: this.prey.length, pred: this.preds.length },
        active: Array.from(this.active.keys()),
        catastropheSpans: this.spans.map(s => ({ type: s.type, start: s.start, end: s.end })),
        historyLength: this.history.length
      };
    }
  }

  const api = { Ecosystem, TICKS_PER_GEN, CAPS, CATS, DEFAULTS, mulberry32, mutateGenes };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  root.VitariumCore = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);
"}

