{"content":"'use strict';
const { Ecosystem } = require('./sim.js');

function fmt(arr) { return arr.map(v => v == null ? '  .  ' : v.toFixed(2)).join(' '); }

const seed = Number(process.argv[2] || 1931);
const gens = Number(process.argv[3] || 480);
const quiet = process.argv.includes('--quiet');
const e = new Ecosystem({ seed });
const t0 = Date.now();
for (let g = 0; g <= gens; g++) {
  if (!quiet && g % 20 === 0) {
    const h = e.history[e.history.length - 1];
    const active = h.active.length ? h.active.join(',') : '—';
    console.log(
      String(g).padStart(4), 'P', String(h.counts.plant).padStart(4),
      'H', String(h.counts.prey).padStart(4),
      'C', String(h.counts.pred).padStart(3),
      '| prey μ', fmt(h.traits.prey.mean),
      '| pred μ', fmt(h.traits.pred.mean),
      '|', active
    );
  }
  if (g < gens) e.stepGeneration();
}
const ms = Date.now() - t0;
const h = e.history[e.history.length - 1];
const all = {
  seed, gen: e.gen, ms,
  final: h.counts,
  events: e.spans.map(s => `${s.type}:${s.start}-${s.end}`),
  logs: e.logs.filter(l => l.kind !== 'start' && l.kind !== 'end').slice(-8).map(l => `${l.gen}:${l.title}`),
  pop: e.history.filter((_, i) => i % 60 === 0).map(x => x.counts),
  preyMean: h.traits.prey.mean,
  predMean: h.traits.pred.mean,
  plantMean: h.traits.plant.mean,
  preySd: h.traits.prey.sd,
};
console.log(JSON.stringify(all, null, 2));
