_endGeneration() {
  this._updatePlants();
  this._compact();
  this._crowding();
  if (this.opts.migration) this._refugium();
  this._noteExtinctions();
  this._sample();
}

// Crowding fever: at unnaturally high densities, a little extra mortality
// keeps boom years from sterilising the plate.  It is an ordinary
// density-dependent check, not a global population clamp.
_crowding() {
  const preyCrowd = Math.min(0.05, Math.max(0, this.prey.length - 520) * 0.000075);
  if (preyCrowd > 0) {
    for (let i = 0; i < this.prey.length; i++) {
      if (this.prey[i].alive && this.rng.chance(preyCrowd)) this.prey[i].alive = false;
    }
  }
  const predCrowd = Math.min(0.055, Math.max(0, this.preds.length - 45) * 0.00048);
  if (predCrowd > 0) {
    for (let i = 0; i < this.preds.length; i++) {
      if (this.preds[i].alive && this.rng.chance(predCrowd)) this.preds[i].alive = false;
    }
  }
  let wp = 0;
  for (let i = 0; i < this.prey.length; i++) if (this.prey[i].alive) this.prey[wp++] = this.prey[i];
  this.prey.length = wp;
  let wq = 0;
  for (let i = 0; i < this.preds.length; i++) if (this.preds[i].alive) this.preds[wq++] = this.preds[i];
  this.preds.length = wq;
}

