const fs=require('fs'), vm=require('vm');
const base=fs.readFileSync('_dev/sim.js','utf8');
function load(transform){
  let src=transform?transform(base):base;
  const ctx={module:{exports:{}},console};
  vm.createContext(ctx); vm.runInContext(src,ctx);
  return ctx.VitariumCore.Ecosystem;
}
const variants={
  base: s=>s,
  predCheap: s=>s.replace("a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost;", "a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost * 0.7;"),
  predCheap2: s=>s.replace("a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost;", "a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost * 0.5;"),
  predCheapLowCrowd: s=>s.replace("a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost;", "a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost * 0.7;").replace("0.00048);", "0.00030);"),
  predCheapBrowse: s=>s.replace("a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost;", "a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost * 0.7;").replace("a.e = Math.min(1, a.e + bite * 0.32 * ph.gain);", "a.e = Math.min(1, a.e + bite * 0.6 * ph.gain);"),
  preySlow: s=>s.replace("a.cool = 28;", "a.cool = 38;").replace("0.24 + 0.55 * ph.threshold", "0.18 + 0.5 * ph.threshold"),
  predCheapPreySlow: s=>s.replace("a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost;", "a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost * 0.7;").replace("a.cool = 28;", "a.cool = 38;").replace("0.24 + 0.55 * ph.threshold", "0.18 + 0.5 * ph.threshold"),
  predCheapRegrow: s=>s.replace("a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost;", "a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost * 0.7;").replace("regrowth: 0.025", "regrowth: 0.032"),
};
const seeds=[1931,7,42,315,90210,88];
for(const [name,fn] of Object.entries(variants)){
  const Eco=load(fn);
  let allAlive=0,total=0,extinctRuns=0;
  let sumP=0,sumH=0,sumC=0,finalOk=0;
  const rows=[];
  for(const seed of seeds){
    const e=new Eco({seed});
    e.runHeadless(360);
    const h=e.history;
    const seg=h.slice(50);
    const alive=seg.filter(x=>x.counts.plant>0&&x.counts.prey>0&&x.counts.pred>0).length;
    allAlive+=alive/seg.length; total++;
    const ext=seg.filter(x=>x.counts.pred===0).length;
    if(ext>0) extinctRuns++;
    sumP+=h.reduce((a,x)=>a+x.counts.plant,0)/h.length;
    sumH+=h.reduce((a,x)=>a+x.counts.prey,0)/h.length;
    sumC+=h.reduce((a,x)=>a+x.counts.pred,0)/h.length;
    const last=h[h.length-1].counts;
    if(last.prey>0&&last.pred>0) finalOk++;
    rows.push(`${seed}:${alive}/${seg.length}(${last.plant}/${last.prey}/${last.pred})`);
  }
  console.log(name.padEnd(20),'coexist',(allAlive/total*100).toFixed(0)+'%','extinctRuns',extinctRuns,'finalOk',finalOk,'avg',Math.round(sumP/total),Math.round(sumH/total),Math.round(sumC/total));
  console.log('  ',rows.join(' '));
}
