{"command":"cd <WS1> && node - <<'JS'
const fs=require('fs'),vm=require('vm');
const base=fs.readFileSync('_dev/sim.js','utf8');
const src=base.replace("a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost;", "a.e -= (0.0026 + ph.speed * 0.0012 + ph.speed * ph.speed * 0.013 + ph.vision * 0.00055) * ph.cost * 0.7;");
fs.writeFileSync('<TMP>/sim-exp.js',src);
const ctx={module:{exports:{}},console}; vm.createContext(ctx); vm.runInContext(src,ctx);
const Eco=ctx.VitariumCore.Ecosystem;
for(const seed of [1931,7,42,315,90210,88,3,11,23,57,101,204,777,1234]){
  const e=new Eco({seed}); e.runHeadless(480);
  const h=e.history;
  const mins={p:Infinity,h:Infinity,c:Infinity};
  for(const x of h.slice(50)){mins.p=Math.min(mins.p,x.counts.plant);mins.h=Math.min(mins.h,x.counts.prey);mins.c=Math.min(mins.c,x.counts.pred);}
  const last=h[h.length-1];
  const mean=f=>last.traits[f].mean.map(v=>v?.toFixed(2)??'-').join(' ');
  const drift=f=>last.traits[f].mean.map((v,i)=>v===null?'-':(v-h[0].traits[f].mean[i]).toFixed(2)).join(' ');
  console.log(String(seed).padStart(5),'final',last.counts.plant,last.counts.prey,last.counts.pred,'| min',mins.p,mins.h,mins.c,'| pred genes',mean('pred'),'Δ',drift('pred'),'| prey Δ',drift('prey'),'| events',e.spans.length,'rescues',e.logs.filter(l=>l.kind==='migration').length,'extinctions',e.logs.filter(l=>l.kind==='extinct').length);
}
