{"command":"cd <WS1> && node - <<'JS'
const {Ecosystem}=require('./_dev/sim.js');
const rows=[];
for(let seed=1;seed<=60;seed++){
  const e=new Ecosystem({seed});
  e.runHeadless(480);
  const h=e.history;
  const seg=h.slice(60);
  const minP=Math.min(...seg.map(x=>x.counts.plant));
  const minH=Math.min(...seg.map(x=>x.counts.prey));
  const minC=Math.min(...seg.map(x=>x.counts.pred));
  const maxH=Math.max(...h.map(x=>x.counts.prey));
  const maxC=Math.max(...h.map(x=>x.counts.pred));
  const last=h[h.length-1];
  const ext=e.logs.filter(l=>l.kind==='extinct').length;
  const resc=e.logs.filter(l=>l.kind==='migration').length;
  const drift = Math.max(...[0,1,2,3].map(g=>Math.abs(last.traits.prey.mean[g]-h[0].traits.prey.mean[g])), ... [0,1,2,3].map(g=>Math.abs(last.traits.pred.mean[g]-h[0].traits.pred.mean[g])));
  const variable = new Set(seg.map(x=>Math.round(x.counts.prey/50))).size + new Set(seg.map(x=>Math.round(x.counts.pred/10))).size;
  const score = (ext===0?20:0)+(resc===0?5:0)+(last.prey>80?10:0)+(last.pred>8?10:0)+(last.plant>1800&&last.plant<4500?8:0)+(minC>6?5:0)+(minH>60?5:0)+(drift>0.15?8:0)+(variable>8?6:0);
  rows.push({seed,score,last,minP,minH,minC,maxH,maxC,ext,resc,drift:drift.toFixed(2),variable});
}
rows.sort((a,b)=>b.score-a.score);
for(const r of rows.slice(0,12)) console.log(r.seed,'score',r.score,'final',r.last.counts.plant,r.last.counts.prey,r.last.counts.pred,'min',r.minP,r.minH,r.minC,'maxH/C',r.maxH,r.maxC,'ext',r.ext,'resc',r.resc,'drift',r.drift,'var',r.variable);
