                <canvas class="spark" id="mutationSpark" width="116" height="34" aria-hidden="true"></canvas>
              </div>
              <div class="param-note"><span>genetic drift envelope</span><span>0&ndash;0.100</span></div>
            </div>

            <div class="param">
              <div class="param-head">
                <span class="param-label" id="regrowthLabel">Food regrowth</span>
