              </div>
              <div class="param-row">
                <div class="slider" id="regrowthSlider" role="slider" tabindex="0" aria-labelledby="regrowthLabel" aria-valuemin="0.01" aria-valuemax="0.08" aria-valuenow="0.025" aria-valuetext="0.025 energy per generation" aria-orientation="horizontal" data-tip="regrowth"></div>
                <canvas class="spark" id="regrowthSpark" width="116" height="34" aria-hidden="true"></canvas>
              </div>
              <div class="param-note"><span>standing plant vigour</span><span>0.010&ndash;0.080</span></div>
            </div>
          </section>

          <section class="panel-section" aria-labelledby="secChronometry">
            <h2 class="sec-head" id="secChronometry"><span class="roman">II</span> Chronometry <span class="sec-rule"></span></h2>

            <div class="param">
              <div class="param-head">
                <span class="param-label" id="spanLabel">Lifespan</span>
                <span class="param-value"><span id="spanValue">480</span><span class="unit">gen</span></span>
              </div>
              <div class="span-row">
                <div class="stepper" role="group" aria-labelledby="spanLabel">
                  <button class="step-btn" id="spanMinus" type="button" aria-label="Decrease lifespan by fifty generations">&minus;</button>
                  <div class="stepper-read" id="spanRead">0480 <span class="unit">gen</span></div>
                  <button class="step-btn" id="spanPlus" type="button" aria-label="Increase lifespan by fifty generations">+</button>
                </div>
                <canvas class="spark" id="spanSpark" width="116" height="34" aria-hidden="true"></canvas>
              </div>
              <div class="param-note"><span>the plate closes here</span><span>100&ndash;2000</span></div>
            </div>

            <div class="param">
              <div class="param-head">
                <span class="param-label" id="tempoLabel">Tempo</span>
                <span class="param-value"><span id="tempoValue">12.0</span><span class="unit">gen/s</span></span>
              </div>
              <div class="tempo-wrap">
                <div class="dial-wrap">
                  <canvas class="tempo-dial" id="tempoDial" role="slider" tabindex="0" aria-labelledby="tempoLabel" aria-valuemin="0.5" aria-valuemax="40" aria-valuenow="12" aria-valuetext="12 generations per second" aria-orientation="horizontal" data-tip="tempo"></canvas>
                </div>
                <div class="dial-side">
                  <span class="eta-label">Estimated close</span>
                  <span class="eta-value" id="tempoEta">00:40 <em>at 12.0&times;</em></span>
                  <canvas class="spark" id="tempoSpark" width="136" height="34" aria-hidden="true"></canvas>
                </div>
              </div>
              <div class="param-note"><span>presentation only; the model is timeless</span><span>0.5&ndash;40</span></div>
            </div>

            <div class="toggle-grid">
              <div class="toggle">
                <button class="switch" id="tracesToggle" type="button" role="switch" aria-checked="true" aria-labelledby="tracesLabel" data-tip="traces"></button>
                <span class="toggle-label" id="tracesLabel">Traces</span>
              </div>
              <div class="toggle">
                <button class="switch" id="migrationToggle" type="button" role="switch" aria-checked="true" aria-labelledby="migrationLabel" data-tip="migration"></button>
                <span class="toggle-label" id="migrationLabel">Margin drift</span>
              </div>
            </div>
          </section>

          <section class="panel-section" aria-labelledby="secDisturbance">
            <h2 class="sec-head" id="secDisturbance"><span class="roman">III</span> Disturbance <span class="sec-rule"></span></h2>

            <div class="event" id="eventDrought" data-event="drought">
              <div class="event-head">
                <svg class="event-glyph" aria-hidden="true"><use href="#g-drought"></use></svg>
                <span class="event-name">Drought</span>
                <span class="event-value"><span id="droughtValue">110</span><span class="unit">gen</span></span>
                <button class="switch" id="droughtSwitch" type="button" role="switch" aria-checked="true" aria-labelledby="droughtLabel" data-tip="drought"></button>
              </div>
              <div class="event-row">
                <div class="slider" id="droughtSlider" role="slider" tabindex="0" aria-label="Drought interval" aria-valuemin="40" aria-valuemax="360" aria-valuenow="110" aria-valuetext="Every 110 generations" aria-orientation="horizontal"></div>
                <canvas class="spark" id="droughtSpark" width="116" height="34" aria-hidden="true"></canvas>
              </div>
              <div class="event-meta">
                <span id="droughtLabel">plant growth arrested &middot; 18 gen</span>
                <span class="next-at" id="droughtNext">next @ 0110</span>
              </div>
            </div>

            <div class="event" id="eventPlague" data-event="plague">
              <div class="event-head">
                <svg class="event-glyph" aria-hidden="true"><use href="#g-plague"></use></svg>
                <span class="event-name">Plague</span>
                <span class="event-value"><span id="plagueValue">150</span><span class="unit">gen</span></span>
                <button class="switch" id="plagueSwitch" type="button" role="switch" aria-checked="true" aria-labelledby="plagueLabel2" data-tip="plague"></button>
              </div>
              <div class="event-row">
                <div class="slider" id="plagueSlider" role="slider" tabindex="0" aria-label="Plague interval" aria-valuemin="40" aria-valuemax="360" aria-valuenow="150" aria-valuetext="Every 150 generations" aria-orientation="horizontal"></div>
                <canvas class="spark" id="plagueSpark" width="116" height="34" aria-hidden="true"></canvas>
              </div>
              <div class="event-meta">
                <span id="plagueLabel2">density-dependent fever &middot; 14 gen</span>
                <span class="next-at" id="plagueNext">next @ 0150</span>
              </div>
            </div>

            <div class="event" id="eventEclipse" data-event="eclipse">
              <div class="event-head">
                <svg class="event-glyph" aria-hidden="true"><use href="#g-eclipse"></use></svg>
                <span class="event-name">Eclipse</span>
                <span class="event-value"><span id="eclipseValue">190</span><span class="unit">gen</span></span>
                <button class="switch" id="eclipseSwitch" type="button" role="switch" aria-checked="true" aria-labelledby="eclipseLabel2" data-tip="eclipse"></button>
              </div>
              <div class="event-row">
                <div class="slider" id="eclipseSlider" role="slider" tabindex="0" aria-label="Eclipse interval" aria-valuemin="40" aria-valuemax="360" aria-valuenow="190" aria-valuetext="Every 190 generations" aria-orientation="horizontal"></div>
                <canvas class="spark" id="eclipseSpark" width="116" height="34" aria-hidden="true"></canvas>
              </div>
              <div class="event-meta">
                <span id="eclipseLabel2">vision contracts &middot; 12 gen</span>
                <span class="next-at" id="eclipseNext">next @ 0190</span>
              </div>
            </div>
          </section>
        </div>

        <div class="drawer-actions">
          <button class="btn btn-primary" id="pauseBtn" type="button" aria-pressed="false" data-tip="pause">
            <svg aria-hidden="true"><use href="#i-pause"></use></svg><span id="pauseLabel">Suspend</span>
          </button>
          <button class="btn" id="headlessBtn" type="button" data-tip="headless">
            <svg aria-hidden="true"><use href="#i-fast"></use></svg><span>Headless</span>
          </button>
        </div>
        <div class="drawer-foot">
          <span>Suspended time leaves no trace.</span>
          <span><kbd>SPACE</kbd> &middot; <kbd>F</kbd></span>
        </div>
      </div>

      <div class="drawer-spine" id="drawerSpine" aria-hidden="true">
        <button class="icon-btn" id="expandBtn" type="button" aria-label="Expand instrument panel" aria-controls="drawerBody" tabindex="-1">
          <svg class="flip" aria-hidden="true"><use href="#i-chevron"></use></svg>
        </button>
        <span class="spine-label">Instruments &middot; VII</span>
        <span class="spine-marker"></span>
      </div>
    </aside>
  </main>

  <footer class="colophon">
    <span>Vitarium &mdash; a closed trophic succession</span>
    <span class="shortcuts">Space observe / halt &middot; F headless &middot; R replay &middot; N new seed</span>
    <span class="local">Seeded PRNG &middot; no external matter</span>
  </footer>
</div>

<section class="archive" id="archive" hidden aria-labelledby="archiveTitle">
  <div class="archive-inner">
    <header class="archive-head">
      <div>
        <p class="eyebrow">VITARIUM <span class="slash">/</span> <span class="accent">ARCHIVE</span> <span class="slash">/</span> OBSERVATION CLOSED</p>
        <h2 id="archiveTitle" tabindex="-1">The plate, in retrospect.</h2>
        <p class="archive-dek" id="archiveDek">Every census and heritable shift from this sealed run, drawn in the same ink.</p>
      </div>
      <div class="archive-actions">
        <button class="btn" id="replayBtn" type="button"><svg aria-hidden="true"><use href="#i-replay"></use></svg><span>Replay this seed</span></button>
        <button class="btn btn-primary" id="newPlateBtn" type="button"><svg aria-hidden="true"><use href="#i-new"></use></svg><span>New plate</span></button>
      </div>
    </header>

    <div class="stats" role="group" aria-label="Run summary">
      <div class="stat">
        <span class="stat-k">Span</span>
        <span class="stat-v" id="statSpan">0480<sub> generations</sub></span>
        <p class="stat-sub">seed <b id="statSeed">000014</b> &middot; <span id="statTempo">12.0</span> gen/s</p>
      </div>
      <div class="stat">
        <span class="stat-k">Final census</span>
        <div class="stat-v census-vals">
          <span class="census-val plant"><i></i><span id="statPlant">0000</span></span>
          <span class="census-val prey"><i></i><span id="statPrey">0000</span></span>
          <span class="census-val pred"><i></i><span id="statPred">0000</span></span>
        </div>
        <div class="stat-sub"><span id="statCensusNote">Virens &middot; Lepus &middot; Vulpes</span></div>
      </div>
      <div class="stat">
        <span class="stat-k">Disturbances</span>
        <span class="stat-v" id="statDist">09<sub> events</sub></span>
        <div class="dist-bars">
          <span class="drought"><i></i><span id="statDrought">4 drought</span></span>
          <span class="plague"><i></i><span id="statPlague">3 plague</span></span>
          <span class="eclipse"><i></i><span id="statEclipse">2 eclipse</span></span>
        </div>
      </div>
      <div class="stat">
        <span class="stat-k">Trait shift</span>
        <span class="stat-v" id="statShift">+0.24</span>
        <p class="stat-sub"><span id="statShiftNote">grazer speed &middot; mean allele</span></p>
        <p class="stat-sub" id="statMutation">mutation 0.025 / allele</p>
      </div>
    </div>

    <figure class="archive-fig" aria-labelledby="popFigTitle">
      <div class="fig-head">
        <div class="fig-label">
          <span class="fig-no">Fig. II</span>
          <span class="fig-title" id="popFigTitle">Census history</span>
        </div>
        <div class="event-legend" aria-label="Disturbances marked on charts">
          <span class="drought"><i></i>Drought</span>
          <span class="plague"><i></i>Plague</span>
          <span class="eclipse"><i></i>Eclipse</span>
          <span class="fig-note">vertical bands mark disturbance spans</span>
        </div>
      </div>
      <div class="pop-wrap" id="popWrap">
        <canvas id="popChart" aria-label="Population curves for virens, lepus, and vulpes over the run"></canvas>
      </div>
    </figure>

    <section class="trait-section" aria-labelledby="traitTitle">
      <div class="trait-head">
        <div class="fig-label">
          <span class="fig-no">Fig. III</span>
          <span class="fig-title" id="traitTitle">Heritable drift</span>
        </div>
        <span class="trait-note">Solid line: mean allele value &middot; band: &plusmn;1&sigma; &middot; normalised genes, 0&ndash;1</span>
      </div>
      <div class="trait-table" id="traitTable"></div>
    </section>

    <footer class="archive-foot">
      <p class="closing">The plate is closed. The seed will repeat it exactly.</p>
      <div class="foot-links">
        <button class="btn" id="exportBtn" type="button"><svg aria-hidden="true"><use href="#i-download"></use></svg><span>Export census .csv</span></button>
        <button class="btn" id="againBtn" type="button"><svg aria-hidden="true"><use href="#i-replay"></use></svg><span>Observe again</span></button>
      </div>
    </footer>
  </div>
</section>

<div class="tip" id="tip" role="tooltip" aria-hidden="true"></div>
<div class="sr-only" id="announcer" aria-live="polite"></div>

<script>
/*__SIM__*/
</script>
<script>
/*__APP__*/
</script>
</body>
</html>
