<div class="shell" id="shell">
  <header class="masthead">
    <div class="ident">
      <p class="eyebrow">THE CLOSED TRANSFER <span class="slash">/</span> <span class="accent">PLATE VII</span> <span class="slash">/</span> OBSERVATION IN PROGRESS</p>
      <h1 class="wordmark">VITARIUM</h1>
      <p class="dek">A living plate of trophic succession &mdash; rosettes, grazers, hunters, and the weather between them.</p>
    </div>
    <div class="mast-meta" role="group" aria-label="Run status">
      <div class="meta-cell">
        <span class="meta-k">Seed</span>
        <span class="meta-v" id="metaSeed">000014</span>
      </div>
      <div class="meta-cell">
        <span class="meta-k">Generation</span>
        <span class="meta-v gen"><span id="metaGen">0000</span><span class="split">/ <span id="metaSpan">0480</span></span></span>
      </div>
      <div class="meta-cell">
        <span class="meta-k">State</span>
        <span class="meta-v"><i class="live-dot" id="liveDot"></i><span id="metaState">OBSERVING</span></span>
      </div>
    </div>
  </header>

  <main class="workspace" id="workspace">
    <section class="specimen" aria-label="Trophic field specimen">
      <div class="specimen-head">
        <div class="fig-label">
          <span class="fig-no">Fig. I</span>
          <span class="fig-title">Trophic field</span>
        </div>
        <div class="legend" aria-label="Species census">
          <div class="species sp-plant">
            <svg class="glyph" aria-hidden="true"><use href="#g-virens"></use></svg>
            <div class="sp-id"><span class="sp-name">Virens</span><span class="sp-role">rosette</span></div>
            <span class="sp-count" id="countPlant">0000</span>
          </div>
          <div class="species sp-prey">
            <svg class="glyph" aria-hidden="true"><use href="#g-lepus"></use></svg>
            <div class="sp-id"><span class="sp-name">Lepus</span><span class="sp-role">grazer</span></div>
            <span class="sp-count" id="countPrey">0000</span>
          </div>
          <div class="species sp-pred">
            <svg class="glyph" aria-hidden="true"><use href="#g-vulpes"></use></svg>
            <div class="sp-id"><span class="sp-name">Vulpes</span><span class="sp-role">hunter</span></div>
            <span class="sp-count" id="countPred">0000</span>
          </div>
        </div>
        <div class="head-events" id="headEvents" aria-live="polite">
          <span class="weather" id="weather">Fair weather</span>
        </div>
      </div>

      <div class="stage" id="stage">
        <canvas id="field" aria-label="A dark trophic field of rosettes, grazers, and hunters. The living simulation is rendered here."></canvas>
        <div class="glass-sheen" aria-hidden="true"></div>
        <div class="strike" id="strike" aria-hidden="true"></div>
        <div class="dispatch" id="dispatch" role="status" aria-live="polite">
          <span class="dkicker" id="dkicker">Disturbance</span>
          <span class="dtitle" id="dtitle">Drought</span>
          <span class="dnote" id="dnote">The canopy withholds.</span>
        </div>
      </div>

      <div class="plate-foot">
        <div class="field-note">
          <span class="foot-kicker">Field notes</span>
          <span class="ledger" id="ledger">Plate sealed.</span>
        </div>
        <div class="field-next">
          <span class="foot-kicker">Next disturbance</span>
          <span class="next-value" id="nextEvent">&mdash;</span>
        </div>
      </div>
    </section>

    <aside class="drawer" id="drawer" aria-label="Instrument panel">
      <div class="drawer-inner" id="drawerInner">
        <div class="drawer-head">
          <div>
            <p class="drawer-title">Instruments <span class="slash">/</span> VII</p>
            <p class="drawer-sub">Every setting acts on the living plate.</p>
          </div>
          <button class="icon-btn collapse-btn" id="collapseBtn" type="button" aria-expanded="true" aria-controls="drawerBody" aria-label="Collapse instrument panel" data-tip="collapse">
