                  <button class="step-btn" id="seedPlus" type="button" aria-label="Seed plus one">+</button>
                </div>
                <button class="mini-btn" id="seedReplay" type="button" aria-label="Replay this seed" data-tip="replay"><svg width="12" height="12" aria-hidden="true"><use href="#i-replay"></use></svg></button>
                <button class="mini-btn" id="seedNew" type="button" aria-label="Draw a new seed" data-tip="reseeds"><svg width="12" height="12" aria-hidden="true"><use href="#i-new"></use></svg></button>
