- Loop:
```
function tickLoop(now) {
  requestAnimationFrame(tickLoop);
  const dt = Math.min(50, now - lastFrame);
  lastFrame = now;
  if (running && !completed && !fastForwarding) {
     acc += dt/1000 * config.tempo;
     let steps = Math.min(6, Math.floor(acc));
     if (steps > 0) {
       for (let i=0;i<steps && !completed;i++){
         engine.stepGeneration();
         if (engine.gen >= config.runLength) { acc=0; finishRun(); break; }
       }
       acc = Math.min(acc - steps, 1); // if finished, 0
       renderer.dirty = true;
       afterStep(); // update UI if needed
     }
  } else {
     // avoid acc accumulation when paused
  }
  // UI updates when gen changed
  if (engine.gen !== lastUiGen) updateLive();
  renderer.frame(engine, running ? acc : 1, now);
}
```
- But process logs after steps and before render; `updateLive` only every gen. Good.
- When the last gen hits, finishRun schedules the archive; `completed=true` immediately, so rendering stops running; the final field drawn with alpha=1. 
