 for (let i=0;i<180;i++) stars.push({x:starRng(),y:starRng(),a:0.02+starRng()*0.05,r:starRng()<0.8?0.5:1});
 const anim = { };
 function ensureSize(){
   const rect=canvas.getBoundingClientRect();
   const w=Math.round(rect.width), h=Math.round(rect.height);
   if (w===cssW && h===cssH) return false;
   cssW=w; cssH=h; dpr=Math.min(2, window.devicePixelRatio||1);
   canvas.width=Math.max(1,Math.round(w*dpr));
   canvas.height=Math.max(1,Math.round(h*dpr));
   ctx.setTransform(dpr,0,0,dpr,0,0);
   computeLayout(); dirty=true;
   return true;
 }
 function computeLayout(){
   const side = Math.max(24, Math.min(56, cssW*0.052));
   const top = 18;
   const bottom = 10;
   const pulseH = Math.max(44, Math.min(62, cssH*0.085));
   const gap = Math.max(14, Math.min(22, cssH*0.035));
   let fw = Math.max(120, cssW - side*2);
   let fh = fw * (80/120);
   const availH = cssH - top - bottom - pulseH - gap;
   if (fh > availH) { fh = Math.max(110, availH); fw = fh * 1.5; }
   const fx = Math.round((cssW - fw)/2);
   const fy = Math.round(top + Math.max(0, Math.min(8, (availH - fh)*.25)));
   field = {x:fx,y:fy,w:fw,h:fh};
   pulse = {x:fx,y:fy+fh+gap,w:fw,h:pulseH};
 }
```
