  const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
  const pad = (v, n) => String(v).padStart(n || 1, '0');
  const nf = new Intl.NumberFormat('en-US');

  function rgba(hexColor, a) {
    const h = String(hexColor || '').trim();
    if (!h.startsWith('#')) return h;
    let raw = h.slice(1);
    if (raw.length === 3) raw = raw.split('').map(c => c + c).join('');
    const n = parseInt(raw, 16);
    if (!Number.isFinite(n)) return h;
    return 'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + a + ')';
  }
  function mix(hexColor, alpha) { return rgba(hexColor, alpha); }
  function round(v, step) { return Math.round(v / step) * step; }
  function fmtDuration(seconds) {
    const total = Math.max(0, Math.ceil(seconds));
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = total % 60;
    if (h > 0) return h + ':' + pad(m, 2) + ':' + pad(s, 2);
    return pad(m, 2) + ':' + pad(s, 2);
  }
  function signed(v, digits) {
    if (v === null || v === undefined || !Number.isFinite(v)) return '\u2014';
    const s = Math.abs(v).toFixed(digits === undefined ? 2 : digits);
    return (v >= 0 ? '+' : '\u2212') + s;
  }

