  /* ------------------------------------------------------------------ */
  /* Canvas renderer                                                    */
  /* ------------------------------------------------------------------ */

  function mulberry32(seed) {
    return Core.mulberry32(seed >>> 0);
  }

  function makeRenderer(canvas) {
    const ctx = canvas.getContext('2d');
    let cssW = 0, cssH = 0, dpr = 1;
    let field = { x: 0, y: 0, w: 1, h: 1 };
    let pulse = { x: 0, y: 0, w: 1, h: 1 };
    let stars = [];
    let flashes = [];
    let killSeen = 0;
    let killMark = 0;
    let dirty = true;
    let lastSizeKey = '';

    const starRng = mulberry32(0x5eeda11);
    for (let i = 0; i < 210; i++) {
      stars.push({
        x: starRng(),
        y: starRng(),
        a: 0.018 + starRng() * 0.055,
        r: starRng() > 0.82 ? 1.2 : 0.65
      });
    }

    const ray = [];
    for (let i = 0; i < 6; i++) {
      ray.push({ c: Math.cos(i * Math.PI / 3), s: Math.sin(i * Math.PI / 3) });
    }
    const angles = [];
    for (let i = 0; i < 5; i++) angles.push(i * Math.PI * 2 / 5);

    function layout() {
      const side = Math.max(18, Math.min(58, cssW * 0.05));
      const top = 18;
      const bottom = 10;
      const pulseH = Math.max(42, Math.min(64, cssH * 0.088));
      const gap = Math.max(13, Math.min(24, cssH * 0.032));
      const availW = Math.max(80, cssW - side * 2);
      const availH = Math.max(60, cssH - top - bottom - pulseH - gap);
      let fw = availW;
      let fh = fw * (80 / 120);
      if (fh > availH) {
        fh = availH;
        fw = fh * 1.5;
      }
      fw = Math.max(1, fw);
      fh = Math.max(1, fh);
      const fx = Math.round((cssW - fw) * 0.5);
      const fy = Math.round(top + Math.max(0, Math.min(7, (availH - fh) * 0.18)));
      field = { x: fx, y: fy, w: fw, h: fh };
      pulse = { x: fx, y: Math.round(fy + fh + gap), w: fw, h: pulseH };
    }

    function ensureSize() {
      const rect = canvas.getBoundingClientRect();
      const w = Math.round(rect.width);
      const h = Math.round(rect.height);
      const d = Math.min(2, window.devicePixelRatio || 1);
      const key = w + ':' + h + ':' + d;
      if (key === lastSizeKey) return false;
      lastSizeKey = key;
      cssW = Math.max(1, w);
      cssH = Math.max(1, h);
      dpr = d;
      canvas.width = Math.max(1, Math.round(cssW * dpr));
      canvas.height = Math.max(1, Math.round(cssH * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      layout();
      dirty = true;
      return true;
    }

    function interp(a, alpha) {
      const W = 120, H = 80;
      let px = a.px === undefined ? a.x : a.px;
      let py = a.py === undefined ? a.y : a.py;
      let dx = a.x - px;
      let dy = a.y - py;
      if (dx > W / 2) px += W; else if (dx < -W / 2) px -= W;
      if (dy > H / 2) py += H; else if (dy < -H / 2) py -= H;
      return { x: px + (a.x - px) * alpha, y: py + (a.y - py) * alpha };
    }

    function paw(x, y, sx, sy, r, color, width) {
      ctx.strokeStyle = color;
      ctx.lineWidth = width;
      ctx.beginPath();
      for (let i = 0; i < ray.length; i++) {
        const r0 = r * 0.22;
        ctx.moveTo(x + ray[i].c * r0, y + ray[i].s * r0);
        ctx.lineTo(x + ray[i].c * r, y + ray[i].s * r);
      }
      ctx.stroke();
      ctx.fillStyle = color;
      ctx.fillRect(x - 0.55, y - 0.55, 1.1, 1.1);
    }

    function drawEventGlyph(type, cx, cy, r) {
      ctx.save();
      ctx.strokeStyle = rgba(C[type], 0.095);
      ctx.lineWidth = 1.4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      if (type === 'drought') {
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.38, 0, Math.PI * 2);
        for (let i = 0; i < 8; i++) {
          const a = i * Math.PI / 4;
          ctx.moveTo(cx + Math.cos(a) * r * 0.52, cy + Math.sin(a) * r * 0.52);
          ctx.lineTo(cx + Math.cos(a) * r * 0.78, cy + Math.sin(a) * r * 0.78);
        }
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx - r * 0.95, cy + r * 0.58);
        ctx.bezierCurveTo(cx - r * 0.4, cy + r * 0.48, cx + r * 0.1, cy + r * 0.7, cx + r * 0.9, cy + r * 0.56);
        ctx.stroke();
      } else if (type === 'plague') {
        ctx.setLineDash([2, 7]);
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.72, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.2, 0, Math.PI * 2);
        ctx.stroke();
        for (let i = 0; i < 10; i++) {
          const a = i * Math.PI / 5;
          const x = cx + Math.cos(a) * r * 0.44;
          const y = cy + Math.sin(a) * r * 0.44;
          ctx.beginPath();
          ctx.moveTo(x - 2.2, y);
          ctx.lineTo(x + 2.2, y);
          ctx.moveTo(x, y - 2.2);
          ctx.lineTo(x, y + 2.2);
          ctx.stroke();
        }
      } else {
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.7, 0.45, Math.PI * 2 - 0.45);
        ctx.stroke();
        ctx.beginPath();
        const a = Math.PI * 0.72;
        ctx.arc(cx + Math.cos(a) * r * 0.24, cy + Math.sin(a) * r * 0.24, r * 0.5, -0.3, Math.PI * 1.45);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx - r * 0.9, cy + r * 0.82);
        ctx.lineTo(cx + r * 0.9, cy + r * 0.82);
        ctx.stroke();
      }
      ctx.restore();
    }

    function drawField(engine, alpha, now) {
      const { x, y, w, h } = field;
      const sx = w / 120;
      const sy = h / 80;
      const cx = x + w / 2;
      const cy = y + h / 2;

      ctx.save();
      // soft halo outside the plate
      const halo = ctx.createRadialGradient(cx, cy, Math.min(w, h) * 0.25, cx, cy, Math.max(w, h) * 0.64);
      halo.addColorStop(0, 'rgba(34, 55, 51, 0.12)');
      halo.addColorStop(1, 'rgba(4, 10, 10, 0)');
      ctx.fillStyle = halo;
      ctx.fillRect(x - 30, y - 24, w + 60, h + 48);

      const bg = ctx.createLinearGradient(x, y, x + w, y + h);
      bg.addColorStop(0, '#0a1718');
      bg.addColorStop(0.54, '#081314');
      bg.addColorStop(1, '#060f10');
      ctx.fillStyle = bg;
      ctx.fillRect(x, y, w, h);

      ctx.save();
      ctx.beginPath();
      ctx.rect(x, y, w, h);
      ctx.clip();

      // fixed field texture
      for (let i = 0; i < stars.length; i++) {
        const s = stars[i];
        ctx.fillStyle = 'rgba(219, 225, 206, ' + s.a.toFixed(3) + ')';
        ctx.fillRect(x + s.x * w, y + s.y * h, s.r, s.r);
      }

      // faint coordinate lattice
      ctx.strokeStyle = 'rgba(223, 225, 205, 0.035)';
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      for (let gx = 20; gx < 120; gx += 20) {
        const xx = x + gx * sx;
        ctx.moveTo(xx, y);
        ctx.lineTo(xx, y + h);
      }
      for (let gy = 20; gy < 80; gy += 20) {
        const yy = y + gy * sy;
        ctx.moveTo(x, yy);
        ctx.lineTo(x + w, yy);
      }
      ctx.stroke();

      const active = Array.from(engine.active.entries());
      if (active.length) {
        ctx.save();
        for (const [type, span] of active) {
          const born = engine.gen - span.start + Math.min(1, alpha);
          const fade = clamp(0.28 + born * 0.72, 0, 1);
          ctx.fillStyle = rgba(C[type], (type === 'eclipse' ? 0.09 : 0.055) * fade);
          ctx.fillRect(x, y, w, h);
          const edge = ctx.createLinearGradient(x, y, x + w, y);
          edge.addColorStop(0, rgba(C[type], 0.08 * fade));
          edge.addColorStop(0.4, rgba(C[type], 0));
          edge.addColorStop(1, rgba(C[type], 0.035 * fade));
          ctx.fillStyle = edge;
          ctx.fillRect(x, y, w, h);
          drawEventGlyph(type, cx, y + h * 0.53, Math.min(w, h) * 0.31);
        }
        ctx.restore();
      }
      if (engine.active.has('eclipse')) {
        ctx.fillStyle = 'rgba(2, 7, 9, 0.18)';
        ctx.fillRect(x, y, w, h);
      }

      // traces underneath the animals
      if (config.traces) {
        ctx.lineWidth = 0.8;
        for (let i = 0; i < engine.prey.length; i++) {
          const a = engine.prey[i];
          const p = interp(a, alpha);
          const px = x + p.x * sx;
          const py = y + p.y * sy;
          const len = sx * 1.15;
          ctx.strokeStyle = rgba(C.prey, 0.12);
          ctx.beginPath();
          ctx.moveTo(px - Math.cos(a.heading) * len, py - Math.sin(a.heading) * len);
          ctx.lineTo(px, py);
          ctx.stroke();
        }
        for (let i = 0; i < engine.preds.length; i++) {
          const a = engine.preds[i];
          const p = interp(a, alpha);
          const px = x + p.x * sx;
          const py = y + p.y * sy;
          const len = sx * 1.45;
          ctx.strokeStyle = rgba(C.pred, 0.16);
          ctx.beginPath();
          ctx.moveTo(px - Math.cos(a.heading) * len, py - Math.sin(a.heading) * len);
          ctx.lineTo(px, py);
          ctx.stroke();
        }
      }

      // plants: rosettes, shaded by stored energy
      const plantBuckets = [
        rgba(C.plant, 0.42), rgba(C.plant, 0.62), rgba(C.plant, 0.82), rgba(C.plant, 0.97)
      ];
      const plantWidth = Math.max(0.55, Math.min(1.0, sx * 0.115));
      for (let i = 0; i < engine.plants.length; i++) {
        const p = engine.plants[i];
        const e = clamp(p.e, 0, 1);
        const px = x + (p.x + 0.5) * sx;
        const py = y + (p.y + 0.5) * sy;
        const rr = sx * (0.17 + e * 0.24);
        const bucket = e < 0.24 ? 0 : e < 0.5 ? 1 : e < 0.78 ? 2 : 3;
        paw(px, py, sx, sy, rr, plantBuckets[bucket], plantWidth);
      }

      // grazers: open chevrons
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      for (let i = 0; i < engine.prey.length; i++) {
        const a = engine.prey[i];
        const p = interp(a, alpha);
        const px = x + p.x * sx;
        const py = y + p.y * sy;
        const e = clamp(a.e, 0, 1);
        const len = sx * (0.62 + e * 0.2);
        const wing = len * 0.62;
        const c = Math.cos(a.heading), s = Math.sin(a.heading);
        ctx.strokeStyle = rgba(C.prey, 0.54 + e * 0.44);
        ctx.lineWidth = Math.max(0.8, Math.min(1.3, sx * 0.15));
        ctx.beginPath();
        ctx.moveTo(px - c * len * 0.52 - s * wing, py - s * len * 0.52 + c * wing);
        ctx.lineTo(px + c * len * 0.48, py + s * len * 0.48);
        ctx.lineTo(px - c * len * 0.52 + s * wing, py - s * len * 0.52 - c * wing);
        ctx.stroke();
      }

      // hunters: filled darts
      for (let i = 0; i < engine.preds.length; i++) {
        const a = engine.preds[i];
        const p = interp(a, alpha);
        const px = x + p.x * sx;
        const py = y + p.y * sy;
        const e = clamp(a.e, 0, 1);
        const len = sx * (0.92 + e * 0.28);
        const wing = len * 0.3;
        const c = Math.cos(a.heading), s = Math.sin(a.heading);
        ctx.fillStyle = rgba(C.pred, 0.7 + e * 0.28);
        ctx.beginPath();
        ctx.moveTo(px + c * len * 0.5, py + s * len * 0.5);
        ctx.lineTo(px - c * len * 0.16 - s * wing, py - s * len * 0.16 + c * wing);
        ctx.lineTo(px - c * len * 0.44, py - s * len * 0.44);
        ctx.lineTo(px - c * len * 0.16 + s * wing, py - s * len * 0.16 - c * wing);
        ctx.closePath();
        ctx.fill();
      }

      // strikes
      if (flashes.length) {
        for (let i = 0; i < flashes.length; i++) {
          const f = flashes[i];
          const age = now - f.t;
          if (age < 0 || age > 560) continue;
          const q = 1 - age / 560;
          const fx = x + f.x * sx;
          const fy = y + f.y * sy;
          ctx.strokeStyle = rgba(C.pred, 0.55 * q);
          ctx.lineWidth = 0.9;
          ctx.beginPath();
