   const w=Math.round(rect.width), h=Math.round(rect.height);
   if (w===cssW && h===cssH) return false;
   cssW=w; cssH=h; dpr=Math.min(2, window.devicePixelRatio||1);
   canvas.width=Math.max(1,Math.round(w*dpr));
