  /* ------------------------------------------------------------------ */
  /* DOM cache                                                          */
  /* ------------------------------------------------------------------ */

  function cacheDom() {
    [
      'shell', 'workspace', 'drawer', 'drawerInner', 'drawerSpine', 'drawerBody', 'collapseBtn', 'expandBtn',
      'metaSeed', 'metaGen', 'metaSpan', 'metaState', 'liveDot',
      'countPlant', 'countPrey', 'countPred', 'headEvents', 'weather',
      'stage', 'field', 'dispatch', 'dkicker', 'dtitle', 'dnote', 'strike',
      'ledger', 'nextEvent',
      'seedInput', 'seedMinus', 'seedPlus', 'seedReplay', 'seedNew', 'seedSpark',
      'mutationSlider', 'mutationValue', 'mutationSpark',
      'regrowthSlider', 'regrowthValue', 'regrowthSpark',
      'spanMinus', 'spanPlus', 'spanValue', 'spanRead', 'spanSpark',
      'tempoDial', 'tempoValue', 'tempoEta', 'tempoSpark',
      'tracesToggle', 'migrationToggle',
      'eventDrought', 'eventPlague', 'eventEclipse',
      'droughtSlider', 'droughtValue', 'droughtSwitch', 'droughtSpark', 'droughtNext',
      'plagueSlider', 'plagueValue', 'plagueSwitch', 'plagueSpark', 'plagueNext',
      'eclipseSlider', 'eclipseValue', 'eclipseSwitch', 'eclipseSpark', 'eclipseNext',
      'pauseBtn', 'pauseLabel', 'headlessBtn',
      'archive', 'archiveTitle', 'archiveDek', 'traitTable',
      'statSpan', 'statSeed', 'statTempo', 'statPlant', 'statPrey', 'statPred', 'statCensusNote',
      'statDist', 'statDrought', 'statPlague', 'statEclipse', 'statShift', 'statShiftNote', 'statMutation',
      'popWrap', 'popChart', 'exportBtn', 'replayBtn', 'newPlateBtn',
