    ].forEach(id => { dom[id] = document.getElementById(id); });
  }

  function setText(el, text) {
    if (el && el.textContent !== text) el.textContent = text;
  }

  /* ------------------------------------------------------------------ */
  /* Canvas renderer                                                    */
  /* ------------------------------------------------------------------ */

  function mulberry32(seed) {
    return Core.mulberry32(seed >>> 0);
  }

  function makeRenderer(canvas) {
    const ctx = canvas.getContext('2d');
    let cssW = 0, cssH = 0, dpr = 1;
    let field = { x: 0, y: 0, w: 1, h: 1 };
    let pulse = { x: 0, y: 0, w: 1, h: 1 };
    let stars = [];
    let flashes = [];
    let killSeen = 0;
    let killMark = 0;
    let dirty = true;
    let lastSizeKey = '';

    const starRng = mulberry32(0x5eeda11);
    for (let i = 0; i < 210; i++) {
      stars.push({
        x: starRng(),
        y: starRng(),
        a: 0.018 + starRng() * 0.055,
        r: starRng() > 0.82 ? 1.2 : 0.65
      });
    }

    const ray = [];
    for (let i = 0; i < 6; i++) {
      ray.push({ c: Math.cos(i * Math.PI / 3), s: Math.sin(i * Math.PI / 3) });
    }
    const angles = [];
    for (let i = 0; i < 5; i++) angles.push(i * Math.PI * 2 / 5);

    function layout() {
      const side = Math.max(18, Math.min(58, cssW * 0.05));
      const top = 18;
      const bottom = 10;
      const pulseH = Math.max(42, Math.min(64, cssH * 0.088));
      const gap = Math.max(13, Math.min(24, cssH * 0.032));
      const availW = Math.max(80, cssW - side * 2);
      const availH = Math.max(60, cssH - top - bottom - pulseH - gap);
      let fw = availW;
      let fh = fw * (80 / 120);
      if (fh > availH) {
        fh = availH;
        fw = fh * 1.5;
      }
      fw = Math.max(1, fw);
      fh = Math.max(1, fh);
      const fx = Math.round((cssW - fw) * 0.5);
      const fy = Math.round(top + Math.max(0, Math.min(7, (availH - fh) * 0.18)));
      field = { x: fx, y: fy, w: fw, h: fh };
      pulse = { x: fx, y: Math.round(fy + fh + gap), w: fw, h: pulseH };
    }

    function ensureSize() {
      const rect = canvas.getBoundingClientRect();
      const w = Math.round(rect.width);
      const h = Math.round(rect.height);
      const d = Math.min(2, window.devicePixelRatio || 1);
      const key = w + ':' + h + ':' + d;
      if (key === lastSizeKey) return false;
      lastSizeKey = key;
      cssW = Math.max(1, w);
      cssH = Math.max(1, h);
      dpr = d;
      canvas.width = Math.max(1, Math.round(cssW * dpr));
      canvas.height = Math.max(1, Math.round(cssH * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      layout();
      dirty = true;
      return true;
    }

    function interp(a, alpha) {
      const W = 120, H = 80;
      let px = a.px === undefined ? a.x : a.px;
      let py = a.py === undefined ? a.y : a.py;
      let dx = a.x - px;
      let dy = a.y - py;
      if (dx > W / 2) px += W; else if (dx < -W / 2) px -= W;
      if (dy > H / 2) py += H; else if (dy < -H / 2) py -= H;
      return { x: px + (a.x - px) * alpha, y: py + (a.y - py) * alpha };
    }

    function paw(x, y, sx, sy, r, color, width) {
      ctx.strokeStyle = color;
      ctx.lineWidth = width;
      ctx.beginPath();
      for (let i = 0; i < ray.length; i++) {
        const r0 = r * 0.22;
        ctx.moveTo(x + ray[i].c * r0, y + ray[i].s * r0);
        ctx.lineTo(x + ray[i].c * r, y + ray[i].s * r);
      }
      ctx.stroke();
      ctx.fillStyle = color;
      ctx.fillRect(x - 0.55, y - 0.55, 1.1, 1.1);
    }

    function drawEventGlyph(type, cx, cy, r) {
      ctx.save();
      ctx.strokeStyle = rgba(C[type], 0.095);
      ctx.lineWidth = 1.4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      if (type === 'drought') {
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.38, 0, Math.PI * 2);
        for (let i = 0; i < 8; i++) {
          const a = i * Math.PI / 4;
          ctx.moveTo(cx + Math.cos(a) * r * 0.52, cy + Math.sin(a) * r * 0.52);
          ctx.lineTo(cx + Math.cos(a) * r * 0.78, cy + Math.sin(a) * r * 0.78);
        }
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx - r * 0.95, cy + r * 0.58);
        ctx.bezierCurveTo(cx - r * 0.4, cy + r * 0.48, cx + r * 0.1, cy + r * 0.7, cx + r * 0.9, cy + r * 0.56);
        ctx.stroke();
      } else if (type === 'plague') {
        ctx.setLineDash([2, 7]);
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.72, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.2, 0, Math.PI * 2);
        ctx.stroke();
        for (let i = 0; i < 10; i++) {
          const a = i * Math.PI / 5;
          const x = cx + Math.cos(a) * r * 0.44;
          const y = cy + Math.sin(a) * r * 0.44;
          ctx.beginPath();
          ctx.moveTo(x - 2.2, y);
          ctx.lineTo(x + 2.2, y);
          ctx.moveTo(x, y - 2.2);
          ctx.lineTo(x, y + 2.2);
          ctx.stroke();
        }
      } else {
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.7, 0.45, Math.PI * 2 - 0.45);
        ctx.stroke();
        ctx.beginPath();
        const a = Math.PI * 0.72;
        ctx.arc(cx + Math.cos(a) * r * 0.24, cy + Math.sin(a) * r * 0.24, r * 0.5, -0.3, Math.PI * 1.45);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx - r * 0.9, cy + r * 0.82);
        ctx.lineTo(cx + r * 0.9, cy + r * 0.82);
        ctx.stroke();
      }
      ctx.restore();
    }

    function drawField(engine, alpha, now) {
      const { x, y, w, h } = field;
      const sx = w / 120;
      const sy = h / 80;
      const cx = x + w / 2;
      const cy = y + h / 2;

      ctx.save();
      // soft halo outside the plate
      const halo = ctx.createRadialGradient(cx, cy, Math.min(w, h) * 0.25, cx, cy, Math.max(w, h) * 0.64);
      halo.addColorStop(0, 'rgba(34, 55, 51, 0.12)');
      halo.addColorStop(1, 'rgba(4, 10, 10, 0)');
      ctx.fillStyle = halo;
      ctx.fillRect(x - 30, y - 24, w + 60, h + 48);

      const bg = ctx.createLinearGradient(x, y, x + w, y + h);
      bg.addColorStop(0, '#0a1718');
      bg.addColorStop(0.54, '#081314');
      bg.addColorStop(1, '#060f10');
      ctx.fillStyle = bg;
      ctx.fillRect(x, y, w, h);

      ctx.save();
      ctx.beginPath();
      ctx.rect(x, y, w, h);
      ctx.clip();

      // fixed field texture
      for (let i = 0; i < stars.length; i++) {
        const s = stars[i];
        ctx.fillStyle = 'rgba(219, 225, 206, ' + s.a.toFixed(3) + ')';
        ctx.fillRect(x + s.x * w, y + s.y * h, s.r, s.r);
      }

      // faint coordinate lattice
      ctx.strokeStyle = 'rgba(223, 225, 205, 0.035)';
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      for (let gx = 20; gx < 120; gx += 20) {
        const xx = x + gx * sx;
        ctx.moveTo(xx, y);
        ctx.lineTo(xx, y + h);
      }
      for (let gy = 20; gy < 80; gy += 20) {
        const yy = y + gy * sy;
        ctx.moveTo(x, yy);
        ctx.lineTo(x + w, yy);
      }
      ctx.stroke();

      const active = Array.from(engine.active.entries());
      if (active.length) {
        ctx.save();
        for (const [type, span] of active) {
          const born = engine.gen - span.start + Math.min(1, alpha);
          const fade = clamp(0.28 + born * 0.72, 0, 1);
          ctx.fillStyle = rgba(C[type], (type === 'eclipse' ? 0.09 : 0.055) * fade);
          ctx.fillRect(x, y, w, h);
          const edge = ctx.createLinearGradient(x, y, x + w, y);
          edge.addColorStop(0, rgba(C[type], 0.08 * fade));
          edge.addColorStop(0.4, rgba(C[type], 0));
          edge.addColorStop(1, rgba(C[type], 0.035 * fade));
          ctx.fillStyle = edge;
          ctx.fillRect(x, y, w, h);
          drawEventGlyph(type, cx, y + h * 0.53, Math.min(w, h) * 0.31);
        }
        ctx.restore();
      }
      if (engine.active.has('eclipse')) {
        ctx.fillStyle = 'rgba(2, 7, 9, 0.18)';
        ctx.fillRect(x, y, w, h);
      }

      // traces underneath the animals
      if (config.traces) {
        ctx.lineWidth = 0.8;
        for (let i = 0; i < engine.prey.length; i++) {
          const a = engine.prey[i];
          const p = interp(a, alpha);
          const px = x + p.x * sx;
          const py = y + p.y * sy;
          const len = sx * 1.15;
          ctx.strokeStyle = rgba(C.prey, 0.12);
          ctx.beginPath();
          ctx.moveTo(px - Math.cos(a.heading) * len, py - Math.sin(a.heading) * len);
          ctx.lineTo(px, py);
          ctx.stroke();
        }
        for (let i = 0; i < engine.preds.length; i++) {
          const a = engine.preds[i];
          const p = interp(a, alpha);
          const px = x + p.x * sx;
          const py = y + p.y * sy;
          const len = sx * 1.45;
          ctx.strokeStyle = rgba(C.pred, 0.16);
          ctx.beginPath();
          ctx.moveTo(px - Math.cos(a.heading) * len, py - Math.sin(a.heading) * len);
          ctx.lineTo(px, py);
          ctx.stroke();
        }
      }

      // plants: rosettes, shaded by stored energy
      const plantBuckets = [
        rgba(C.plant, 0.42), rgba(C.plant, 0.62), rgba(C.plant, 0.82), rgba(C.plant, 0.97)
      ];
      const plantWidth = Math.max(0.55, Math.min(1.0, sx * 0.115));
      for (let i = 0; i < engine.plants.length; i++) {
        const p = engine.plants[i];
        const e = clamp(p.e, 0, 1);
        const px = x + (p.x + 0.5) * sx;
        const py = y + (p.y + 0.5) * sy;
        const rr = sx * (0.17 + e * 0.24);
        const bucket = e < 0.24 ? 0 : e < 0.5 ? 1 : e < 0.78 ? 2 : 3;
        paw(px, py, sx, sy, rr, plantBuckets[bucket], plantWidth);
      }

      // grazers: open chevrons
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      for (let i = 0; i < engine.prey.length; i++) {
        const a = engine.prey[i];
        const p = interp(a, alpha);
        const px = x + p.x * sx;
        const py = y + p.y * sy;
        const e = clamp(a.e, 0, 1);
        const len = sx * (0.62 + e * 0.2);
        const wing = len * 0.62;
        const c = Math.cos(a.heading), s = Math.sin(a.heading);
        ctx.strokeStyle = rgba(C.prey, 0.54 + e * 0.44);
        ctx.lineWidth = Math.max(0.8, Math.min(1.3, sx * 0.15));
        ctx.beginPath();
        ctx.moveTo(px - c * len * 0.52 - s * wing, py - s * len * 0.52 + c * wing);
        ctx.lineTo(px + c * len * 0.48, py + s * len * 0.48);
        ctx.lineTo(px - c * len * 0.52 + s * wing, py - s * len * 0.52 - c * wing);
        ctx.stroke();
      }

      // hunters: filled darts
      for (let i = 0; i < engine.preds.length; i++) {
        const a = engine.preds[i];
        const p = interp(a, alpha);
        const px = x + p.x * sx;
        const py = y + p.y * sy;
        const e = clamp(a.e, 0, 1);
        const len = sx * (0.92 + e * 0.28);
        const wing = len * 0.3;
        const c = Math.cos(a.heading), s = Math.sin(a.heading);
        ctx.fillStyle = rgba(C.pred, 0.7 + e * 0.28);
        ctx.beginPath();
        ctx.moveTo(px + c * len * 0.5, py + s * len * 0.5);
        ctx.lineTo(px - c * len * 0.16 - s * wing, py - s * len * 0.16 + c * wing);
        ctx.lineTo(px - c * len * 0.44, py - s * len * 0.44);
        ctx.lineTo(px - c * len * 0.16 + s * wing, py - s * len * 0.16 - c * wing);
        ctx.closePath();
        ctx.fill();
      }

      // strikes
      if (flashes.length) {
        for (let i = 0; i < flashes.length; i++) {
          const f = flashes[i];
          const age = now - f.t;
          if (age < 0 || age > 560) continue;
          const q = 1 - age / 560;
          const fx = x + f.x * sx;
          const fy = y + f.y * sy;
          ctx.strokeStyle = rgba(C.pred, 0.55 * q);
          ctx.lineWidth = 0.9;
          ctx.beginPath();
          for (let k = 0; k < 4; k++) {
            const a = k * Math.PI / 2 + (f.s % 1) * 1.4;
            const r0 = 1.3 + (1 - q) * 4;
            const r1 = 4.5 + (1 - q) * 7;
            ctx.moveTo(fx + Math.cos(a) * r0, fy + Math.sin(a) * r0);
            ctx.lineTo(fx + Math.cos(a) * r1, fy + Math.sin(a) * r1);
          }
          ctx.stroke();
        }
      }

      // fine registration marks and scale
      ctx.strokeStyle = 'rgba(231, 227, 211, 0.10)';
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      for (let gx = 20; gx < 120; gx += 20) {
        const xx = x + gx * sx;
        ctx.moveTo(xx, y);
        ctx.lineTo(xx, y + 3);
        ctx.moveTo(xx, y + h - 3);
        ctx.lineTo(xx, y + h);
      }
      for (let gy = 20; gy < 80; gy += 20) {
        const yy = y + gy * sy;
        ctx.moveTo(x, yy);
        ctx.lineTo(x + 3, yy);
        ctx.moveTo(x + w - 3, yy);
        ctx.lineTo(x + w, yy);
      }
      ctx.stroke();

      // scale bar
      const barW = sx * 10;
      const barX = x + w - barW - 9;
      const barY = y + h - 9;
      ctx.strokeStyle = 'rgba(231, 227, 211, 0.24)';
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(barX, barY);
      ctx.lineTo(barX + barW, barY);
      ctx.moveTo(barX, barY - 2.5);
      ctx.lineTo(barX, barY + 2.5);
      ctx.moveTo(barX + barW, barY - 2.5);
      ctx.lineTo(barX + barW, barY + 2.5);
      ctx.stroke();
      ctx.fillStyle = 'rgba(231, 227, 211, 0.34)';
      ctx.font = MONOFONT_SM;
      ctx.textAlign = 'right';
      ctx.fillText('10 CELLS', x + w - 9, barY - 5);

      ctx.restore(); // clip

      // frame
      ctx.strokeStyle = 'rgba(231, 227, 211, 0.28)';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      ctx.strokeStyle = 'rgba(231, 227, 211, 0.12)';
      ctx.strokeRect(x + 4.5, y + 4.5, w - 9, h - 9);
      const corners = [
        [x, y, 1, 1], [x + w, y, -1, 1], [x, y + h, 1, -1], [x + w, y + h, -1, -1]
      ];
      ctx.strokeStyle = rgba(C.brass, 0.55);
      ctx.beginPath();
      for (const c of corners) {
        ctx.moveTo(c[0] + c[2] * 10, c[1]);
        ctx.lineTo(c[0], c[1]);
        ctx.lineTo(c[0], c[1] + c[3] * 10);
      }
      ctx.stroke();

      // edge captions
      ctx.font = MONOFONT_SM;
      ctx.fillStyle = 'rgba(231, 227, 211, 0.34)';
      ctx.textAlign = 'left';
      ctx.fillText('FIELD 120 × 80', x, y - 7);
      ctx.textAlign = 'right';
      ctx.fillText('SEED ' + pad(config.seed, 6), x + w, y - 7);
      ctx.restore();
    }

    function drawPulse(engine, now) {
      const { x, y, w, h } = pulse;
      const topLabel = 12;
      const plotX = x;
      const plotY = y + topLabel;
      const plotW = w;
      const plotH = h - topLabel - 4;
      const N = Math.max(1, config.runLength);
      const history = engine.history;
      const current = engine.gen;

      ctx.save();
      ctx.fillStyle = 'rgba(231, 227, 211, 0.014)';
      ctx.fillRect(x, y, w, h);
      ctx.strokeStyle = 'rgba(231, 227, 211, 0.15)';
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(x, y + 0.5);
      ctx.lineTo(x + w, y + 0.5);
      ctx.stroke();

      ctx.font = MONOFONT_SM;
      ctx.fillStyle = 'rgba(231, 227, 211, 0.38)';
      ctx.textAlign = 'left';
      ctx.fillText('TROPHIC PULSE', x, y + 7);
      ctx.textAlign = 'right';
      ctx.fillStyle = 'rgba(231, 227, 211, 0.28)';
      ctx.fillText('GEN 0 \u2014 ' + pad(config.runLength, 4), x + w, y + 7);
      ctx.textAlign = 'left';

      ctx.strokeStyle = 'rgba(231, 227, 211, 0.06)';
      ctx.beginPath();
      for (let i = 1; i < 6; i++) {
        const xx = plotX + plotW * i / 6;
        ctx.moveTo(xx, plotY);
        ctx.lineTo(xx, plotY + plotH);
      }
      ctx.stroke();

      // disturbance windows
      for (const span of engine.spans) {
        const a = clamp(span.start / N, 0, 1);
        const b = clamp(Math.min(span.end, N + 1) / N, 0, 1);
        if (b <= a) continue;
        const x0 = plotX + a * plotW;
        const x1 = plotX + b * plotW;
        ctx.fillStyle = rgba(C[span.type], engine.gen >= span.start && engine.gen < span.end ? 0.11 : 0.055);
        ctx.fillRect(x0, plotY, Math.max(1, x1 - x0), plotH);
        ctx.strokeStyle = rgba(C[span.type], 0.72);
        ctx.lineWidth = 0.9;
        ctx.beginPath();
        ctx.moveTo(x0, plotY);
        ctx.lineTo(x0, plotY + 3);
        ctx.stroke();
      }

      // future tick marks
      for (const type of EVENT_KEYS) {
        const ed = config.events[type];
        if (!ed.enabled || ed.interval <= 0) continue;
        let at = engine.nextAt[type];
        if (!Number.isFinite(at)) continue;
        let guard = 0;
        while (at <= N && guard++ < 20) {
          const xx = plotX + (at / N) * plotW;
          ctx.strokeStyle = rgba(C[type], 0.26);
          ctx.lineWidth = 0.7;
          ctx.beginPath();
          ctx.moveTo(xx, plotY + 2);
          ctx.lineTo(xx, plotY + 5);
          ctx.stroke();
          at += ed.interval;
        }
      }

      // normalized histories
      const domains = { plant: 5200, prey: 1000, pred: 200 };
      const drawSeries = (key, color) => {
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.05;
        ctx.beginPath();
        let started = false;
        for (let i = 0; i < history.length; i++) {
          const hh = history[i];
          const px = plotX + (hh.gen / N) * plotW;
          let q = clamp(hh.counts[key] / domains[key], 0, 1);
          if (hh.counts[key] === 0) q = 0.004;
          const py = plotY + plotH - q * (plotH - 3);
          if (!started) { ctx.moveTo(px, py); started = true; }
          else ctx.lineTo(px, py);
        }
        ctx.stroke();
        const last = history[history.length - 1];
        if (last) {
          const px = plotX + (last.gen / N) * plotW;
          const py = plotY + plotH - clamp(last.counts[key] / domains[key], 0, 1) * (plotH - 3);
          ctx.fillStyle = color;
          ctx.beginPath();
          ctx.arc(px, py, 1.45, 0, Math.PI * 2);
          ctx.fill();
        }
      };
      drawSeries('plant', rgba(C.plant, 0.74));
      drawSeries('prey', rgba(C.prey, 0.84));
      drawSeries('pred', rgba(C.pred, 0.86));

      // current-generation needle
      const nx = plotX + (current / N) * plotW;
      ctx.strokeStyle = 'rgba(231, 227, 211, 0.20)';
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(nx, plotY);
      ctx.lineTo(nx, plotY + plotH);
      ctx.stroke();
      ctx.fillStyle = rgba(C.brass, 0.8);
      ctx.beginPath();
      ctx.moveTo(nx, plotY - 2.5);
      ctx.lineTo(nx + 2.5, plotY);
      ctx.lineTo(nx, plotY + 2.5);
      ctx.lineTo(nx - 2.5, plotY);
      ctx.closePath();
      ctx.fill();

      // tiny species keys at the right end of the label strip
      ctx.font = MONOFONT_SM;
      ctx.textAlign = 'right';
      const keyY = y + 7;
      ctx.fillStyle = rgba(C.pred, 0.9);
      ctx.fillText('VULPES', x + w - 71, keyY);
      ctx.fillStyle = rgba(C.prey, 0.9);
      ctx.fillText('LEPUS', x + w - 127, keyY);
      ctx.fillStyle = rgba(C.plant, 0.9);
      ctx.fillText('VIRENS', x + w - 183, keyY);
      ctx.restore();
    }

    function syncKills(engine, now) {
      if (engine.killCount !== killSeen) {
        const diff = Math.max(0, engine.killCount - killSeen);
        const take = Math.min(diff, 7);
        const recent = engine.kills.slice(-take);
        for (const k of recent) {
          flashes.push({ x: k.x, y: k.y, t: now, s: k.seed || 0 });
        }
        killSeen = engine.killCount;
        killMark = now;
      }
      if (flashes.length) {
        for (let i = flashes.length - 1; i >= 0; i--) {
          if (now - flashes[i].t > 580) flashes.splice(i, 1);
        }
      }
    }

    function draw(engine, alpha, now) {
      ensureSize();
      if (!ctx || !field.w) return;
      ctx.clearRect(0, 0, cssW, cssH);
      syncKills(engine, now);
      const a = clamp(alpha, 0, 1);
      drawField(engine, a, now);
      drawPulse(engine, now);
      dirty = false;
    }

    function reset() {
      flashes = [];
      killSeen = 0;
      dirty = true;
    }

    function hasEffects(now) {
      return flashes.some(f => now - f.t < 580);
    }

    return {
      draw,
      reset,
      invalidate() { dirty = true; },
      get dirty() { return dirty; },
      set dirty(v) { dirty = !!v; },
      hasEffects
    };
  }

  /* ------------------------------------------------------------------ */
  /* Sparklines and dial                                                 */
  /* ------------------------------------------------------------------ */

  function prepareCanvas(canvas) {
    const r = canvas.getBoundingClientRect();
    const w = Math.max(1, Math.round(r.width || canvas.clientWidth || 58));
    const h = Math.max(1, Math.round(r.height || canvas.clientHeight || 17));
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
    }
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    return { ctx, w, h };
  }

  function sparkBase(ctx, w, h) {
    ctx.strokeStyle = 'rgba(231, 227, 211, 0.12)';
    ctx.lineWidth = 0.6;
    ctx.beginPath();
    ctx.moveTo(0.5, h - 2.5);
    ctx.lineTo(w - 0.5, h - 2.5);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(231, 227, 211, 0.045)';
    ctx.beginPath();
    ctx.moveTo(0.5, Math.round(h * 0.5) + 0.5);
    ctx.lineTo(w - 0.5, Math.round(h * 0.5) + 0.5);
    ctx.stroke();
  }

  function polyline(ctx, pts, color, width) {
    if (!pts.length) return;
    ctx.strokeStyle = color;
    ctx.lineWidth = width || 1;
    ctx.beginPath();
    pts.forEach((p, i) => { if (i === 0) ctx.moveTo(p[0], p[1]); else ctx.lineTo(p[0], p[1]); });
    ctx.stroke();
  }

  function drawSparkMutation() {
    const { ctx, w, h } = prepareCanvas(dom.mutationSpark);
    sparkBase(ctx, w, h);
    const rate = config.mutation / 0.1;
    const end = 0.06 + rate * 0.42;
    const y0 = h * 0.52;
    const x1 = w - 2, x0 = 2;
    const band = [];
    for (let i = 0; i <= 26; i++) {
      const t = i / 26;
      const spread = end * Math.pow(t, 0.64);
      const x = x0 + (x1 - x0) * t;
      band.push([x, y0 - spread * (h - 6), y0 + spread * (h - 6)]);
    }
    ctx.fillStyle = rgba(C.brass, 0.10);
    ctx.beginPath();
    band.forEach((p, i) => { if (i === 0) ctx.moveTo(p[0], p[1]); else ctx.lineTo(p[0], p[1]); });
    for (let i = band.length - 1; i >= 0; i--) ctx.lineTo(band[i][0], band[i][2]);
    ctx.closePath();
    ctx.fill();
    polyline(ctx, band.map(p => [p[0], p[1]]), rgba(C.brass, 0.55), 0.8);
    polyline(ctx, band.map(p => [p[0], p[2]]), rgba(C.brass, 0.55), 0.8);
    ctx.strokeStyle = rgba(C.ink, 0.12);
    ctx.setLineDash([1, 3]);
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(x1, y0);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = rgba(C.brass, 0.95);
    ctx.beginPath();
    ctx.arc(x1 - 1, y0, 1.35, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawSparkRegrowth() {
    const { ctx, w, h } = prepareCanvas(dom.regrowthSpark);
    sparkBase(ctx, w, h);
    const k = 2.2 * Math.pow(config.regrowth / 0.025, 0.72);
    const pts = [];
    for (let i = 0; i <= 28; i++) {
      const t = i / 28;
      const y = (h - 3) - (1 - Math.exp(-k * t)) / (1 - Math.exp(-k)) * (h - 6);
      pts.push([2 + t * (w - 4), y]);
    }
    ctx.fillStyle = rgba(C.plant, 0.11);
    ctx.beginPath();
    ctx.moveTo(2, h - 2.5);
    pts.forEach(p => ctx.lineTo(p[0], p[1]));
    ctx.lineTo(w - 2, h - 2.5);
    ctx.closePath();
    ctx.fill();
    polyline(ctx, pts, rgba(C.plant, 0.72), 0.9);
    const last = pts[pts.length - 1];
    ctx.fillStyle = rgba(C.plant, 0.95);
    ctx.beginPath();
    ctx.arc(last[0] - 0.5, last[1], 1.25, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawSparkSeed() {
    const { ctx, w, h } = prepareCanvas(dom.seedSpark);
    sparkBase(ctx, w, h);
    const rng = mulberry32((config.seed * 2654435761) >>> 0);
    const pts = [];
    let y = 0.5;
    for (let i = 0; i <= 22; i++) {
      y = clamp(y + (rng() - 0.5) * 0.5, 0.13, 0.87);
      pts.push([2 + (i / 22) * (w - 4), 3 + y * (h - 7)]);
    }
    polyline(ctx, pts, rgba(C.brass, 0.66), 0.9);
    for (let i = 0; i < pts.length; i += 5) {
      ctx.fillStyle = rgba(C.brass, 0.3);
      ctx.fillRect(pts[i][0], 2, 0.6, h - 5);
    }
    ctx.fillStyle = rgba(C.brass, 0.9);
    ctx.beginPath();
    ctx.arc(pts[pts.length - 1][0], pts[pts.length - 1][1], 1.2, 0, Math.PI * 2);
    ctx.fill();
  }

  function eventsUpTo(limit) {
    const list = [];
    for (const type of EVENT_KEYS) {
      const ed = config.events[type];
      if (!ed.enabled || ed.interval <= 0) continue;
      for (let g = ed.interval; g <= limit; g += ed.interval) {
        list.push({ g, type });
        if (list.length > 80) break;
      }
    }
    return list.sort((a, b) => a.g - b.g);
  }

  function drawSparkSpan() {
    const { ctx, w, h } = prepareCanvas(dom.spanSpark);
    sparkBase(ctx, w, h);
    const x0 = 2, x1 = w - 2;
    const mid = h * 0.58;
    const frac = clamp(config.runLength / 2000, 0.02, 1);
    ctx.strokeStyle = rgba(C.brass, 0.22);
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(x0, h - 2.5);
    ctx.lineTo(x1, h - 2.5);
    ctx.stroke();
    ctx.strokeStyle = rgba(C.brass, 0.62);
    ctx.beginPath();
    ctx.moveTo(x0, mid);
    ctx.lineTo(x0 + (x1 - x0) * frac, mid);
    ctx.stroke();
    const ev = eventsUpTo(config.runLength);
    for (const e of ev) {
      const x = x0 + (e.g / 2000) * (x1 - x0);
      ctx.strokeStyle = rgba(C[e.type], 0.56);
      ctx.beginPath();
      ctx.moveTo(x, mid - 3.5);
      ctx.lineTo(x, mid + 2.5);
      ctx.stroke();
    }
    const mx = x0 + (x1 - x0) * frac;
    ctx.fillStyle = rgba(C.brass, 0.95);
    ctx.beginPath();
    ctx.moveTo(mx, mid - 4.5);
    ctx.lineTo(mx + 3, mid);
    ctx.lineTo(mx, mid + 4.5);
    ctx.lineTo(mx - 3, mid);
    ctx.closePath();
    ctx.fill();
  }

  function drawSparkTempo() {
    const { ctx, w, h } = prepareCanvas(dom.tempoSpark);
    sparkBase(ctx, w, h);
    const N = Math.max(1, config.runLength);
    const pts = [];
    for (let i = 0; i <= 30; i++) {
      const t = i / 30;
      const speed = 0.5 + t * 39.5;
      const secs = N / speed;
      const q = clamp(1 - Math.log(secs / (N / 0.5)) / Math.log(80), 0, 1);
      pts.push([2 + t * (w - 4), h - 3 - q * (h - 6)]);
    }
    polyline(ctx, pts, rgba(C.brass, 0.52), 0.85);
    const tx = (config.tempo - 0.5) / 39.5;
    const x = 2 + tx * (w - 4);
    const t = tx;
    const speed = config.tempo;
    const secs = N / speed;
    const q = clamp(1 - Math.log(secs / (N / 0.5)) / Math.log(80), 0, 1);
    const y = h - 3 - q * (h - 6);
    ctx.strokeStyle = rgba(C.ink, 0.18);
    ctx.beginPath();
    ctx.moveTo(x, 2);
    ctx.lineTo(x, h - 3);
    ctx.stroke();
    ctx.fillStyle = rgba(C.brass, 0.95);
    ctx.beginPath();
    ctx.arc(x, y, 1.4, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawSparkInterval(type) {
    const id = type + 'Spark';
    const { ctx, w, h } = prepareCanvas(dom[id]);
    sparkBase(ctx, w, h);
    const ed = config.events[type];
    const mid = h * 0.58;
    ctx.strokeStyle = rgba(C[type], ed.enabled ? 0.24 : 0.08);
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(2, h - 2.5);
    ctx.lineTo(w - 2, h - 2.5);
    ctx.stroke();
    const points = [];
    for (let g = ed.interval; g <= Math.max(ed.interval, config.runLength); g += ed.interval) {
      points.push(g);
      if (points.length > 20) break;
    }
    for (const g of points) {
      const x = 2 + (g / Math.max(1, config.runLength)) * (w - 4);
      ctx.strokeStyle = rgba(C[type], ed.enabled ? 0.62 : 0.18);
      ctx.beginPath();
      ctx.moveTo(x, mid - 4);
      ctx.lineTo(x, mid + 2.5);
      ctx.stroke();
    }
    ctx.fillStyle = rgba(C[type], ed.enabled ? 0.9 : 0.22);
    ctx.beginPath();
    ctx.arc(2, mid, 1.2, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawSparkIntervalAll() {
    EVENT_KEYS.forEach(drawSparkInterval);
  }

  function drawTempoDial() {
    const { ctx, w, h } = prepareCanvas(dom.tempoDial);
    const min = 0.5, max = 40;
    const t = clamp((config.tempo - min) / (max - min), 0, 1);
    const cx = w / 2, cy = h / 2, r = Math.min(w, h) * 0.37;
    const start = Math.PI * 0.75;
    const sweep = Math.PI * 1.5;

    ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(231, 227, 211, 0.18)';
    ctx.lineWidth = 0.9;
    ctx.beginPath();
    ctx.arc(cx, cy, r, start, start + sweep);
    ctx.stroke();

    for (let i = 0; i <= 28; i++) {
      const a = start + sweep * i / 28;
      const long = i % 7 === 0;
      const r0 = r - (long ? 4.5 : 2.6);
      const r1 = r - 0.5;
      ctx.strokeStyle = i / 28 <= t ? 'rgba(199, 163, 99, 0.52)' : 'rgba(231, 227, 211, 0.14)';
      ctx.lineWidth = long ? 0.9 : 0.55;
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0);
      ctx.lineTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(199, 163, 99, 0.92)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(cx, cy, r, start, start + sweep * t);
    ctx.stroke();

    const na = start + sweep * t;
    ctx.strokeStyle = 'rgba(236, 229, 210, 0.92)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(na) * r * 0.22, cy + Math.sin(na) * r * 0.22);
    ctx.lineTo(cx + Math.cos(na) * r * 0.78, cy + Math.sin(na) * r * 0.78);
    ctx.stroke();
    ctx.fillStyle = C.brass;
    ctx.beginPath();
    ctx.arc(cx + Math.cos(na) * r * 0.78, cy + Math.sin(na) * r * 0.78, 1.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(199, 163, 99, 0.85)';
    ctx.beginPath();
    ctx.arc(cx, cy, 2.0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(231, 227, 211, 0.10)';
    ctx.lineWidth = 0.6;
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.62, 0, Math.PI * 2);
    ctx.stroke();
  }

  function drawAllSparks() {
    drawSparkSeed();
    drawSparkMutation();
    drawSparkRegrowth();
    drawSparkSpan();
    drawSparkTempo();
    drawSparkIntervalAll();
    drawTempoDial();
  }
