    const text = remaining + 'G';
    if (left && left.textContent !== text) left.textContent = text;
    const label = EVENTS[type].label;
    chip.setAttribute('aria-label', label + ' active, ' + remaining + ' generations remaining');
  }

  function rebuildActiveChips(list) {
    if (!dom.headEvents) return;
    const keys = list.map(x => x[0]).sort();
    const sig = keys.join('|');
    if (sig !== state.activeSig) {
      state.activeSig = sig;
      for (const [type, chip] of Array.from(state.chips.entries())) {
        if (!keys.includes(type)) {
          chip.remove();
          state.chips.delete(type);
        }
      }
      dom.weather.hidden = keys.length > 0;
      for (const type of EVENT_KEYS) {
        if (!keys.includes(type)) continue;
        let chip = state.chips.get(type);
        if (!chip) {
          chip = document.createElement('span');
          chip.className = 'chip';
          chip.style.setProperty('--ev', eventColorVar(type));
          chip.dataset.tip = type;
          chip.innerHTML = '<i></i><span>' + EVENTS[type].label + '</span><span class="left"></span>';
          dom.headEvents.appendChild(chip);
          state.chips.set(type, chip);
        }
        // preserve domestic order
        const last = dom.headEvents.lastElementChild;
        if (last !== chip) dom.headEvents.appendChild(chip);
      }
    }
    for (const [type, span] of list) setActiveChipRemaining(type, Math.max(0, span.end - state.engine.gen));
  }

  function renderActive() {
    if (!state.engine) return;
    const list = Array.from(state.engine.active.entries());
    rebuildActiveChips(list);
    for (const type of EVENT_KEYS) {
      const el = EVT_DOM[type];
      const row = el.row();
      const active = state.engine.active.get(type);
      row.dataset.active = active ? 'true' : 'false';
      row.dataset.enabled = config.events[type].enabled ? 'true' : 'false';
      const sw = el.sw();
      if (sw.getAttribute('aria-checked') !== String(config.events[type].enabled)) {
        sw.setAttribute('aria-checked', String(config.events[type].enabled));
      }
      const value = el.value();
      const txt = String(config.events[type].interval);
      if (value.textContent !== txt) value.textContent = txt;
      value.classList.toggle('is-off', !config.events[type].enabled);
      const next = el.next();
      let label;
      if (!config.events[type].enabled) label = 'disabled';
      else if (active) label = 'ACTIVE \u00b7 ' + Math.max(0, active.end - state.engine.gen) + 'G left';
      else if (state.engine.nextAt[type] === Infinity) label = 'quiet';
      else if (state.engine.nextAt[type] > config.runLength) label = 'beyond this span';
      else label = 'next @ ' + pad(state.engine.nextAt[type], 4);
      if (next.textContent !== label) next.textContent = label;
    }
  }

  function nextDisturbance() {
    if (!state.engine) return null;
    let best = null;
    for (const type of EVENT_KEYS) {
      const ed = config.events[type];
      if (!ed.enabled || ed.interval <= 0) continue;
      let at = state.engine.nextAt[type];
      if (!Number.isFinite(at)) continue;
      if (at > config.runLength) continue;
      if (!best || at < best.at) best = { type, at };
    }
    return best;
  }

  function renderNext() {
    if (!state.engine || !dom.nextEvent) return;
    const n = nextDisturbance();
    if (!n) {
      const anyEnabled = EVENT_KEYS.some(t => config.events[t].enabled && config.events[t].interval > 0);
      const label = state.complete ? 'PLATE CLOSED' : anyEnabled ? 'NONE WITHIN SPAN' : 'NONE SCHEDULED';
      setText(dom.nextEvent, label);
      return;
    }
    const label = EVENTS[n.type].label.toUpperCase() + ' \u00b7 GEN ' + pad(n.at, 4);
    const key = n.type + label;
    if (dom.nextEvent.dataset.key !== key) {
      dom.nextEvent.dataset.key = key;
      dom.nextEvent.innerHTML = '<span class="dot" style="background:' + C[n.type] + '"></span>' + label;
    }
  }

  function renderEta() {
    if (!state.engine) return;
    const remain = Math.max(0, config.runLength - state.engine.gen);
    const seconds = remain / Math.max(0.5, config.tempo);
    const duration = fmtDuration(seconds);
    const key = duration + '|' + config.tempo.toFixed(1);
    if (state.etaSig !== key) {
      state.etaSig = key;
      dom.tempoEta.innerHTML = duration + ' <em>at ' + config.tempo.toFixed(1) + '\u00d7</em>';
    }
  }

  function renderLedger(log, animate) {
    if (!log || !dom.ledger) return;
    const html = '<span class="ledger-gen">' + pad(log.gen, 4) + '</span>' +
      '<span class="ledger-title">' + log.title + '</span>' +
      (log.detail ? '<span class="ledger-detail"> \u2014 ' + log.detail + '</span>' : '');
    clearTimeout(state.ledgerTimer);
    if (animate === false) {
      dom.ledger.classList.remove('swap');
      dom.ledger.innerHTML = html;
      state.ledgerLog = log;
      return;
    }
    dom.ledger.classList.add('swap');
    state.ledgerTimer = setTimeout(() => {
      dom.ledger.innerHTML = html;
      dom.ledger.classList.remove('swap');
      state.ledgerLog = log;
    }, 120);
  }

  function processLogs(announce) {
    if (!state.engine) return;
    const logs = state.engine.logs;
    if (state.seenLogs >= logs.length) return;
    let latest = null;
    let dispatchLog = null;
    for (let i = state.seenLogs; i < logs.length; i++) {
      const l = logs[i];
      latest = l;
      if (l.kind === 'start' && announce) dispatchLog = l;
      if (announce && (l.kind === 'migration' || l.kind === 'extinct')) {
        announceToScreenReader('Generation ' + l.gen + '. ' + l.title + '. ' + l.detail);
      }
    }
    state.seenLogs = logs.length;
    if (dispatchLog) showDispatch(dispatchLog);
    if (latest) renderLedger(latest, true);
  }

  function renderCounts() {
    if (!state.engine) return;
    const g = state.engine.gen;
    setText(dom.metaGen, pad(g, 4));
    setText(dom.metaSpan, pad(config.runLength, 4));
    setText(dom.metaSeed, pad(config.seed, 6));
    setText(dom.countPlant, pad(state.engine.plants.length, 4));
    setText(dom.countPrey, pad(state.engine.prey.length, 4));
    setText(dom.countPred, pad(state.engine.preds.length, 4));
  }

  function stateName() {
    if (state.complete) return 'CLOSED';
    if (state.fastForward) return 'HEADLESS';
    if (!state.running) return 'SUSPENDED';
    return 'OBSERVING';
  }

  function renderStateUI() {
    setText(dom.metaState, stateName());
    const dot = dom.liveDot;
    dot.className = 'live-dot' +
      (state.fastForward ? ' is-headless' : (state.complete || !state.running) ? ' is-halted' : '');
    dom.pauseBtn.querySelector('use').setAttribute('href', state.running ? '#i-pause' : '#i-play');
    setText(dom.pauseLabel, state.running ? 'Suspend' : 'Resume');
    dom.pauseBtn.setAttribute('aria-pressed', String(!state.running));
    dom.pauseBtn.dataset.tip = state.running ? 'pause' : 'resume';
    dom.pauseBtn.disabled = state.complete || state.fastForward;
    dom.headlessBtn.disabled = state.complete || state.fastForward;
    dom.workspace.classList.toggle('is-running', state.running && !state.fastForward && !state.complete);
  }

  function updateLive(force) {
    if (!state.engine) return;
    renderCounts();
    renderActive();
    renderNext();
    renderEta();
    renderStateUI();
    if (force) {
      state.lastUiGen = -1;
    }
  }

  /* ------------------------------------------------------------------ */
  /* Controls                                                           */
  /* ------------------------------------------------------------------ */

  function busy() {
    return !state.engine || state.fastForward || state.complete;
  }

  function ensureSliderParts(el) {
    if (!el || el.querySelector('.slider-fill')) return;
    el.innerHTML = '<span class="slider-fill"></span><span class="slider-ticks" aria-hidden="true"></span><span class="slider-thumb" aria-hidden="true"></span>';
  }

  function makeSlider(id, options) {
    const el = dom[id];
    ensureSliderParts(el);
    let value = options.value;
    const decimals = options.decimals === undefined ? 0 : options.decimals;
    const step = options.step;
    const update = () => {
      const p = clamp((value - options.min) / (options.max - options.min), 0, 1);
      el.style.setProperty('--fill', String(p));
      el.setAttribute('aria-valuenow', String(value));
      el.setAttribute('aria-valuetext', options.ariaText(value));
      el.setAttribute('aria-valuemin', String(options.min));
      el.setAttribute('aria-valuemax', String(options.max));
    };
    const setValue = (next, notify) => {
      let v = Math.round(next / step) * step;
      v = clamp(v, options.min, options.max);
      v = Number(v.toFixed(decimals));
      const changed = v !== value;
      value = v;
      update();
      if (notify && changed) options.onInput(v);
      return v;
    };
    if (options.tip) el.dataset.tip = options.tip;
    update();
    let dragging = false;
    const fromPointer = e => {
      const r = el.getBoundingClientRect();
      const p = clamp((e.clientX - r.left) / Math.max(1, r.width), 0, 1);
      return options.min + p * (options.max - options.min);
    };
    el.addEventListener('pointerdown', e => {
      if (busy() || (e.pointerType === 'mouse' && e.button !== 0)) return;
      el.focus({ preventScroll: true });
      dragging = true;
      try { el.setPointerCapture(e.pointerId); } catch (err) { /* no-op */ }
      setValue(fromPointer(e), true);
      e.preventDefault();
    });
    el.addEventListener('pointermove', e => {
      if (!dragging) return;
      setValue(fromPointer(e), true);
      e.preventDefault();
    });
    const end = e => {
      if (!dragging) return;
      dragging = false;
      try { el.releasePointerCapture(e.pointerId); } catch (err) { /* no-op */ }
      options.onCommit && options.onCommit(value);
    };
    el.addEventListener('pointerup', end);
    el.addEventListener('pointercancel', end);
    el.addEventListener('lostpointercapture', () => { dragging = false; });
    el.addEventListener('keydown', e => {
      if (busy()) return;
      let handled = true;
      const big = step * 5;
      switch (e.key) {
        case 'ArrowRight': case 'ArrowUp': case 'Right': case 'Up':
          setValue(value + step, true); break;
        case 'ArrowLeft': case 'ArrowDown': case 'Left': case 'Down':
          setValue(value - step, true); break;
        case 'PageUp': setValue(value + big, true); break;
        case 'PageDown': setValue(value - big, true); break;
        case 'Home': setValue(options.min, true); break;
        case 'End': setValue(options.max, true); break;
        default: handled = false;
      }
      if (handled) { e.preventDefault(); e.stopPropagation(); }
    });
    sliderControls[id] = { set: v => setValue(v, false), get: () => value };
    return sliderControls[id];
  }

  function commitSeed(value, restart) {
    let n = parseInt(String(value).replace(/[^\d]/g, ''), 10);
    if (!Number.isFinite(n)) n = config.seed;
    n = clamp(n, 1, 999999);
    dom.seedInput.value = pad(n, 6);
    if (n !== config.seed) {
      config.seed = n;
      drawSparkSeed();
      if (restart !== false) startRun();
    }
  }

  function deriveSeed(seed) {
    const next = (((seed * 1664525) >>> 0) + 1013904223) >>> 0;
    return (next % 999983) + 1;
  }

  function setSpan(v, restartIfPast) {
    if (busy()) return;
    let next = Math.round(v / 50) * 50;
    next = clamp(next, 100, 2000);
    config.runLength = next;
    dom.spanValue.textContent = String(next);
    dom.spanRead.innerHTML = pad(next, 4) + ' <span class="unit">gen</span>';
    dom.spanRead.setAttribute('aria-valuenow', String(next));
    dom.spanRead.setAttribute('aria-valuetext', next + ' generations');
    drawSparkSpan();
    renderCounts();
    renderEta();
    renderNext();
    if (state.engine && state.engine.gen >= config.runLength) {
      if (restartIfPast !== false) finishRun();
    }
    renderer.invalidate();
  }

  function setTempo(v, notify) {
    let next = clamp(Math.round(v * 2) / 2, 0.5, 40);
    config.tempo = next;
    dom.tempoValue.textContent = next.toFixed(1);
    dom.tempoDial.setAttribute('aria-valuenow', String(next));
    dom.tempoDial.setAttribute('aria-valuetext', next.toFixed(1) + ' generations per second');
    renderEta();
    drawSparkTempo();
    drawTempoDial();
    if (notify) renderer.invalidate();
  }

  function valueFromDialEvent(e) {
    const r = dom.tempoDial.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    const start = Math.PI * 0.75;
    const sweep = Math.PI * 1.5;
    let a = Math.atan2(e.clientY - cy, e.clientX - cx);
    let phi = a - start;
    while (phi < 0) phi += Math.PI * 2;
    while (phi >= Math.PI * 2) phi -= Math.PI * 2;
    if (phi > sweep) {
      const toStart = Math.min(phi, Math.PI * 2 - phi);
      const toEnd = Math.min(Math.abs(phi - sweep), Math.abs(phi - Math.PI * 2 - sweep));
      phi = toEnd <= toStart ? sweep : 0;
    }
    const t = clamp(phi / sweep, 0, 1);
    return 0.5 + t * 39.5;
  }

  function setupDial() {
    const el = dom.tempoDial;
    let dragging = false;
    el.addEventListener('pointerdown', e => {
      if (busy() || (e.pointerType === 'mouse' && e.button !== 0)) return;
      el.focus({ preventScroll: true });
      dragging = true;
      try { el.setPointerCapture(e.pointerId); } catch (err) { /* no-op */ }
      setTempo(valueFromDialEvent(e), true);
      e.preventDefault();
    });
    el.addEventListener('pointermove', e => {
      if (!dragging) return;
      setTempo(valueFromDialEvent(e), true);
      e.preventDefault();
    });
    const end = () => { dragging = false; };
    el.addEventListener('pointerup', end);
    el.addEventListener('pointercancel', end);
    el.addEventListener('lostpointercapture', end);
    el.addEventListener('keydown', e => {
      if (busy()) return;
      let next = config.tempo;
      let handled = true;
      switch (e.key) {
        case 'ArrowRight': case 'ArrowUp': case 'Right': case 'Up': next += 0.5; break;
        case 'ArrowLeft': case 'ArrowDown': case 'Left': case 'Down': next -= 0.5; break;
        case 'PageUp': next += 5; break;
        case 'PageDown': next -= 5; break;
        case 'Home': next = 0.5; break;
        case 'End': next = 40; break;
        default: handled = false;
      }
      if (handled) { e.preventDefault(); e.stopPropagation(); setTempo(next, true); }
    });
    setTempo(config.tempo, false);
  }

  function setupToggles() {
    const wire = (el, initial, onChange) => {
      el.setAttribute('aria-checked', String(initial));
      el.addEventListener('click', () => {
        if (busy()) return;
        const next = el.getAttribute('aria-checked') !== 'true';
        el.setAttribute('aria-checked', String(next));
        onChange(next);
      });
    };
    wire(dom.tracesToggle, config.traces, next => {
      config.traces = next;
      renderer.invalidate();
    });
    wire(dom.migrationToggle, config.migration, next => {
      config.migration = next;
      state.engine.setMigration(next);
      announceToScreenReader('Margin drift ' + (next ? 'enabled' : 'disabled') + '.');
    });
    for (const type of EVENT_KEYS) {
      wire(EVT_DOM[type].sw(), config.events[type].enabled, next => {
        config.events[type].enabled = next;
        state.engine.setEnabled(type, next);
        eventSparkSetup(type);
        drawAllSparks();
        updateLive(true);
        renderer.invalidate();
        announceToScreenReader(EVENTS[type].label + (next ? ' schedule enabled.' : ' schedule disabled.'));
      });
    }
  }

  function eventSparkSetup(type) {
    // Interval sparklines share one setter so they can be repainted after any
    // schedule change.
    const ed = config.events[type];
    const slider = sliderControls[type + 'Slider'];
    if (slider) slider.set(ed.interval);
  }

  function initializeControls() {
    // Slider scaffolding and behavior
    makeSlider('mutationSlider', {
      min: 0, max: 0.1, step: 0.001, decimals: 3, value: config.mutation, tip: 'mutation',
      ariaText: v => v.toFixed(3) + ' per allele per generation',
      onInput: v => {
        config.mutation = v;
        dom.mutationValue.textContent = v.toFixed(3);
        if (state.engine) state.engine.setMutationRate(v);
        drawSparkMutation();
        renderer.invalidate();
      }
    });
    makeSlider('regrowthSlider', {
      min: 0.01, max: 0.08, step: 0.001, decimals: 3, value: config.regrowth, tip: 'regrowth',
      ariaText: v => v.toFixed(3) + ' energy per generation',
      onInput: v => {
        config.regrowth = v;
        dom.regrowthValue.textContent = v.toFixed(3);
        if (state.engine) state.engine.setRegrowth(v);
        drawSparkRegrowth();
        drawSparkSpan();
        renderer.invalidate();
      }
    });
    for (const type of EVENT_KEYS) {
      makeSlider(type + 'Slider', {
        min: 40, max: 360, step: 10, decimals: 0, value: config.events[type].interval, tip: type,
        ariaText: v => 'Every ' + v + ' generations',
        onInput: v => {
          config.events[type].interval = v;
          dom[type + 'Value'].textContent = String(v);
          if (state.engine) state.engine.setInterval(type, v);
          drawSparkInterval(type);
          drawSparkSpan();
          renderActive();
          renderNext();
          renderer.invalidate();
        }
      });
      const slider = dom[type + 'Slider'];
      if (slider) slider.setAttribute('aria-label', EVENTS[type].label + ' interval');
    }

    // Seed control
    dom.seedInput.value = pad(config.seed, 6);
    dom.seedInput.dataset.tip = 'seed';
    dom.seedInput.addEventListener('focus', () => {
      requestAnimationFrame(() => dom.seedInput.select());
    });
    dom.seedInput.addEventListener('keydown', e => {
      if (e.key === 'Enter') {
        e.preventDefault();
        commitSeed(dom.seedInput.value, true);
        dom.seedInput.blur();
      } else if (e.key === 'Escape') {
        dom.seedInput.value = pad(config.seed, 6);
        dom.seedInput.blur();
      }
    });
    dom.seedInput.addEventListener('blur', () => {
      const v = parseInt(dom.seedInput.value, 10);
      if (Number.isFinite(v) && v !== config.seed) commitSeed(v, true);
      else dom.seedInput.value = pad(config.seed, 6);
    });
    dom.seedMinus.addEventListener('click', () => {
      if (busy()) return;
      const next = config.seed <= 1 ? 999999 : config.seed - 1;
      config.seed = next;
      dom.seedInput.value = pad(next, 6);
      startRun();
    });
    dom.seedPlus.addEventListener('click', () => {
      if (busy()) return;
      const next = config.seed >= 999999 ? 1 : config.seed + 1;
      config.seed = next;
      dom.seedInput.value = pad(next, 6);
      startRun();
    });
    dom.seedReplay.addEventListener('click', () => {
      if (busy()) return;
      startRun();
    });
    dom.seedNew.addEventListener('click', () => {
      if (busy()) return;
      config.seed = deriveSeed(config.seed);
      dom.seedInput.value = pad(config.seed, 6);
      startRun();
    });

    // Lifespan stepper
    dom.spanRead.tabIndex = 0;
    dom.spanRead.setAttribute('role', 'spinbutton');
    dom.spanRead.setAttribute('aria-valuemin', '100');
    dom.spanRead.setAttribute('aria-valuemax', '2000');
    dom.spanRead.dataset.tip = 'lifespan';
    dom.spanMinus.addEventListener('click', () => setSpan(config.runLength - 50));
    dom.spanPlus.addEventListener('click', () => setSpan(config.runLength + 50));
    dom.spanRead.addEventListener('keydown', e => {
      if (busy()) return;
      let handled = true;
      switch (e.key) {
        case 'ArrowUp': case 'ArrowRight': setSpan(config.runLength + 50); break;
        case 'ArrowDown': case 'ArrowLeft': setSpan(config.runLength - 50); break;
        case 'PageUp': setSpan(config.runLength + 250); break;
        case 'PageDown': setSpan(config.runLength - 250); break;
        case 'Home': setSpan(100); break;
        case 'End': setSpan(2000); break;
        default: handled = false;
      }
      if (handled) { e.preventDefault(); e.stopPropagation(); }
    });

    setupDial();
    setupToggles();

    // Actions
    dom.pauseBtn.addEventListener('click', () => {
      if (busy()) return;
      setRunning(!state.running);
    });
    dom.headlessBtn.addEventListener('click', () => {
      if (busy()) return;
      headlessFinish();
    });
    dom.replayBtn.addEventListener('click', () => {
      if (state.fastForward) return;
      startRun();
      dom.archiveOpen = false;
      closeArchive(true);
      focusPause();
    });
    dom.newPlateBtn.addEventListener('click', () => {
      if (state.fastForward) return;
      config.seed = deriveSeed(config.seed);
      dom.seedInput.value = pad(config.seed, 6);
      closeArchive(true);
      startRun();
      focusPause();
    });
    dom.exportBtn.addEventListener('click', exportCSV);

    // Drawer folding
    dom.collapseBtn.addEventListener('click', () => foldDrawer(true));
    dom.expandBtn.addEventListener('click', () => foldDrawer(false));
    dom.collapseBtn.dataset.tip = 'collapse';
    dom.expandBtn.dataset.tip = 'expand';

    dom.seedInput.dataset.tip = 'seed';
    dom.seedReplay.dataset.tip = 'replay';
    dom.seedNew.dataset.tip = 'reseeds';

    dom.replayBtn.dataset.tip = 'replayArchive';
    dom.newPlateBtn.dataset.tip = 'newPlate';
    dom.exportBtn.dataset.tip = 'export';
    dom.pauseBtn.dataset.tip = 'pause';
    dom.headlessBtn.dataset.tip = 'headless';

    requestAnimationFrame(() => {
      drawAllSparks();
    });
  }

  function focusPause() {
    setTimeout(() => {
      try { dom.pauseBtn.focus({ preventScroll: true }); } catch (err) { /* no-op */ }
    }, 30);
  }

  function foldDrawer(collapsed) {
    if (window.matchMedia('(max-width: 900px)').matches) return;
    dom.workspace.classList.toggle('is-collapsed', collapsed);
    dom.collapseBtn.setAttribute('aria-expanded', String(!collapsed));
    if (collapsed) {
      dom.drawerInner.inert = true;
      dom.drawerInner.setAttribute('aria-hidden', 'true');
      dom.expandBtn.focus({ preventScroll: true });
    } else {
      dom.drawerInner.inert = false;
      dom.drawerInner.removeAttribute('aria-hidden');
      dom.collapseBtn.focus({ preventScroll: true });
    }
    renderer.invalidate();
    setTimeout(() => {
      drawAllSparks();
      renderer.invalidate();
    }, 310);
  }

  /* ------------------------------------------------------------------ */
  /* Tooltips                                                           */
  /* ------------------------------------------------------------------ */

  let tipTarget = null;

  function showTip(target) {
    if (!target || !dom.tip) return;
    const key = target.dataset.tip;
    const data = TIPS[key];
    if (!data) return;
    if (target.closest('[inert]')) return;
    tipTarget = target;
    dom.tip.innerHTML = '<span class="tip-title">' + data.title + '</span><span class="tip-body">' + data.body + '</span>';
    dom.tip.setAttribute('aria-hidden', 'false');
    dom.tip.classList.add('show');
    requestAnimationFrame(() => {
      if (tipTarget !== target) return;
      const r = target.getBoundingClientRect();
      const tw = dom.tip.offsetWidth;
      const th = dom.tip.offsetHeight;
      let left = r.left + r.width / 2 - tw / 2;
      left = clamp(left, 8, window.innerWidth - tw - 8);
      let top = r.top - th - 10;
      if (top < 8) top = r.bottom + 10;
      if (top + th > window.innerHeight - 8) top = Math.max(8, window.innerHeight - th - 8);
      dom.tip.style.left = Math.round(left) + 'px';
      dom.tip.style.top = Math.round(top) + 'px';
    });
  }

  function hideTip(target) {
