      showTip(target);
    });
    document.addEventListener('pointerout', e => {
      const target = e.target.closest('[data-tip]');
      if (!target) return;
      if (e.relatedTarget && target.contains(e.relatedTarget)) return;
      hideTip(target);
    });
    document.addEventListener('focusin', e => {
      const target = e.target.closest('[data-tip]');
      if (target) showTip(target);
    });
    document.addEventListener('focusout', e => {
      const target = e.target.closest('[data-tip]');
      if (target) hideTip(target);
    });
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') hideTip();
    });
    window.addEventListener('resize', () => hideTip());
    document.querySelector('.drawer-body') && document.querySelector('.drawer-body').addEventListener('scroll', () => hideTip(), { passive: true });
    window.addEventListener('scroll', () => hideTip(), { passive: true });
  }

  function announceToScreenReader(text) {
    if (!dom.announcer) return;
    dom.announcer.textContent = '';
    setTimeout(() => { dom.announcer.textContent = text; }, 30);
  }
