  function drawGeneChart(canvas) {
    if (!state.engine) return;
    const ids = (canvas.dataset.geneCanvas || '').split(':');
    const species = ids[0];
    const geneIndex = Number(ids[1]);
    const sp = SPECIES_BY_KEY[species];
    if (!sp || !Number.isFinite(geneIndex)) return;
    const { ctx, w, h } = setupChartCanvas(canvas);
    if (w < 8 || h < 8) return;
    const padL = 15, padR = 6, padT = 7, padB = 7;
    const plotW = Math.max(4, w - padL - padR);
    const plotH = Math.max(4, h - padT - padB);
    const plotX = padL;
    const plotY = padT;
    const plotR = plotX + plotW;
    const plotB = plotY + plotH;
    const hist = state.engine.history;
    const N = Math.max(1, state.engine.gen || config.runLength);
    const xFor = g => plotX + (g / N) * plotW;
    const yFor = v => plotB - clamp(v, 0, 1) * plotH;
