        '<span class="ct-gen">GENERATION ' + pad(row.gen, 4) + '</span>' +
        SPECIES.map(sp => '<div class="ct-row ' + sp.key + '"><i></i><span>' + sp.name.toUpperCase() + '</span><b>' + nf.format(row.counts[sp.key]) + '</b></div>').join('') +
        (row.active && row.active.length ? '<div class="ct-events">' + row.active.map(t => EVENTS[t].label).join(' \u00b7 ') + '</div>' : '');
      const px = clamp(x, 84, r.width - 84);
      chartTipEl.style.left = px + 'px';
      chartTipEl.style.top = '2px';
      chartTipEl.style.transform = 'translate(-50%, 0)';
      if (state.chartHover !== index) {
        state.chartHover = index;
