  /* ------------------------------------------------------------------ */
  /* Export                                                             */
  /* ------------------------------------------------------------------ */

  function exportCSV() {
    if (!state.engine) return;
    const hist = state.engine.history;
    const geneHeaders = [];
    for (const sp of SPECIES) {
      for (const g of sp.genes) {
        geneHeaders.push(sp.key + '_' + g.label.toLowerCase().replace(/[^a-z]+/g, '_') + '_mean');
        geneHeaders.push(sp.key + '_' + g.label.toLowerCase().replace(/[^a-z]+/g, '_') + '_sd');
      }
    }
    const headers = ['generation', 'virens', 'lepus', 'vulpes'].concat(geneHeaders).concat(['active_events']);
    const lines = [headers.join(',')];
    for (const row of hist) {
      const cols = [row.gen, row.counts.plant, row.counts.prey, row.counts.pred];
      for (const sp of SPECIES) {
        for (let i = 0; i < sp.genes.length; i++) {
          const m = row.traits[sp.key] && row.traits[sp.key].mean ? row.traits[sp.key].mean[i] : null;
          const s = row.traits[sp.key] && row.traits[sp.key].sd ? row.traits[sp.key].sd[i] : null;
          cols.push(m === null || m === undefined ? '' : m.toFixed(6));
          cols.push(s === null || s === undefined ? '' : s.toFixed(6));
        }
      }
      cols.push((row.active || []).join(';'));
      lines.push(cols.join(','));
    }
    const blob = new Blob([lines.join('\n')], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'vitarium_seed_' + pad(config.seed, 6) + '_' + pad(state.engine.gen, 4) + 'gen.csv';
    document.body.appendChild(a);
