  /* ------------------------------------------------------------------ */
  /* Public console API and boot                                        */
  /* ------------------------------------------------------------------ */

  function publicSeek(target) {
    if (!state.engine || state.archiveOpen || state.fastForward || state.complete) return state.engine && state.engine.gen;
