    state.fastForward = true;
    state.running = false;
    state.acc = 0;
    renderStateUI();
    showSpecialBanner('var(--brass)', 'HEADLESS RUN \u00b7 NO LIGHT', 'READING THE PLATE',
      'Computing generations ' + pad(state.engine.gen, 4) + ' / ' + pad(target, 4) + '.', true);
