    const r = canvas.getBoundingClientRect();
    const w = Math.max(1, Math.round(r.width));
    const h = Math.max(1, Math.round(r.height));
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
    }
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    ctx.textBaseline = 'middle';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    return { ctx, w, h };
  }

  function chartTickLabel(v) {
    if (v >= 1000) return (v / 1000) + 'k';
    return String(v);
  }

  let chartTipEl = null;

  function drawPopChart() {
    if (!state.engine) return;
    const { ctx, w, h } = setupChartCanvas(dom.popChart);
    const chart = dom.popChart;
    const narrow = w < 640;
    const padL = narrow ? 34 : 44;
    const padR = narrow ? 88 : 108;
    const padT = narrow ? 24 : 29;
    const padB = 22;
    const plotW = Math.max(20, w - padL - padR);
    const plotH = Math.max(20, h - padT - padB);
    const plotX = padL;
    const plotY = padT;
    const plotR = plotX + plotW;
    const plotB = plotY + plotH;
    const hist = state.engine.history;
    const N = Math.max(1, state.engine.gen || config.runLength);
    const last = hist[hist.length - 1];
    const counts = hist.reduce((m, row) => {
      m.plant = Math.max(m.plant, row.counts.plant);
      m.prey = Math.max(m.prey, row.counts.prey);
      m.pred = Math.max(m.pred, row.counts.pred);
      return m;
    }, { plant: 1, prey: 1, pred: 1 });
    const maxCount = Math.max(counts.plant, counts.prey, counts.pred, 10);
    const logMax = Math.max(2, Math.ceil(Math.log10(maxCount + 1)));
    const domain = Math.pow(10, logMax);
    const yFor = n => plotB - (Math.log10(Math.max(1, n)) / Math.log10(domain)) * plotH;
    const xForGen = g => plotX + (g / N) * plotW;

    ctx.font = MONOFONT_SM;
    ctx.fillStyle = C.faint;
    ctx.textAlign = 'left';
    ctx.fillText('LOG CENSUS', plotX, 10);
    ctx.textAlign = 'right';
    ctx.fillText('INDIVIDUALS', plotR, 10);

    // horizontal guides and labels
    for (let i = 0; i <= logMax; i++) {
      const value = Math.pow(10, i);
      if (value > domain + 0.5) continue;
      const y = yFor(value);
      ctx.strokeStyle = rgba(C.ink, 0.075);
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(plotX, y);
      ctx.lineTo(plotR, y);
      ctx.stroke();
      ctx.fillStyle = C.faint;
      ctx.textAlign = 'right';
      ctx.fillText(chartTickLabel(value), plotX - 8, y);
    }
    // x guides / labels
    const divisions = 6;
    for (let i = 0; i <= divisions; i++) {
      const g = Math.round(N * i / divisions);
      const x = xForGen(g);
      ctx.strokeStyle = rgba(C.ink, i === 0 || i === divisions ? 0.11 : 0.055);
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(x, plotY);
      ctx.lineTo(x, plotB);
      ctx.stroke();
      ctx.fillStyle = C.faint;
      ctx.textAlign = i === 0 ? 'left' : i === divisions ? 'right' : 'center';
      ctx.fillText(String(g), x, plotB + 11);
    }
    ctx.strokeStyle = rgba(C.ink, 0.22);
    ctx.beginPath();
    ctx.moveTo(plotX, plotB + 0.5);
    ctx.lineTo(plotR, plotB + 0.5);
    ctx.stroke();
    ctx.fillStyle = C.ghost;
    ctx.textAlign = 'right';
    ctx.fillText('GENERATION', plotR, plotB + 18);

    // disturbance windows
    for (const span of state.engine.spans) {
      if (span.start > N) continue;
      const x0 = xForGen(clamp(span.start, 0, N));
      const x1 = xForGen(clamp(Math.min(span.end, N), 0, N));
      ctx.fillStyle = rgba(C[span.type], 0.065);
      ctx.fillRect(x0, plotY, Math.max(1, x1 - x0), plotH);
      ctx.strokeStyle = rgba(C[span.type], 0.55);
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(x0, plotY);
      ctx.lineTo(x0, plotY + 4);
      ctx.stroke();
    }
    // small event letters at the top when there is room
    if (plotW > 520) {
      for (const span of state.engine.spans) {
        if (span.start > N) continue;
        const x0 = xForGen(clamp(span.start, 0, N));
        ctx.fillStyle = rgba(C[span.type], 0.9);
        ctx.font = MONOFONT_SM;
        ctx.textAlign = 'left';
        ctx.fillText(EVENTS[span.type].label[0], x0 + 3, 15);
      }
    }

    // series
    const drawSeries = (key, color) => {
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.25;
      ctx.beginPath();
      let started = false;
      for (const row of hist) {
        const value = row.counts[key];
        if (!value) { started = false; continue; }
        const x = xForGen(row.gen);
        const y = yFor(value);
        if (!started) { ctx.moveTo(x, y); started = true; }
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    };
    drawSeries('plant', rgba(C.plant, 0.86));
    drawSeries('prey', rgba(C.prey, 0.92));
    drawSeries('pred', rgba(C.pred, 0.94));

    if (last) {
      const positions = [];
      for (const sp of SPECIES) {
        const value = last.counts[sp.key];
        positions.push({ sp, value, y: value ? yFor(value) : plotB - 1 });
      }
      positions.sort((a, b) => a.y - b.y);
      for (let i = 1; i < positions.length; i++) {
        if (positions[i].y - positions[i - 1].y < 13) positions[i].y = positions[i - 1].y + 13;
      }
      const overflow = positions.length ? positions[positions.length - 1].y - (plotB - 2) : 0;
      if (overflow > 0) for (const p of positions) p.y = Math.max(plotY + 6, p.y - overflow);
      for (const p of positions) {
        const x = xForGen(N);
        const color = C[p.sp.key];
        ctx.strokeStyle = rgba(color, 0.5);
        ctx.lineWidth = 0.7;
        ctx.beginPath();
        ctx.moveTo(plotR + 2, p.y);
        ctx.lineTo(plotR + 7, p.y);
        ctx.stroke();
        ctx.fillStyle = rgba(color, 0.96);
        ctx.beginPath();
        if (p.value) {
          ctx.arc(plotR - 1, p.y, 2.1, 0, Math.PI * 2);
        } else {
          ctx.rect(plotR - 3, p.y - 1.5, 3, 3);
        }
        ctx.fill();
        ctx.font = MONOFONT_SM;
        ctx.textAlign = 'left';
        ctx.fillStyle = rgba(color, 0.95);
        ctx.fillText(p.sp.name.toUpperCase(), plotR + 11, p.y);
        ctx.fillStyle = C.inkSoft;
        ctx.fillText(nf.format(p.value), plotR + 11 + (narrow ? 48 : 57), p.y);
      }
    }

    // hover crosshair
    if (state.chartHover !== null && state.chartHover !== undefined) {
      const row = hist[state.chartHover];
      if (row) {
        const x = xForGen(row.gen);
        ctx.strokeStyle = 'rgba(236, 229, 210, 0.28)';
        ctx.lineWidth = 0.7;
        ctx.setLineDash([2, 4]);
        ctx.beginPath();
        ctx.moveTo(x, plotY);
        ctx.lineTo(x, plotB);
        ctx.stroke();
        ctx.setLineDash([]);
        for (const sp of SPECIES) {
          const v = row.counts[sp.key];
          if (!v) continue;
          ctx.fillStyle = C[sp.key];
          ctx.beginPath();
          ctx.arc(x, yFor(v), 2.3, 0, Math.PI * 2);
          ctx.fill();
          ctx.strokeStyle = C.bg;
          ctx.lineWidth = 0.8;
          ctx.stroke();
        }
      }
    }

    state.chartGeom = { padL, padR, padT, padB, plotX, plotY, plotW, plotH, plotR, plotB, N };
    if (!chartTipEl) {
      chartTipEl = document.createElement('div');
      chartTipEl.className = 'chart-tip';
      chartTipEl.hidden = true;
      dom.popWrap.appendChild(chartTipEl);
    }
  }

  function drawGeneChart(canvas) {
    if (!state.engine) return;
    const ids = (canvas.dataset.geneCanvas || '').split(':');
    const species = ids[0];
    const geneIndex = Number(ids[1]);
    const sp = SPECIES_BY_KEY[species];
    if (!sp || !Number.isFinite(geneIndex)) return;
    const { ctx, w, h } = setupChartCanvas(canvas);
    if (w < 8 || h < 8) return;
    const padL = 15, padR = 6, padT = 7, padB = 7;
    const plotW = Math.max(4, w - padL - padR);
    const plotH = Math.max(4, h - padT - padB);
    const plotX = padL;
    const plotY = padT;
    const plotR = plotX + plotW;
    const plotB = plotY + plotH;
    const hist = state.engine.history;
    const N = Math.max(1, state.engine.gen || config.runLength);
    const xFor = g => plotX + (g / N) * plotW;
    const yFor = v => plotB - clamp(v, 0, 1) * plotH;
    const color = C[sp.key];

    // field guides
    for (const v of [0, 0.25, 0.5, 0.75, 1]) {
      const y = yFor(v);
      ctx.strokeStyle = v === 0 || v === 1 ? rgba(C.ink, 0.11) : rgba(C.ink, 0.045);
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.moveTo(plotX, y);
      ctx.lineTo(plotR, y);
      ctx.stroke();
    }
    ctx.strokeStyle = rgba(C.ink, 0.08);
    ctx.beginPath();
    ctx.moveTo(plotX + 0.5, plotY);
    ctx.lineTo(plotX + 0.5, plotB);
    ctx.stroke();

    // event markers
    for (const span of state.engine.spans) {
      if (span.start > N) continue;
      const x0 = xFor(clamp(span.start, 0, N));
      const x1 = xFor(clamp(Math.min(span.end, N), 0, N));
      ctx.fillStyle = rgba(C[span.type], 0.055);
      if (x1 > x0) ctx.fillRect(x0, plotY, Math.max(0.6, x1 - x0), plotH);
      ctx.strokeStyle = rgba(C[span.type], 0.42);
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.moveTo(x0, plotY);
      ctx.lineTo(x0, plotB);
      ctx.stroke();
    }

    const means = [];
    const sds = [];
    let any = false;
    for (const row of hist) {
      const t = row.traits[sp.key];
      const m = t && t.mean ? t.mean[geneIndex] : null;
      const s = t && t.sd ? t.sd[geneIndex] : null;
      means.push(m);
      sds.push(s);
      if (m !== null && m !== undefined) any = true;
    }
    if (!any) {
      ctx.fillStyle = C.faint;
      ctx.font = MONOFONT_SM;
      ctx.textAlign = 'center';
      ctx.fillText('NOT OBSERVED', plotX + plotW / 2, plotY + plotH / 2);
      return;
    }

    // split into contiguous non-null segments
    const segments = [];
    let seg = null;
    for (let i = 0; i < hist.length; i++) {
      if (means[i] === null || means[i] === undefined) {
        if (seg) { segments.push(seg); seg = null; }
      } else {
        if (!seg) seg = [];
        seg.push(i);
      }
    }
    if (seg) segments.push(seg);

    // spread envelope
    ctx.save();
    ctx.beginPath();
    ctx.rect(plotX, plotY, plotW, plotH);
    ctx.clip();
    ctx.fillStyle = rgba(color, 0.13);
    for (const s of segments) {
      if (s.length < 2) continue;
      ctx.beginPath();
      for (let i = 0; i < s.length; i++) {
        const idx = s[i];
        const x = xFor(hist[idx].gen);
        const y = yFor(means[idx] + (sds[idx] || 0));
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      for (let i = s.length - 1; i >= 0; i--) {
        const idx = s[i];
        ctx.lineTo(xFor(hist[idx].gen), yFor(means[idx] - (sds[idx] || 0)));
      }
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    // mean line
    ctx.strokeStyle = rgba(color, 0.95);
    ctx.lineWidth = 1.05;
    for (const s of segments) {
      ctx.beginPath();
      for (let i = 0; i < s.length; i++) {
        const idx = s[i];
        const x = xFor(hist[idx].gen);
        const y = yFor(means[idx]);
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }

    // final dot
    const finals = segments.length ? segments[segments.length - 1] : [];
    if (finals.length) {
      const idx = finals[finals.length - 1];
      ctx.fillStyle = rgba(color, 0.98);
      ctx.beginPath();
      ctx.arc(xFor(hist[idx].gen) - 0.6, yFor(means[idx]), 1.55, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function drawAllCharts() {
    drawPopChart();
    $$('.gene-cell canvas').forEach(drawGeneChart);
  }

  function statsForLastValid(history, speciesKey, geneIndex) {
    for (let i = history.length - 1; i >= 0; i--) {
      const t = history[i].traits[speciesKey];
      if (t && t.mean && t.mean[geneIndex] !== null && t.mean[geneIndex] !== undefined) {
        return { mean: t.mean[geneIndex], sd: t.sd[geneIndex], gen: history[i].gen };
      }
    }
    return null;
  }

  function fillTraitRows() {
    if (!state.engine) return;
    const hist = state.engine.history;
    const initial = hist[0];
    const final = hist[hist.length - 1];
    const rows = $$('.trait-row', dom.traitTable);
    for (const row of rows) {
      const key = row.dataset.species;
      const sp = SPECIES_BY_KEY[key];
      if (!sp) continue;
      const finalCount = final ? final.counts[key] : 0;
      setText(row.querySelector('[data-final]'), nf.format(finalCount));
      let strongest = { value: 0, title: '', label: '' };
      const cells = $$('.gene-cell', row);
      cells.forEach((cell, index) => {
        const gene = sp.genes[index];
        const lastValid = statsForLastValid(hist, key, index);
        const stat = lastValid ? '\u03bc ' + lastValid.mean.toFixed(2) + '  \u03c3 ' + (lastValid.sd === null ? '\u2014' : lastValid.sd.toFixed(2)) : '\u2014';
        setText(cell.querySelector('[data-gene-stat]'), stat);
        const canvas = cell.querySelector('canvas');
        if (canvas) {
          canvas.setAttribute('aria-label', sp.name + ' ' + gene.title + (lastValid ? ': mean ' + lastValid.mean.toFixed(2) + ', spread ' + (lastValid.sd || 0).toFixed(2) : ': no census'));
        }
        if (lastValid && initial && initial.traits[key] && initial.traits[key].mean[index] !== null) {
          const delta = lastValid.mean - initial.traits[key].mean[index];
          if (Math.abs(delta) > Math.abs(strongest.value)) {
            strongest = { value: delta, title: gene.title, label: gene.label };
          }
        }
      });
      const note = row.querySelector('[data-shift]');
      if (note) {
        if (finalCount === 0) {
          note.innerHTML = 'absent at close';
        } else if (strongest.title) {
          note.innerHTML = 'strongest shift <b>' + strongest.label.toUpperCase() + ' ' + signed(strongest.value, 2) + '</b>';
        } else {
          note.textContent = 'census stable';
        }
      }
    }
  }

  function fillArchiveSummary() {
    if (!state.engine) return;
    const final = state.engine.history[state.engine.history.length - 1];
    const initial = state.engine.history[0];
    const N = state.engine.gen;
    const spanCounts = { drought: 0, plague: 0, eclipse: 0 };
    for (const span of state.engine.spans) spanCounts[span.type]++;
    const total = state.engine.spans.length;

    dom.statSpan.innerHTML = pad(N, 4) + '<sub> generations</sub>';
    dom.statSeed.textContent = pad(config.seed, 6);
    dom.statTempo.textContent = config.tempo.toFixed(1);
    dom.statPlant.textContent = nf.format(final.counts.plant);
    dom.statPrey.textContent = nf.format(final.counts.prey);
    dom.statPred.textContent = nf.format(final.counts.pred);
    dom.statCensusNote.textContent = final.counts.plant + ' virens \u00b7 ' + final.counts.prey + ' lepus \u00b7 ' + final.counts.pred + ' vulpes';
    dom.statDist.innerHTML = pad(total, 2) + '<sub> ' + (total === 1 ? 'event' : 'events') + '</sub>';
    dom.statDrought.textContent = spanCounts.drought + (spanCounts.drought === 1 ? ' drought' : ' drought');
    dom.statPlague.textContent = spanCounts.plague + (spanCounts.plague === 1 ? ' plague' : ' plague');
    dom.statEclipse.textContent = spanCounts.eclipse + (spanCounts.eclipse === 1 ? ' eclipse' : ' eclipse');

    let best = { value: 0, species: null, gene: null };
    if (initial) {
      for (const sp of SPECIES) {
        for (let i = 0; i < sp.genes.length; i++) {
          const last = statsForLastValid(state.engine.history, sp.key, i);
          const first = initial.traits[sp.key];
          if (!last || !first || first.mean[i] === null) continue;
          const delta = last.mean - first.mean[i];
          if (Math.abs(delta) > Math.abs(best.value)) best = { value: delta, species: sp, gene: sp.genes[i] };
        }
      }
    }
    dom.statShift.textContent = best.species ? signed(best.value, 2) : '\u2014';
    dom.statShiftNote.textContent = best.species ? best.species.name.toLowerCase() + ' ' + best.gene.title : 'no heritable census';
    dom.statMutation.textContent = 'mutation ' + config.mutation.toFixed(3) + ' / allele \u00b7 food ' + config.regrowth.toFixed(3);
    dom.archiveDek.textContent = 'A single seed, ' + nf.format(N) + ' generations, ' + total + ' disturbance ' + (total === 1 ? 'window' : 'windows') + '. Census, heritable mean, and spread are preserved in the same ink.';
    const figNote = $('.fig-note', dom.archive);
    if (figNote) figNote.textContent = 'log census \u00b7 bands mark disturbance spans';
    fillTraitRows();
    const traitNote = $('.trait-note', dom.archive);
    if (traitNote) traitNote.innerHTML = 'Solid line: mean allele value \u00b7 band: &plusmn;1&sigma; \u00b7 genes normalised 0&ndash;1 \u00b7 generations 0&ndash;' + N;
  }

  function openArchive() {
    if (!state.engine || !state.complete) return;
    if (state.archiveOpen) return;
    state.archiveOpen = true;
    hideDispatch();
    hideTip();
    fillArchiveSummary();
    dom.archive.hidden = false;
    dom.archive.scrollTop = 0;
    document.body.classList.add('archive-open');
    dom.shell.inert = true;
    dom.shell.setAttribute('aria-hidden', 'true');
    dom.archive.classList.remove('reveal');
    void dom.archive.offsetWidth;
    requestAnimationFrame(() => {
      dom.archive.classList.add('open');
      requestAnimationFrame(() => {
        drawAllCharts();
        dom.archive.classList.add('reveal');
        dom.archiveTitle.focus({ preventScroll: true });
      });
    });
  }

  function closeArchive(instant) {
    clearTimeout(state.archiveRevealTimer);
    state.archiveOpen = false;
    state.chartHover = null;
    hideTip();
    if (chartTipEl) chartTipEl.hidden = true;
    dom.archive.classList.remove('open', 'reveal');
    document.body.classList.remove('archive-open');
    dom.shell.inert = false;
    dom.shell.removeAttribute('aria-hidden');
    if (instant) {
      dom.archive.hidden = true;
    } else {
      setTimeout(() => { dom.archive.hidden = true; }, 500);
    }
  }

  function attachPopHover() {
    let scheduled = false;
    const hide = () => {
      if (state.chartHover === null) return;
      state.chartHover = null;
      if (chartTipEl) chartTipEl.hidden = true;
      drawPopChart();
    };
    dom.popWrap.addEventListener('pointermove', e => {
      if (!state.archiveOpen || !state.chartGeom) return;
      const r = dom.popWrap.getBoundingClientRect();
      const g = state.chartGeom;
      const x = e.clientX - r.left;
      if (x < g.plotX || x > g.plotR || e.clientY < g.plotY - 10 || e.clientY > g.plotB + 10) {
        hide();
        return;
      }
      const ratio = (x - g.plotX) / Math.max(1, g.plotW);
      const index = clamp(Math.round(ratio * g.N), 0, state.engine.history.length - 1);
      if (!chartTipEl) return;
      const row = state.engine.history[index];
      if (!row) return;
      chartTipEl.hidden = false;
      chartTipEl.innerHTML =
        '<span class="ct-gen">GENERATION ' + pad(row.gen, 4) + '</span>' +
        SPECIES.map(sp => '<div class="ct-row ' + sp.key + '"><i></i><span>' + sp.name.toUpperCase() + '</span><b>' + nf.format(row.counts[sp.key]) + '</b></div>').join('') +
        (row.active && row.active.length ? '<div class="ct-events">' + row.active.map(t => EVENTS[t].label).join(' \u00b7 ') + '</div>' : '');
      const px = clamp(x, 84, r.width - 84);
      chartTipEl.style.left = px + 'px';
      chartTipEl.style.top = '2px';
      chartTipEl.style.transform = 'translate(-50%, 0)';
      if (state.chartHover !== index) {
        state.chartHover = index;
        if (!scheduled) {
          scheduled = true;
          requestAnimationFrame(() => {
            scheduled = false;
            if (state.archiveOpen) drawPopChart();
          });
        }
      }
    });
    dom.popWrap.addEventListener('pointerleave', hide);
  }

  /* ------------------------------------------------------------------ */
  /* Export                                                             */
  /* ------------------------------------------------------------------ */

  function exportCSV() {
    if (!state.engine) return;
    const hist = state.engine.history;
    const geneHeaders = [];
    for (const sp of SPECIES) {
      for (const g of sp.genes) {
        geneHeaders.push(sp.key + '_' + g.label.toLowerCase().replace(/[^a-z]+/g, '_') + '_mean');
        geneHeaders.push(sp.key + '_' + g.label.toLowerCase().replace(/[^a-z]+/g, '_') + '_sd');
      }
    }
    const headers = ['generation', 'virens', 'lepus', 'vulpes'].concat(geneHeaders).concat(['active_events']);
    const lines = [headers.join(',')];
    for (const row of hist) {
      const cols = [row.gen, row.counts.plant, row.counts.prey, row.counts.pred];
      for (const sp of SPECIES) {
        for (let i = 0; i < sp.genes.length; i++) {
          const m = row.traits[sp.key] && row.traits[sp.key].mean ? row.traits[sp.key].mean[i] : null;
          const s = row.traits[sp.key] && row.traits[sp.key].sd ? row.traits[sp.key].sd[i] : null;
          cols.push(m === null || m === undefined ? '' : m.toFixed(6));
          cols.push(s === null || s === undefined ? '' : s.toFixed(6));
        }
      }
      cols.push((row.active || []).join(';'));
      lines.push(cols.join(','));
    }
    const blob = new Blob([lines.join('\n')], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'vitarium_seed_' + pad(config.seed, 6) + '_' + pad(state.engine.gen, 4) + 'gen.csv';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
    announceToScreenReader('Census CSV exported.');
  }

  /* ------------------------------------------------------------------ */
  /* Keyboard, resize, loop                                             */
  /* ------------------------------------------------------------------ */

  function setupKeyboard() {
    document.addEventListener('keydown', e => {
      if (e.defaultPrevented || e.metaKey || e.ctrlKey || e.altKey) return;
      if (state.archiveOpen) return;
      const t = e.target;
      const typing = t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' ||
        (t.closest && t.closest('[role="slider"], [role="spinbutton"], button')));
      if (e.code === 'Space' && !typing && !state.fastForward && !state.complete) {
        e.preventDefault();
        setRunning(!state.running);
        return;
      }
      if (typing || state.fastForward || state.complete) return;
      if (e.key === 'f' || e.key === 'F') { e.preventDefault(); headlessFinish(); }
      else if (e.key === 'r' || e.key === 'R') { e.preventDefault(); startRun(); }
      else if (e.key === 'n' || e.key === 'N') {
        e.preventDefault();
        config.seed = deriveSeed(config.seed);
        startRun();
      } else if (e.key === 'i' || e.key === 'I') {
        e.preventDefault();
        foldDrawer(!dom.workspace.classList.contains('is-collapsed'));
      }
    });
  }

  function setupResize() {
    let resizeTimer = 0;
    const redraw = () => {
      hideTip();
      drawAllSparks();
      if (state.archiveOpen) {
        drawAllCharts();
        if (chartTipEl) chartTipEl.hidden = true;
        state.chartHover = null;
      }
      renderer.invalidate();
    };
    window.addEventListener('resize', () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(redraw, 120);
    });
  }

  function loop(now) {
    rafId = requestAnimationFrame(loop);
    if (!state.lastTime) state.lastTime = now;
    let dt = now - state.lastTime;
    state.lastTime = now;
    if (dt < 0) dt = 0;
    dt = Math.min(dt, 64);
    if (state.running && !state.complete && !state.fastForward && state.engine) {
      state.acc += (dt / 1000) * config.tempo;
      let steps = 0;
      while (state.acc >= 1 && steps < 8 && !state.complete) {
        state.engine.stepGeneration();
        state.acc -= 1;
        steps++;
        if (state.engine.gen >= config.runLength) {
          state.acc = 0;
          finishRun(false);
          break;
        }
      }
      if (steps > 0) {
        processLogs(true);
        updateLive(true);
        renderer.invalidate();
      }
    }
    const shouldDraw = state.running || renderer.dirty || renderer.hasEffects(now);
    if (shouldDraw && state.engine) {
      renderer.draw(state.engine, state.running ? clamp(state.acc, 0, 1) : 1, now);
    }
  }

  /* ------------------------------------------------------------------ */
  /* Public console API and boot                                        */
  /* ------------------------------------------------------------------ */

  function publicSeek(target) {
    if (!state.engine || state.archiveOpen || state.fastForward || state.complete) return state.engine && state.engine.gen;
    const end = clamp(Math.round(target), state.engine.gen, config.runLength);
    if (end > state.engine.gen) {
      state.running = false;
      freezePositions();
      while (state.engine.gen < end) state.engine.stepGeneration();
      processLogs(false);
      freezePositions();
      updateLive(true);
      renderStateUI();
      renderer.invalidate();
      if (state.engine.gen >= config.runLength) finishRun(false);
    }
    return state.engine.gen;
  }

  function init() {
    cacheDom();
    buildTraitTable();
    renderer = makeRenderer(dom.field);
    initializeControls();
    setupTooltips();
    attachPopHover();
    setupKeyboard();
    setupResize();
    startRun();
    if (!dom.archive.classList.contains('open')) dom.archive.hidden = true;
    requestAnimationFrame(now => {
      state.lastTime = now;
      loop(now);
    });
    try {
      window.VITARIUM = {
        get engine() { return state.engine; },
        get config() { return config; },
        get state() { return { gen: state.engine ? state.engine.gen : 0, running: state.running, complete: state.complete, archiveOpen: state.archiveOpen }; },
        seek: publicSeek,
        finish: () => finishRun(false),
        resume: () => setRunning(true),
        suspend: () => setRunning(false),
        replay: () => startRun(),
        seed: function (n) {
          const v = parseInt(n, 10);
          if (Number.isFinite(v)) { config.seed = clamp(v, 1, 999999); startRun(); }
        },
        snapshot: () => state.engine ? state.engine.snapshot() : null,
        exportCSV
      };
    } catch (err) { /* console API is a convenience, not a dependency */ }
  }

  init();
})();
