{"content":"'use strict';
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const sleep = ms => new Promise(r => setTimeout(r, ms));

class CDP {
  constructor(ws) {
    this.ws = ws;
    this.id = 0;
    this.pending = new Map();
    this.events = [];
    this.console = [];
    this.exceptions = [];
    this.network = [];
    ws.addEventListener('message', ev => {
      const msg = JSON.parse(ev.data);
      if (msg.id && this.pending.has(msg.id)) {
        const p = this.pending.get(msg.id);
        this.pending.delete(msg.id);
        if (msg.error) p.reject(new Error(JSON.stringify(msg.error)));
        else p.resolve(msg.result);
      } else if (msg.method) {
        this.events.push(msg);
        if (msg.method === 'Runtime.consoleAPICalled') {
          this.console.push({
            type: msg.params.type,
            args: msg.params.args.map(a => a.value !== undefined ? a.value : a.description || a.type)
          });
        }
        if (msg.method === 'Runtime.exceptionThrown') {
          this.exceptions.push(msg.params.exceptionDetails);
        }
        if (msg.method === 'Network.requestWillBeSent') {
          this.network.push(msg.params.request.url);
        }
      }
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      setTimeout(() => {
        if (this.pending.has(id)) {
          this.pending.delete(id);
          reject(new Error('CDP timeout: ' + method));
        }
      }, 30000);
    });
  }
  async eval(expression, awaitPromise = true) {
    const res = await this.send('Runtime.evaluate', {
      expression,
      awaitPromise,
      returnByValue: true,
      userGesture: true
    });
    if (res.exceptionDetails) throw new Error(JSON.stringify(res.exceptionDetails));
    return res.result ? res.result.value : undefined;
  }
  async screenshot(file) {
    const { data } = await this.send('Page.captureScreenshot', { format: 'png', fromSurface: true });
    fs.writeFileSync(file, Buffer.from(data, 'base64'));
    return file;
  }
}

async function launch(opts = {}) {
  const width = opts.width || 1440;
  const height = opts.height || 900;
  const port = opts.port || 9333;
  const profile = `<TMP>/vitarium-chrome-${process.pid}-${Date.now()}`;
  const chrome = spawn(CHROME, [
    '--headless=new',
    '--remote-debugging-port=' + port,
    '--user-data-dir=' + profile,
    '--no-first-run',
    '--no-default-browser-check',
    '--disable-extensions',
    '--disable-background-networking',
    '--disable-component-update',
    '--disable-sync',
    '--hide-scrollbars',
    '--force-device-scale-factor=1',
    '--window-size=' + width + ',' + height,
    'about:blank'
  ], { stdio: ['ignore', 'pipe', 'pipe'] });
  let stderr = '';
  chrome.stderr.on('data', d => { stderr += d.toString(); });
  let version = null;
  for (let i = 0; i < 80; i++) {
    try {
      const res = await fetch('http://127.0.0.1:' + port + '/json/list');
      if (res.ok) {
        const list = await res.json();
        if (list.length) { version = list; break; }
      }
    } catch (e) { /* not ready */ }
    await sleep(100);
  }
  if (!version) {
    chrome.kill('SIGKILL');
    throw new Error('Chrome did not start: ' + stderr.slice(-2000));
  }
  const target = version.find(t => t.type === 'page') || version[0];
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });
  const cdp = new CDP(ws);
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  await cdp.send('Log.enable');
  await cdp.send('Network.enable');
  await cdp.send('Emulation.setDeviceMetricsOverride', {
    width, height, deviceScaleFactor: 1, mobile: !!opts.mobile
  });
  await cdp.send('Page.navigate', { url: opts.url });
  await sleep(opts.settle || 1000);
  await cdp.eval('document.readyState');
  return {
    cdp, chrome, profile,
    async close() {
      try { ws.close(); } catch (e) {}
      try { chrome.kill('SIGTERM'); } catch (e) {}
      await sleep(200);
      try { fs.rmSync(profile, { recursive: true, force: true }); } catch (e) {}
    }
  };
}

module.exports = { CDP, launch, sleep };
