'use strict';
const path = require('path');
const { launch, sleep } = require('./cdp');
const fs = require('fs');

(async () => {
  const url = 'file://' + path.resolve(__dirname, '..', 'index.html');
  const { cdp, close } = await launch({ width: 1440, height: 900, url, settle: 1200 });
  try {
    const ready = await cdp.eval("({v: typeof window.VITARIUM, gen: window.VITARIUM && VITARIUM.state.gen, err: window.__err || null})");
    console.log('READY', JSON.stringify(ready));
    const consoleMsgs = cdp.console.slice(-20);
    console.log('CONSOLE', JSON.stringify(consoleMsgs, null, 2));
    console.log('EXCEPTIONS', JSON.stringify(cdp.exceptions, null, 2).slice(0, 4000));
    await cdp.eval('VITARIUM.suspend()');
    await sleep(200);
    await cdp.screenshot(path.join(__dirname, 'shot-initial.png'));
    await cdp.eval('VITARIUM.seek(165)');
    await sleep(500);
    await cdp.screenshot(path.join(__dirname, 'shot-mid.png'));
    await cdp.eval('VITARIUM.seek(480)');
    await sleep(2200);
    await cdp.screenshot(path.join(__dirname, 'shot-archive.png'));
    console.log('STATE', JSON.stringify(await cdp.eval('VITARIUM.state')));
    console.log('NETWORK', JSON.stringify([...new Set(cdp.network)]));
    console.log('CONSOLE2', JSON.stringify(cdp.console.slice(-20), null, 2));
    console.log('EXCEPTIONS2', JSON.stringify(cdp.exceptions.slice(-5), null, 2).slice(0, 4000));
  } finally {
    await close();
  }
})().catch(err => { console.error(err); process.exit(1); });
