{"command":"cd <WS1> && cat > _dev/debug-run.js <<'EOF'
'use strict';
const path=require('path'); const {launch,sleep}=require('./cdp');
(async()=>{
 const {cdp,close}=await launch({width:1440,height:900,url:'file://'+path.resolve(__dirname,'..','index.html'),settle:500});
 try{
   await cdp.eval('VITARIUM.suspend()');
   const d=await cdp.eval(`(()=>{
     const e=VITARIUM.engine;
     return {
       seed:e.seed, opts:e.opts, gen:e.gen,
       hist:e.history.slice(0,16).map(h=>({g:h.gen,p:h.counts.plant,h:h.counts.prey,c:h.counts.pred})),
       config:JSON.parse(JSON.stringify(VITARIUM.config)),
       counts:[e.plants.length,e.prey.length,e.preds.length],
       logs:e.logs.slice(0,4)
     };
   })()`);
   console.log(JSON.stringify(d,null,2));
   // now make a second fresh engine in the browser and step to 16 synchronously
   const d2=await cdp.eval(`(()=>{
     const Eco=window.VitariumCore.Ecosystem;
     const c=JSON.parse(JSON.stringify(VITARIUM.config));
     const e=new Eco({seed:c.seed, mutationRate:c.mutation, regrowth:c.regrowth, droughtEvery:c.events.drought.interval, plagueEvery:c.events.plague.interval, eclipseEvery:c.events.eclipse.interval, enableDrought:true, enablePlague:true, enableEclipse:true, migration:true});
     const hist=[];
     for(let g=0;g<16;g++){hist.push({g:e.gen,p:e.plants.length,h:e.prey.length,c:e.preds.length}); e.stepGeneration();}
     return {hist, opts:e.opts};
   })()`);
   console.log('FRESH', JSON.stringify(d2,null,2));
   console.log('CONSOLE',JSON.stringify(cdp.console)); console.log('EXC',JSON.stringify(cdp.exceptions).slice(0,2000));
 } finally { await close(); }
})().catch(e=>{console.error(e);process.exit(1)});
EOF
