{"file_path":"<WS1>/_dev/template.html","new_string":".event-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  margin-top: 2px;
}
.event {
  --ev: var(--drought);
  min-width: 0;
  padding: 0 9px;
  border-left: 1px solid var(--rule);
}
.event:first-child { padding-left: 0; border-left: 0; }
.event:last-child { padding-right: 0; }
.event-head { display: flex; align-items: center; gap: 5px; min-width: 0; }
.event-glyph { width: 13px; height: 13px; flex: none; color: var(--ev); opacity: 0.9; }
.event-name {
  font-size: 7.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.event[data-active="true"] .event-name { color: var(--ev); }
.event .switch { margin-left: auto; width: 23px; height: 13px; }
.event .switch::after { width: 4px; height: 4px; margin-top: -2px; left: 4px; }
.event .switch[aria-checked="true"]::after { left: 13px; }
.event-value {
  margin-top: 7px;
  font-size: 13px;
  line-height: 1;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.event-value .unit { font-size: 7px; color: var(--faint); margin-left: 3px; letter-spacing: 0.02em; }
.event-value.is-off { color: var(--faint); }
.event-row { margin-top: 4px; display: flex; align-items: center; gap: 0; }
.event-row .slider { --accent: var(--ev); height: 20px; }
.event .spark {
  width: 100%;
  height: 12px;
  flex: none;
  margin-top: 1px;
  opacity: 0.72;
}
.event-meta {
  display: flex;
  justify-content: flex-start;
  gap: 4px;
  margin-top: 2px;
  font-size: 7px;
  letter-spacing: 0.035em;
  color: var(--ghost);
  white-space: nowrap;
  overflow: hidden;
}
.event-meta .next-at { color: var(--faint); font-variant-numeric: tabular-nums; }
.event[data-active="true"] .event-meta .next-at { color: var(--ev); opacity: 0.86; }
.event[data-enabled="false"] .event-name,
.event[data-enabled="false"] .event-glyph { opacity: 0.4; }
.event[data-enabled="false"] .slider,
.event[data-enabled="false"] .spark { opacity: 0.28; }
.event[data-enabled="false"] .event-value { color: var(--faint); }
.event[data-active="true"] {
  background: linear-gradient(180deg, color-mix(in srgb, var(--ev) 6%, transparent), transparent 78%);
}
.event .slider-ticks { opacity: 0.5; }","old_string":".event { --ev: var(--drought); margin-top: 11px; padding-top: 10px; border-top: 1px solid var(--rule); }
