{"command":"cd <WS1> && cat > _dev/scan-seeds.js <<'EOF'
'use strict';
const path=require('path'); const {launch,sleep}=require('./cdp');
(async()=>{
 const {cdp,close}=await launch({width:1200,height:800,url:'file://'+path.resolve(__dirname,'..','index.html'),settle:600});
 try{
  await cdp.eval('VITARIUM.suspend()');
  const all=[];
  for(let start=1; start<=60; start+=12){
    const end=Math.min(60,start+11);
    const res=await cdp.eval(`(()=>{
      const Eco=window.VitariumCore.Ecosystem;
      const seeds=[${Array.from({length:end-start+1},(_,i)=>start+i).join(',')}];
      return seeds.map(seed=>{
        const e=new Eco({seed, droughtEvery:110, plagueEvery:150, eclipseEvery:190,
          enableDrought:true, enablePlague:true, enableEclipse:true, migration:true,
          mutationRate:0.025, regrowth:0.025});
        for(let g=0;g<480;g++) e.stepGeneration();
        const h=e.history;
        const seg=h.slice(60);
        const minH=Math.min(...seg.map(x=>x.counts.prey));
        const minC=Math.min(...seg.map(x=>x.counts.pred));
        const minP=Math.min(...seg.map(x=>x.counts.plant));
        const maxH=Math.max(...h.map(x=>x.counts.prey));
        const maxC=Math.max(...h.map(x=>x.counts.pred));
        const last=h[h.length-1];
        const ext=e.logs.filter(l=>l.kind==='extinct').length;
        const resc=e.logs.filter(l=>l.kind==='migration').length;
        const diff=arr=>arr.map((v,i)=>v===null?0:Math.abs(v-h[0].traits[seed?'x':'x'].mean[i])).reduce((a,b)=>a+b,0);
        const dprey=h[0].traits.prey.mean.map((v,i)=>Math.abs(last.traits.prey.mean[i]-v));
        const dpred=h[0].traits.pred.mean.map((v,i)=>Math.abs(last.traits.pred.mean[i]-v));
        const drift=Math.max(...dprey,...dpred);
        const variable=new Set(seg.map(x=>Math.round(x.counts.prey/80))).size+new Set(seg.map(x=>Math.round(x.counts.pred/20))).size;
        return {seed,final:last.counts,minP,minH,minC,maxH,maxC,ext,resc,drift:+drift.toFixed(2),variable,spans:e.spans.length};
      });
    })()`);
    all.push(...res);
    console.log('scanned',end);
  }
  const score=r=>{
    let s=0;
    if(r.final.prey>0 && r.final.pred>0) s+=20;
    if(r.ext===0) s+=15;
    if(r.resc===0) s+=5;
    if(r.final.pred>=15) s+=10; else if(r.final.pred>=5) s+=4;
    if(r.final.prey>=150) s+=10; else if(r.final.prey>=60) s+=5;
    if(r.final.plant>=1800&&r.final.plant<=4600) s+=8;
    if(r.minC>=8) s+=8;
    if(r.minH>=60) s+=5;
    if(r.drift>=.15) s+=8;
    if(r.variable>=10) s+=5;
    return s;
  };
  all.sort((a,b)=>score(b)-score(a));
  for(const r of all.slice(0,18)) console.log('SCORE',score(r),JSON.stringify(r));
  console.log('ALL', JSON.stringify(all));
 } finally { await close(); }
})().catch(e=>{console.error(e);process.exit(1)});
EOF
