'use strict';
const path=require('path'); const {launch}=require('./cdp');
(async()=>{
 const {cdp,close}=await launch({width:1200,height:800,url:'file://'+path.resolve(__dirname,'..','index.html'),settle:500});
 try{
  await cdp.eval('VITARIUM.suspend()');
  const res=await cdp.eval(`(()=>{
    const Eco=window.VitariumCore.Ecosystem;
    return [20,24,32,46,50,55,56].map(seed=>{
      const e=new Eco({seed, droughtEvery:110, plagueEvery:150, eclipseEvery:190, enableDrought:true, enablePlague:true, enableEclipse:true, migration:true, mutationRate:0.025, regrowth:0.025});
      for(let g=0;g<480;g++) e.stepGeneration();
      return {seed,hist:e.history.filter((_,i)=>i%40===0).map(x=>[x.gen,x.counts.plant,x.counts.prey,x.counts.pred]),
        preyMean:e.history[480].traits.prey.mean.map(v=>v?.toFixed(2)), predMean:e.history[480].traits.pred.mean.map(v=>v?.toFixed(2)),
        preySd:e.history[480].traits.prey.sd.map(v=>v?.toFixed(2)), predSd:e.history[480].traits.pred.sd.map(v=>v?.toFixed(2)),
        spans:e.spans.map(s=>s.type[0]+s.start).join(','), final:e.history[480].counts};
    });
  })()`);
  console.log(JSON.stringify(res,null,2));
 }finally{await close();}
})().catch(e=>{console.error(e);process.exit(1)});
EOF
