'use strict';
const path=require('path'); const {launch,sleep}=require('./cdp');
(async()=>{
 const url='file://'+path.resolve(__dirname,'..','index.html');
 const {cdp,close}=await launch({width:1440,height:900,url,settle:900});
 try{
   const state0=await cdp.eval('VITARIUM.state');
   console.log('state0',JSON.stringify(state0));
   // pause at a live drought window, then resume a moment so the dispatch is real
   await cdp.eval('VITARIUM.seek(108)');
   await sleep(150);
   await cdp.eval('VITARIUM.resume()');
   await sleep(360);
   await cdp.eval('VITARIUM.suspend()');
   await sleep(150);
   await cdp.screenshot(path.join(__dirname,'shot-event.png'));
   console.log('stateEvent',JSON.stringify(await cdp.eval('VITARIUM.state')));
   // fold the drawer
   await cdp.eval("document.getElementById('collapseBtn').click()");
   await sleep(450);
   await cdp.screenshot(path.join(__dirname,'shot-collapsed.png'));
   await cdp.eval("document.getElementById('expandBtn').click()");
   await sleep(350);
   // to 480 and archive
   await cdp.eval('VITARIUM.seek(480)');
   await sleep(2200);
   await cdp.screenshot(path.join(__dirname,'shot-archive2.png'));
   console.log('STATE',JSON.stringify(await cdp.eval('VITARIUM.state')));
   console.log('NET',JSON.stringify([...new Set(cdp.network)]));
   console.log('CONSOLE',JSON.stringify(cdp.console.slice(-20),null,2));
   console.log('EXC',JSON.stringify(cdp.exceptions.slice(-4),null,2).slice(0,3000));
 }finally{await close();}
})().catch(e=>{console.error(e);process.exit(1)});
EOF
