const path=require('path'), {launch,sleep}=require('./_dev/cdp');
(async()=>{
 const {cdp,close}=await launch({width:1440,height:900,url:'file://'+path.resolve('index.html'),settle:600});
 async function press(key,code,k,txt){await cdp.send('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:k,nativeVirtualKeyCode:k,text:txt||undefined,unmodifiedText:txt||undefined}); await cdp.send('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:k,nativeVirtualKeyCode:k}); await sleep(120);}
 try{
  await cdp.eval("document.body.tabIndex=-1; document.body.focus()");
