   await press('Tab','Tab',9);
   const info=await cdp.eval(`({id:document.activeElement.id, tag:document.activeElement.tagName, tip:document.getElementById('tip').classList.contains('show'), tipText:document.getElementById('tip').innerText.slice(0,60), fv:document.activeElement.matches(':focus-visible')})`);
   console.log(i,JSON.stringify(info));
