'use strict';
const path=require('path'); const {launch,sleep}=require('./cdp');
function assert(cond,msg){ if(!cond) throw new Error('ASSERT: '+msg); console.log('ok -',msg); }
(async()=>{
 const url='file://'+path.resolve(__dirname,'..','index.html');
 const {cdp,close}=await launch({width:1440,height:900,url,settle:800});
 async function key(key, code, keyCode, text){
   await cdp.send('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:keyCode,nativeVirtualKeyCode:keyCode,text:text||undefined,unmodifiedText:text||undefined});
   await cdp.send('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:keyCode,nativeVirtualKeyCode:keyCode});
   await sleep(90);
 }
 try{
   const init=await cdp.eval(`({state:VITARIUM.state, cfg:JSON.parse(JSON.stringify(VITARIUM.config))})`);
   console.log('INIT', JSON.stringify(init));
   assert(init.state.running===true,'auto-starts');
   assert(init.cfg.seed===56,'seed 56 default');

   // hover tooltip
   await cdp.eval(`(()=>{const e=document.getElementById('mutationSlider'); e.dispatchEvent(new PointerEvent('pointerover',{bubbles:true,pointerType:'mouse'}));})()`);
   await sleep(100);
   const tip=await cdp.eval("({shown:document.getElementById('tip').classList.contains('show'), text:document.getElementById('tip').innerText})");
   console.log('TIP', JSON.stringify(tip));
   assert(tip.shown && /Mutation rate/i.test(tip.text),'hover tooltip appears with mutation help');
   await cdp.eval(`document.getElementById('mutationSlider').dispatchEvent(new PointerEvent('pointerout',{bubbles:true,pointerType:'mouse'}))`);

   // keyboard slider via programmatic focus (keyboard path)
   await cdp.eval("document.getElementById('mutationSlider').focus()");
   const before=Number(await cdp.eval("document.getElementById('mutationSlider').getAttribute('aria-valuenow')"));
   await key('ArrowRight','ArrowRight',39);
   const after=Number(await cdp.eval("document.getElementById('mutationSlider').getAttribute('aria-valuenow')"));
   console.log('SLIDER', before,'->',after);
   assert(Math.abs(after-before-0.001)<1e-9,'arrow key changes mutation by 0.001');
   assert(Math.abs((await cdp.eval('VITARIUM.config.mutation')) - after)<1e-9,'config receives slider change');
   // restore
   await key('ArrowLeft','ArrowLeft',37);
   await cdp.eval("document.getElementById('mutationSlider').blur()");

   // actual Tab focus tooltip
   await cdp.eval("document.body.tabIndex=-1; document.body.focus()");
   await key('Tab','Tab',9);
   await sleep(100);
   const tabTip=await cdp.eval("({id:document.activeElement.id, tip:document.getElementById('tip').classList.contains('show'), title:(document.querySelector('#tip .tip-title')||{}).textContent, fv:document.activeElement.matches(':focus-visible')})");
   console.log('TAB TIP',JSON.stringify(tabTip));
   assert(tabTip.id==='collapseBtn' && tabTip.tip && tabTip.fv,'first Tab reaches a labeled control with tooltip and focus ring');

   // switch keyboard
   await cdp.eval("document.getElementById('tracesToggle').focus()");
   const tr0=await cdp.eval("document.getElementById('tracesToggle').getAttribute('aria-checked')");
   await key('Enter','Enter',13,'\r');
   const tr1=await cdp.eval("document.getElementById('tracesToggle').getAttribute('aria-checked')");
   assert(tr0!==tr1,'Enter toggles traces');
   await key('Enter','Enter',13,'\r');
   assert(tr0===await cdp.eval("document.getElementById('tracesToggle').getAttribute('aria-checked')"),'traces toggles back');

   // drawer fold and focus
   await cdp.eval("document.getElementById('collapseBtn').click()");
   await sleep(380);
   let fold=await cdp.eval(`({collapsed:document.getElementById('workspace').classList.contains('is-collapsed'), focus:document.activeElement && document.activeElement.id, inert:document.getElementById('drawerInner').inert, expanded:document.getElementById('collapseBtn').getAttribute('aria-expanded')})`);
   console.log('FOLD', JSON.stringify(fold));
   assert(fold.collapsed,'drawer collapses');
   assert(fold.focus==='expandBtn','focus moves to expand control');
   assert(fold.inert===true,'collapsed drawer is inert');
   assert(fold.expanded==='false','collapse control state updated');
   await cdp.screenshot(path.join(__dirname,'interaction-collapsed.png'));
   await cdp.eval("document.getElementById('expandBtn').click()");
   await sleep(380);
   fold=await cdp.eval(`({collapsed:document.getElementById('workspace').classList.contains('is-collapsed'), focus:document.activeElement && document.activeElement.id, inert:document.getElementById('drawerInner').inert})`);
   console.log('UNFOLD', JSON.stringify(fold));
   assert(!fold.collapsed && fold.focus==='collapseBtn' && fold.inert===false,'drawer expands and restores focus');

   // pause via body keyboard
   await cdp.eval("document.getElementById('pauseBtn').focus(); document.getElementById('pauseBtn').blur(); document.body.tabIndex=-1; document.body.focus()");
   const run0=(await cdp.eval('VITARIUM.state')).running;
   await key(' ','Space',32,' ');
   const run1=(await cdp.eval('VITARIUM.state')).running;
   assert(run0!==run1,'Space toggles the clock');
   await key(' ','Space',32,' ');
   assert((await cdp.eval('VITARIUM.state')).running===run0,'Space toggles back');

   // drought switch off/on and readouts
   await cdp.eval("document.getElementById('droughtSwitch').click()");
   await sleep(60);
   let drought=await cdp.eval(`({checked:document.getElementById('droughtSwitch').getAttribute('aria-checked'), nextAt:VITARIUM.engine.nextAt.drought, label:document.getElementById('droughtNext').textContent, enabled:VITARIUM.config.events.drought.enabled, active:document.getElementById('eventDrought').dataset.active})`);
   console.log('DROUGHT OFF',JSON.stringify(drought));
   assert(drought.checked==='false' && drought.enabled===false,'drought off state applies');
   assert(/off/i.test(drought.label),'drought row reads off');
   await cdp.eval("document.getElementById('droughtSwitch').click()");
   await sleep(60);
   drought=await cdp.eval(`({checked:document.getElementById('droughtSwitch').getAttribute('aria-checked'), nextAt:VITARIUM.engine.nextAt.drought, next:document.getElementById('droughtNext').textContent, enabled:VITARIUM.config.events.drought.enabled})`);
   console.log('DROUGHT ON',JSON.stringify(drought));
   assert(drought.checked==='true' && drought.enabled===true && Number.isFinite(drought.nextAt),'drought on reschedules');

   // active catastrophe chip after a headless seek
   await cdp.eval('VITARIUM.seek(112)');
   await sleep(120);
   const active=await cdp.eval(`({gen:VITARIUM.state.gen, chips:[...document.querySelectorAll('#headEvents .chip')].map(e=>e.innerText), active:[...VITARIUM.engine.active.keys()], eventRow:document.getElementById('eventDrought').dataset.active})`);
   console.log('ACTIVE',JSON.stringify(active));
   assert(active.gen===112 && active.active.includes('drought') && active.chips.some(t=>/drought/i.test(t)),'drought chip appears while active');
   assert(active.eventRow==='true','drought row marks active');

   // determinism (the config now includes a rescheduled drought from gen 112)
   await cdp.eval('VITARIUM.replay(); VITARIUM.seek(120)');
   const h1=await cdp.eval(`(()=>{const s=JSON.stringify(VITARIUM.engine.history); let h=0; for(let i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))|0;} return {hash:h, gen:VITARIUM.engine.gen, counts:VITARIUM.engine.history[120].counts};})()`);
   await cdp.eval('VITARIUM.replay(); VITARIUM.seek(120)');
   const h2=await cdp.eval(`(()=>{const s=JSON.stringify(VITARIUM.engine.history); let h=0; for(let i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))|0;} return {hash:h, gen:VITARIUM.engine.gen, counts:VITARIUM.engine.history[120].counts};})()`);
   console.log('DETERMINISM',JSON.stringify(h1),JSON.stringify(h2));
   assert(h1.hash===h2.hash && h1.gen===120,'same seed and settings reproduce history exactly');

   // a11y-ish checks
   const a11y=await cdp.eval(`(()=>{
     const sliders=[...document.querySelectorAll('[role=slider]')];
     const switches=[...document.querySelectorAll('[role=switch]')];
     return {
       sliders: sliders.map(s=>({id:s.id,name:s.getAttribute('aria-label')||s.getAttribute('aria-labelledby'),now:s.getAttribute('aria-valuenow'),text:s.getAttribute('aria-valuetext')})),
       switches: switches.map(s=>({id:s.id,name:s.getAttribute('aria-labelledby'),checked:s.getAttribute('aria-checked')})),
       dupIds: [...document.querySelectorAll('[id]')].map(e=>e.id).filter((id,i,a)=>a.indexOf(id)!==i),
       steppers: [...document.querySelectorAll('[role=spinbutton]')].map(e=>({id:e.id,label:e.getAttribute('aria-labelledby'),now:e.getAttribute('aria-valuenow')}))
     };
   })()`);
   console.log('A11Y',JSON.stringify(a11y,null,2));
   assert(a11y.sliders.every(s=>s.name && s.now!==null && s.text),'sliders named and valued');
   assert(a11y.switches.every(s=>s.name && s.checked!==null),'switches named and stateful');
   assert(a11y.steppers.every(s=>s.label && s.now!==null),'lifespan spinbutton named and valued');
   assert(a11y.dupIds.length===0,'no duplicate ids');

   console.log('NET',JSON.stringify([...new Set(cdp.network)]));
   console.log('EXC',JSON.stringify(cdp.exceptions));
   console.log('CONSOLE',JSON.stringify(cdp.console));
   assert(cdp.exceptions.length===0,'no runtime exceptions');
   const external=(new Set(cdp.network)).filter(u=>!u.startsWith('file:')&&!u.startsWith('data:'));
   assert(external.length===0,'no external network requests');
 } finally { await close(); }
})().catch(e=>{console.error(e);process.exit(1)});
