'use strict';
const fs=require('fs'); const path=require('path'); const {launch,sleep}=require('./cdp');
function assert(cond,msg){ if(!cond) throw new Error('ASSERT: '+msg); console.log('ok -',msg); }
(async()=>{
 const url='file://'+path.resolve(__dirname,'..','index.html');
 const downloadPath=path.resolve(__dirname,'downloads');
 const {cdp,close}=await launch({width:1440,height:900,url,settle:600});
 try{
   await cdp.send('Page.setDownloadBehavior',{behavior:'allow',downloadPath});
   // click headless close
   await cdp.eval("document.getElementById('headlessBtn').click()");
   await sleep(3000);
   const state=await cdp.eval(`({s:VITARIUM.state, counts:{p:VITARIUM.engine.plants.length,h:VITARIUM.engine.prey.length,c:VITARIUM.engine.preds.length}, stats:{span:document.getElementById('statSpan').innerText, plant:document.getElementById('statPlant').innerText, prey:document.getElementById('statPrey').innerText, pred:document.getElementById('statPred').innerText, dist:document.getElementById('statDist').innerText, shift:document.getElementById('statShift').innerText}, archive:{open:document.getElementById('archive').classList.contains('open'), hidden:document.getElementById('archive').hidden, inert:document.getElementById('shell').inert, focus:document.activeElement && document.activeElement.id, scroll:document.getElementById('archive').scrollTop}, cfg:JSON.parse(JSON.stringify(VITARIUM.config))})`);
   console.log('HEADLESS ARCHIVE',JSON.stringify(state,null,2));
   assert(state.s.complete===true && state.s.archiveOpen===true,'headless reaches archive');
   assert(state.archive.open && !state.archive.hidden && state.archive.inert===true,'archive visible and shell inert');
   assert(state.archive.focus==='archiveTitle','focus moves to archive title');
   assert(state.counts.p===3860 && state.counts.h===255 && state.counts.c===39,'headless final census matches the seeded run');
   assert(state.stats.plant==='3,860' && state.stats.prey==='255' && state.stats.pred==='39','dashboard stats populated');
   assert(state.stats.dist.startsWith('09'),'nine disturbance events counted');
   await cdp.screenshot(path.join(__dirname,'archive-final.png'));

   // hover population chart
   const r=await cdp.eval(`(()=>{const r=document.getElementById('popWrap').getBoundingClientRect(); return {x:r.x,y:r.y,w:r.width,h:r.height}})()`);
   await cdp.eval(`(()=>{const e=document.getElementById('popWrap'); const r=e.getBoundingClientRect(); e.dispatchEvent(new PointerEvent('pointermove',{bubbles:true,pointerType:'mouse',clientX:r.x+r.width*0.55,clientY:r.y+r.height*0.6}));})()`);
   await sleep(150);
   const hover=await cdp.eval(`({hidden:document.getElementById('popWrap').querySelector('.chart-tip')?.hidden, text:document.getElementById('popWrap').querySelector('.chart-tip')?.innerText})`);
   console.log('HOVER',JSON.stringify(hover));
   assert(hover.hidden===false && /GENERATION/.test(hover.text||''),'chart hover shows census readout');
   await cdp.screenshot(path.join(__dirname,'archive-hover.png'));

   // export CSV
   await cdp.eval("document.getElementById('exportBtn').click()");
   await sleep(900);
   const files=fs.readdirSync(downloadPath).filter(f=>f.endsWith('.csv'));
   console.log('CSV FILES',files);
   assert(files.length===1,'CSV export creates one file');
   const content=fs.readFileSync(path.join(downloadPath,files[0]),'utf8');
   const lines=content.trim().split('\n');
   console.log('CSV head',lines[0].slice(0,220));
   assert(lines.length===481,'CSV has one header plus 480 generation rows');
   assert(/virens/.test(lines[0]) && /lepus_speed_mean/.test(lines[0]) && /vulpes_repro_threshold_sd/.test(lines[0]),'CSV includes all species and gene statistics');
   assert(lines[480].startsWith('480,'),'CSV ends at generation 480');

   // replay from archive
   await cdp.eval("document.getElementById('replayBtn').click()");
   await sleep(450);
   const after=await cdp.eval(`({s:VITARIUM.state, open:document.getElementById('archive').classList.contains('open'), hidden:document.getElementById('archive').hidden, inert:document.getElementById('shell').inert, focus:document.activeElement && document.activeElement.id, seed:VITARIUM.config.seed, span:document.querySelector('.specimen .sp-count').textContent})`);
   console.log('REPLAY',JSON.stringify(after));
   assert(after.s.complete===false && after.s.running===true,'replay resumes a fresh run');
   assert(after.open===false && after.hidden===true && after.inert===false,'archive closes and shell is interactive');
   assert(after.seed===56,'replay keeps the seed');
   console.log('NET',JSON.stringify([...new Set(cdp.network)]));
   console.log('EXC',JSON.stringify(cdp.exceptions));
   console.log('CONSOLE',JSON.stringify(cdp.console));
   assert(cdp.exceptions.length===0,'no runtime exceptions');
   const external=[...new Set(cdp.network)].filter(u=>!u.startsWith('file:')&&!u.startsWith('data:'));
   assert(external.length===0,'no external network requests');
 } finally { await close(); }
})().catch(e=>{console.error(e);process.exit(1)});
EOF
