(async()=>{
 const {cdp,close}=await launch({width:390,height:844,url:'file://'+path.resolve(__dirname,'..','index.html'),mobile:true,settle:900});
 try{
   await cdp.eval('VITARIUM.suspend()');
   await sleep(200);
   await cdp.eval('window.scrollTo(0,0)');
   await cdp.screenshot(path.join(__dirname,'m2-top.png'));
   console.log('dims',await cdp.eval(`({inner:[innerWidth,innerHeight],scrollW:document.documentElement.scrollWidth,stage:document.getElementById('stage').getBoundingClientRect().toJSON(),drawer:document.querySelector('.drawer').getBoundingClientRect().toJSON(),drawerBody:[document.querySelector('.drawer-body').clientHeight,document.querySelector('.drawer-body').scrollHeight]})`));
   // scroll to drawer
   const y=await cdp.eval(`document.querySelector('.drawer').getBoundingClientRect().top + scrollY - 20`);
   await cdp.eval(`window.scrollTo(0,${Math.max(0,y)})`);
   await sleep(200);
   await cdp.screenshot(path.join(__dirname,'m2-drawer.png'));
   // headless close
   await cdp.eval("document.getElementById('headlessBtn').click()");
   await sleep(2600);
   await cdp.eval('document.getElementById("archive").scrollTo(0,0)');
   await sleep(200);
   await cdp.screenshot(path.join(__dirname,'m2-archive-top.png'));
   const arch=await cdp.eval(`(()=>{const a=document.getElementById('archive'); return {scrollW:document.documentElement.scrollWidth, innerW:innerWidth, archScrollW:a.scrollWidth, archClientW:a.clientWidth, archH:a.scrollHeight, innerH:a.clientHeight, focus:document.activeElement.id, bodyClass:document.body.className};})()`);
   console.log('ARCH',JSON.stringify(arch));
   await cdp.eval("document.getElementById('archive').scrollTo(0,900)");
   await sleep(250);
   await cdp.screenshot(path.join(__dirname,'m2-archive-mid.png'));
   await cdp.eval("document.getElementById('archive').scrollTo(0,2600)");
   await sleep(250);
   await cdp.screenshot(path.join(__dirname,'m2-archive-end.png'));
   console.log('EXC',JSON.stringify(cdp.exceptions),'CONSOLE',JSON.stringify(cdp.console));
 } finally { await close(); }
})().catch(e=>{console.error(e);process.exit(1)});
EOF
