'use strict';
const path=require('path'); const {launch,sleep}=require('./cdp');
function assert(cond,msg){ if(!cond) throw new Error('ASSERT: '+msg); console.log('ok -',msg); }
(async()=>{
 const url='file://'+path.resolve(__dirname,'..','index.html');
 const {cdp,close}=await launch({width:1440,height:900,url,settle:500});
 async function press(key,code,k){await cdp.send('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:k,nativeVirtualKeyCode:k}); await cdp.send('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:k,nativeVirtualKeyCode:k}); await sleep(100);}
 try{
   await cdp.eval('VITARIUM.suspend()');
   // set lifespan to 100 while paused
   for(let i=0;i<8;i++) await cdp.eval("document.getElementById('spanMinus').click()");
   let d=await cdp.eval(`({span:document.getElementById('spanValue').textContent, aria:document.getElementById('spanRead').getAttribute('aria-valuenow'), next:document.getElementById('spanSpark').width})`);
   console.log('SPAN',JSON.stringify(d));
   assert(d.span==='100' && d.aria==='100','lifespan stepper lowers to 100');
   // tempo via End on dial
   await cdp.eval("document.getElementById('tempoDial').focus()");
   await press('End','End',35);
   d=await cdp.eval(`({tempo:document.getElementById('tempoValue').textContent, aria:document.getElementById('tempoDial').getAttribute('aria-valuenow'), eta:document.getElementById('tempoEta').innerText, cfg:VITARIUM.config.tempo})`);
   console.log('TEMPO',JSON.stringify(d));
   assert(d.tempo==='40.0' && d.cfg===40 && d.aria==='40','End sets tempo to 40');
   // resume via the control and wait for the automatic close
