/* ------------------------------------------------------------------ */
/* Keyboard, resize, loop                                             */
/* ------------------------------------------------------------------ */

function setupKeyboard() {
  document.addEventListener('keydown', e => {
    if (e.defaultPrevented || e.metaKey || e.ctrlKey || e.altKey) return;
    if (state.archiveOpen) return;
    const t = e.target;
    const typing = t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' ||
      (t.closest && t.closest('[role="slider"], [role="spinbutton"], button')));
    if (e.code === 'Space' && !typing && !state.fastForward && !state.complete) {
      e.preventDefault();
      setRunning(!state.running);
      return;
    }
    if (typing || state.fastForward || state.complete) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); headlessFinish(); }
    else if (e.key === 'r' || e.key === 'R') { e.preventDefault(); startRun(); }
    else if (e.key === 'n' || e.key === 'N') {
      e.preventDefault();
      config.seed = deriveSeed(config.seed);
      startRun();
    } else if (e.key === 'i' || e.key === 'I') {
      e.preventDefault();
      foldDrawer(!dom.workspace.classList.contains('is-collapsed'));
    }
  });
}

function setupResize() {
  let resizeTimer = 0;
  const redraw = () => {
    hideTip();
    drawAllSparks();
    updateDrawerHint();
    if (state.archiveOpen) {
      drawAllCharts();
      if (chartTipEl) chartTipEl.hidden = true;
      state.chartHover = null;
    }
    renderer.invalidate();
  };
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(redraw, 120);
  });
}

function loop(now) {
  rafId = requestAnimationFrame(loop);
  if (!state.lastTime) state.lastTime = now;
  let dt = now - state.lastTime;
  state.lastTime = now;
  if (dt < 0) dt = 0;
  dt = Math.min(dt, 64);
  if (state.running && !state.complete && !state.fastForward && state.engine) {
    state.acc += (dt / 1000) * config.tempo;
    let steps = 0;
    while (state.acc >= 1 && steps < 8 && !state.complete) {
      state.engine.stepGeneration();
      state.acc -= 1;
      steps++;
      if (state.engine.gen >= config.runLength) {
        state.acc = 0;
        finishRun(false);
        break;
      }
    }
    if (steps > 0) {
      processLogs(true);
      updateLive(true);
      renderer.invalidate();
    }

    cacheDom();
    buildTraitTable();
    renderer = makeRenderer(dom.field);
    initializeControls();
    setupTooltips();
    attachPopHover();
    setupKeyboard();
    setupResize();
    startRun();
    if (!dom.archive.classList.contains('open')) dom.archive.hidden = true;
    requestAnimationFrame(now => {
      state.lastTime = now;
      loop(now);
    });
    try {
      window.VITARIUM = {
        get engine() { return state.engine; },
        get config() { return config; },
        get state() { return { gen: state.engine ? state.engine.gen : 0, running: state.running, complete: state.complete, archiveOpen: state.archiveOpen }; },
        seek: publicSeek,
        finish: () => finishRun(false),
        resume: () => setRunning(true),
        suspend: () => setRunning(false),
        replay: () => startRun(),
        seed: function (n) {
          const v = parseInt(n, 10);
          if (Number.isFinite(v)) { config.seed = clamp(v, 1, 999999); startRun(); }
        },
        snapshot: () => state.engine ? state.engine.snapshot() : null,
        exportCSV
      };
    } catch (err) { /* console API is a convenience, not a dependency */ }
  }

  init();
})();

