const path=require('path'); const {launch,sleep}=require('./cdp');
(async()=>{
 const url='file://'+path.resolve(__dirname,'..','index.html');
 const {cdp,close}=await launch({width:1440,height:900,url,settle:700});
 try{
  await cdp.eval('VITARIUM.seek(220); VITARIUM.resume();');
  await sleep(300);
  const metrics=await cdp.eval(`new Promise(resolve=>{
    let frames=0; const start=performance.now(); let last=start; let worst=0; let over32=0;
    function tick(now){ frames++; const dt=now-last; last=now; if(dt>worst) worst=dt; if(dt>32) over32++; if(now-start<2500) requestAnimationFrame(tick); else resolve({frames, ms:now-start, fps:frames/((now-start)/1000), worst, over32, counts:[VITARIUM.engine.plants.length,VITARIUM.engine.prey.length,VITARIUM.engine.preds.length], gen:VITARIUM.engine.gen}); }
    requestAnimationFrame(tick);
  })`);
  console.log('PERF',JSON.stringify(metrics));
  await cdp.send('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});
  await cdp.eval("VITARIUM.suspend(); VITARIUM.seek(120); VITARIUM.finish();");
  await sleep(1800);
  const media=await cdp.eval(`({reduce:matchMedia('(prefers-reduced-motion: reduce)').matches, open:document.getElementById('archive').classList.contains('open'), reveal:document.getElementById('archive').classList.contains('reveal'), clip:getComputedStyle(document.getElementById('popChart')).clipPath, focus:document.activeElement.id})`);
  console.log('REDUCED',JSON.stringify(media));
  console.log('EXC',JSON.stringify(cdp.exceptions));
 }finally{await close();}
})().catch(e=>{console.error(e);process.exit(1)});
EOF
