'use strict';
const path=require('path'); const {launch,sleep}=require('./cdp');
(async()=>{
 const url='file://'+path.resolve(__dirname,'..','index.html');
 const {cdp,close}=await launch({width:1440,height:900,url,settle:600});
 try{
  await cdp.eval('VITARIUM.seek(108)');
  await sleep(100);
  await cdp.eval('VITARIUM.resume()');
  await sleep(420);
  await cdp.eval('VITARIUM.suspend()');
  await sleep(160);
  await cdp.screenshot(path.join(__dirname,'final-event.png'));
  console.log('live',JSON.stringify(await cdp.eval(`({state:VITARIUM.state, drawerHint:document.getElementById('drawerMore').hidden, body:[document.querySelector('.drawer-body').clientHeight,document.querySelector('.drawer-body').scrollHeight], buttons:[...document.querySelectorAll('.drawer-actions .btn')].map(e=>e.innerText), range:document.querySelector('.sec-note').innerText, actionsBottom:document.querySelector('.drawer-actions').getBoundingClientRect().bottom})`)));
  await cdp.eval('VITARIUM.seek(480)');
  await sleep(2200);
  await cdp.screenshot(path.join(__dirname,'final-archive.png'));
  console.log('archive',JSON.stringify(await cdp.eval(`({focus:document.activeElement.id, exceptions:0})`)));
  console.log('EXC',JSON.stringify(cdp.exceptions));
  console.log('CONSOLE',JSON.stringify(cdp.console));
 }finally{await close();}
})().catch(e=>{console.error(e);process.exit(1)});
EOF
